const MAINS_PRESET = [{"name":"GS I","subjects":[{"name":"Art and Culture","chapters":[{"id":"p1","name":"Dance forms","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","Discuss the Tandava dance as recorded in the early Indian inscriptions."]]},{"id":"p2","name":"Conservation of Indian Art & Heritage","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","Safeguarding the Indian art heritage is the need of the moment. Discuss."]]},{"id":"p3","name":"Bhakti and Sufi movement","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Evaluate the nature of the Bhakti literature and its contribution to Indian culture."],["2018","15","The Bhakti movement received a remarkable re-orientation with the advent of Sri Chaitanya Mahaprabhu. Discuss."],["2014","10","Sufis and medieval mystic saints failed to modify either the religious ideas and practices or the outward structure of Hindu/Muslim societies to any appreciable extent. Comment."]]},{"id":"p4","name":"Buddhism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","10","Highlight the Central Asian and Greco -Bactrian elements in Gandhara art."],["2016","12.5","Early Buddhist Stupa-art, while depicting folk motifs and narratives successfully expounds Buddhist ideals. Elucidate."],["2014","10","Gandhara sculpture owed as much to the Romans as to the Greeks. Explain."]]},{"id":"p5","name":"Civilizations & Highlights","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Discuss the salient features of the Harappan architecture."],["2024","10","Underline the changes in the field of society and economy from the Rig Vedic to the later Vedic period."],["2023","15","What are the main features of Vedic society and religion? Do you think some of the features are still prevailing in Indian society?"],["2015","12.5","The ancient civilization in Indian sub-continent differed from those of Egypt, Mesopotamia and Greece in that its culture and traditions have been preserved without a breakdown to the present day. Comment."],["2014","10","To what extent has the urban planning and culture of the Indus Valley Civilization provided inputs to the present day urbanization? Discuss."]]},{"id":"p6","name":"Indian Philosophy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","15","Indian philosophy and tradition played a significant role in conceiving and shaping the monuments and their art in India. Discuss."]]},{"id":"p7","name":"Kingdoms & Highlights","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","‘The sculptors filled the Chandella artform with resilient vigor and breadth of life.’ Elucidate."],["2024","10","Estimate the contribution of Pallavas of Kanchi for the development of art and literature of South India."],["2024","15","“Though the great Cholas are no more yet their name is still remembered with great pride because of their highest achievements in the domain of art and architecture.” Comment."],["2023","15","What were the major technological changes introduced during the Sultanate period? How did those technological changes influence the Indian society?"],["2022","15","Discuss the main contributions of Gupta period and Chola period to Indian heritage and culture."],["2020","10","Pala period is the most significant phase in the history of Buddhism in India. Enumerate."],["2017","10","How do you justify the view that the level of excellence of Gupta numismatic art is not at all noticeable in later times?"],["2013","10","Chola architecture represents a high watermark in the evolution of temple architecture. Discuss."]]},{"id":"p8","name":"Kings & Contributions","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Examine the main aspects of Akbar’s religious syncretism."],["2016","12.5","Krishnadeva Raya, the King of Vijayanagar, was not only an accomplished scholar himself but was also a great patron of learning and literature. Discuss."]]},{"id":"p9","name":"Miscellaneous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","Explain the role of geographical factors towards the development of Ancient India."],["2014","10","Taxila university was one of the oldest universities of the world with which were associated a number of renowned learned personalities of different disciplines. Its strategic location caused its fame to flourish, but unlike Nalanda, it is not considered as a university in the modern sense. Discuss."]]},{"id":"p10","name":"Travellers","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","Assess the importance of the accounts of the Chinese and Arab travellers in the reconstruction of the history of India."]]},{"id":"p11","name":"Sculptures and Significance","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","How will you explain that medieval Indian temple sculptures represent the social life of those days?"],["2022","15","Discuss the significance of the lion and bull figures in Indian mythology, art and architecture."]]},{"id":"p12","name":"Rock-cut Architecture as Historical Sources","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","The rock-cut architecture represents one of the most important sources of our knowledge of early Indian art and history. Discuss."],["2015","12.5","Mesolithic rock cut architecture of India not only reflects the cultural life of the times but also a tine aesthetic sense comparable to modern painting. Critically evaluate this comment."]]},{"id":"p13","name":"Literature as Historical Sources","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","15","Persian literary sources of medieval India reflect the spirit of the age. Comment."],["2013","10","Though not very useful from the point of view of a connected political history of South India, the Sangam literature portrays the social and economic conditions of its time with remarkable vividness. Comment."]]}]},{"name":"Modern History","chapters":[{"id":"p14","name":"Colonial rule and impact","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","How did the colonial rule affect the tribals in India and what was the tribal response to the colonial oppression?"],["2022","10","Why did the armies of the British East India Company - mostly comprising of Indian soldiers-win consistently against the more numerous and better equipped armies of the then Indian rulers ? Give reasons."],["2022","10","Why was there a sudden spurt in famines in colonial India since the mid-eighteenth century ? Give reasons."],["2017","15","Examine how the decline of traditional artisanal industry in colonial India crippled the rural economy."],["2014","10","Examine critically the various facets of economic policies of the British in India from mid-eighteenth century till independence."]]},{"id":"p15","name":"Gandhi X Indian Leaders of Freedom Struggle","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","What was the difference between Mahatma Gandhi and Rabindranath Tagore in their approach towards education and nationalism?"],["2018","10","Throw light on the significance of the thoughts of Mahatma Gandhi in the present times."],["2016","12.5","Highlight the differences in the approach of Subhash Chandra Bose and Mahatma Gandhi in the struggle for freedom."],["2015","12.5","How different would have been the achievement of Indian independence without Mahatma Gandhi? Discuss."],["2015","12.5","Mahatma Gandhi and Dr. B.R. Ambedkar, despite having divergent approaches and strategies, had a common goal of amelioration of the downtrodden. Elucidate."]]},{"id":"p16","name":"Revolt and Mutiny","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","10","The 1857 Uprising was the culmination the recurrent big and small local rebellions that had occurred in the preceding hundred years of British rule. Elucidate."],["2017","10","Clarify how mid-eighteenth century India was beset with the spectre of a fragmented polity."],["2016","12.5","Explain how the Uprising of 1857 constitutes an important watershed in the evolution of British policies towards colonial India."],["2014","10","In what ways did the naval mutiny prove to be the last nail in the coffin of British colonial aspirations in India?"],["2014","10","The third battle of Panipat was fought in 1761. Why were so many empire-shaking battles fought at Panipat?"]]},{"id":"p17","name":"Socio-religious reform","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Mahatma Jotirao Phule’s writings and efforts of social reforms touched issues of almost all subaltern classes. Discuss."],["2021","10","Trace the rise and growth of socio-religious reform movements with special reference to Young Bengal and Brahmo Samaj."],["2017","15","The women’s questions arose in modern India as a part of the 19th century social reform movement. What were the major issues and debates concerning women in that period?"]]},{"id":"p18","name":"Viceroy and their Administration","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","Evaluate the policies of Lord Curzon and their long term implications on the national movement."],["2013","10","In many ways, Lord Dalhousie was the founder of modern India. Elaborate."]]},{"id":"p19","name":"Acts and their Features","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","It would have been difficult for the Constituent Assembly to complete its historic task of drafting the Constitution for Independent India in just three years but for the experience gained with the Government of India Act, 1935. Discuss."]]},{"id":"p20","name":"Important contributors/contribution","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","Why did the ‘Moderates’ fail to carry conviction with the nation about their proclaimed ideology and political goals by the end of the nineteenth century?"],["2017","15","Highlight the importance of the new objectives that got added to the vision of Indian independence since twenties of the last century."],["2016","12.5","Discuss the role of women in the freedom struggle especially during the Gandhian phase."],["2013","10","Several foreigners made India their homeland and participated in various movements. Analyze their role in the Indian struggle for freedom."]]},{"id":"p21","name":"Various stages of Freedom struggle","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What were the events that led to the Quit India Movement? Point out its results."],["2021","15","Bring out the constructive programmes of Mahatma Gandhi during Non-Cooperation Movement and Civil Disobedience Movement."],["2019","15","Many voices had strengthened and enriched the nationalist movement during the Gandhian phase. Elaborate."],["2019","15","Assess the role of British imperial power in complicating the process of transfer of power during the 1940s."],["2019","10","Examine the linkages between 19th centuries ‘Indian Renaissance’ and the emergence of national identity."]]}]},{"name":"Post Independence","chapters":[{"id":"p22","name":"Foreign influence on Independent India’s policies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","10","The New Economic Policy - 1921 of Lenin had influenced the policies adopted by India soon after independence. Evaluate."]]},{"id":"p23","name":"Land reform","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","Critically discuss the objectives of Bhoodan and Gramdan movements initiated by Acharya Vinoba Bhave and their success."]]},{"id":"p24","name":"Personalities Contribution","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","Discuss the contribution of Maulana Abul Kalam Azad to pre-and post-independent India."]]},{"id":"p25","name":"Slogan based","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","Write a critical note on the evolution and significance of the slogan “Jai Jawana Jai Kisan”."]]},{"id":"p26","name":"States Reorganistion","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","The political and administrative reorganization of states and territories has been a continuous ongoing process since the mid-nineteenth century. Discuss with examples."],["2018","15","Discuss whether formation of new states in recent times is beneficial or not for the economy of India."],["2016","12.5","Has the formation of linguistic States strengthened the cause of Indian Unity?"]]},{"id":"p27","name":"Consolidation after Independence","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Trace India’s consolidation process during early phase of independence in terms of polity, economy, education and international relations."],["2021","10","Assess the main administrative issues and socio-cultural problems in the integration process of Indian Princely States."]]},{"id":"p28","name":"Wars after Independence","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","Analyze the circumstances that led to Tashkent Agreement in 1966. Discuss the highlights of the agreement."],["2013","10","Critically examine the compulsions which prompted India to play a decisive roles in the emergence of Bangladesh."]]}]},{"name":"World History","chapters":[{"id":"p29","name":"American and French revolution","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","The French Revolution has enduring relevance to the contemporary world. Explain."],["2019","15","Explain how the foundations of the modern world were laid by the American and French revolution."],["2013","10","American Revolution was an economic revolt against mercantilism. Substantiate."]]},{"id":"p30","name":"Anti-colonial struggles","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","What problems were germane to the decolonization process of Malay Peninsula."],["2016","12.5","The anti-colonial struggles in West Africa were led by the new elite of Western-educated Africans. Examine."],["2014","10","What were the major political, economic and social developments in the world which motivated the anti-colonial struggle in India?"],["2013","10","Africa was chopped into states artificially created by accident of European competition. Analyse."]]},{"id":"p31","name":"Great Economic Depression","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","What policy instruments were deployed to contain the great economic depression?"]]},{"id":"p32","name":"Industrial Revolution","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","How far was the Industrial Revolution in England responsible for the decline of handicrafts and cottage industries in India?"],["2015","12.5","Why did the industrial revolution first occur in England? Discuss the quality of life of the people there during the industrialization. How does it compare with that in India at present?"],["2013","10","Latecomer Industrial revolution in Japan involved certain factors that were markedly different from what west had experience."]]},{"id":"p33","name":"Miscellaneous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","Bring out the socio-economic effects of the introduction of railways in different countries of the world."],["2018","15","Why indentured labour was taken by the British from India to other colonies? Have they been able to preserve their cultural identity over there?"],["2014","10","What were the events that led to the Suez Crisis in 1956? How did it deal a final blow to Britain’s self-image as a world power?"]]},{"id":"p34","name":"World wars","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","How far is it correct to say that the First World War was fought essentially for the preservation of balance of power?"],["2021","15","“There arose a serious challenge to the Democratic State System between the two World Wars.” Evaluate the statement. (250 words)"],["2015","12.5","To what extent can Germany be held responsible for causing the two World Wars? Discuss critically"]]}]},{"name":"Society","chapters":[{"id":"p35","name":"Diversity and pluralism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","What is regional disparity? How does it differ from diversity? How serious is the issue of regional disparity in India?"],["2024","15","Critically analyse the proposition that there is a high correlation between India’s cultural diversities and socio-economic marginalities."],["2022","15","Analyse the salience of ‘sect’ in Indian society vis-a-vis caste, region and religion."],["2019","15","Do we have cultural pockets of small India all over the nation? Elaborate with examples."],["2017","10","In the context of diversity of India, can it be said that the regions form cultural units rather than the States? Give reasons with examples for your viewpoint."],["2015","12.5","Describe any four cultural elements of diversity in India and rate their relative significance in building a national identity."]]},{"id":"p36","name":"Tribes & Related Issues","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Does tribal development in India centre around two axes, those of displacement and of rehabilitation? Give your opinion."],["2022","10","Given the diversities among tribal communities in India, in which specific contexts should they be considered as a single category ?"],["2021","10","Examine the uniqueness of tribal knowledge system when compared with mainstream knowledge and cultural systems."],["2015","12.5","How do you explain the statistics that show that the sex ratio in Tribes in India is more favourable to women than the sex ratio among Scheduled Castes?"]]},{"id":"p37","name":"Family","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Intercaste marriages between castes which have socio-economic parity have increased, to some extent, but this is less true of interreligious marriages. Discuss."],["2023","10","Child cuddling is now being replaced by mobile phones. Discuss its impact on the socialization of children."],["2023","10","Do you think marriage as a sacrament in losing its value in Modern India?"],["2022","10","Explore and evaluate the impact of ‘Work From Home’ on family relationships."],["2014","10","The life cycle of a joint family depends on economic factors rather than social values. Discuss."]]},{"id":"p38","name":"Uniqueness of Indian society","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","15","How does Indian society maintain continuity in traditional social values? Enumerate the changes taking place in it."],["2019","10","What makes Indian society unique in sustaining its culture? Discuss."],["2017","15","The spirit tolerance and love is not only an interesting feature of Indian society from very early times, but it is also playing an important part at the present. Elaborate."]]},{"id":"p39","name":"Population and associated issues","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What is the concept of a ‘demographic winter’? Is the world moving towards such a situation? Elaborate."],["2023","15","Why did human development fail to keep pace with economic development in India?"],["2021","15","Discuss the main objectives of Population Education and point out the measures to achieve them in India in detail."],["2015","12.5","Critically examine whether growing population is the cause of poverty OR poverty is the main cause of population increase in India."],["2015","12.5","Discuss the changes in the trends of labour migration within and outside India in the last four decades."]]},{"id":"p40","name":"Poverty and Related issues","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","COVID-19 pandemic accelerated class inequalities and poverty in India. Comment."],["2018","10","Despite implementation of various programmes for eradication of poverty by the government in India, poverty is still existing.’ Explain by giving reasons."],["2016","12.5","An essential condition to eradicate poverty is to liberate the poor from deprivation. Substantiate this statement with suitable examples"]]},{"id":"p41","name":"Development and Related issues","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","‘Achieving sustainable growth with emphasis on environmental protection could come into conflict with poor people’s needs in a country like India – Comment."],["2024","10","In dealing with socio-economic issues of development, what kind of collaboration between government, NGO’s and private sector would be most productive?"],["2021","15","What is Cryptocurrency? How does it affect global society? Has it been affecting Indian society also? (250 words)"],["2020","15","How have digital initiatives in India contributed to the functioning of the educational system in the country? Elaborate your answer."]]},{"id":"p42","name":"Women and Associated concerns","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Distinguish between gender equality, gender equity and women’s empowerment. Why is it important to take gender concerns into account in programme design and implementation?"],["2023","10","Explain why suicide among young women is increasing in Indian Society."],["2021","10","Examine the role of ‘Gig Economy’ in the process of empowerment of women in India."],["2019","10","“Empowering women is the key to control population growth”. Discuss"],["2019","15","What are the continued challenges for women in India against time and space?"],["2018","15","Women’s movement in India has not addressed the issues of women of lower social strata. Substantiate your view."],["2014","10","Discuss the various economic and socio-cultural forces that are driving increasing feminization of agriculture in India."],["2014","10","How does patriarchy impact the position of a middle class working woman in India?"],["2014","10","Why do some of the most prosperous regions of India have an adverse sex ratio for women? Give your arguments."],["2013","10","Male membership needs to be encouraged in order to make women’s organization free from gender bias. Comment."]]},{"id":"p43","name":"Urban Water Management","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","What are the environmental implications of the reclamation of water bodies into urban land use? Explain with examples."],["2020","15","Account for the huge flooding of million cities in India including the smart ones like Hyderabad and Pune. Suggest lasting remedial measures."],["2016","12.5","Major cities of India are becoming more vulnerable to flood conditions. Discuss."]]},{"id":"p44","name":"Environmental Issues","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","5","Bring out the causes for the formation of heat islands in the urban habitat of the world."]]},{"id":"p45","name":"Urban Planning","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","15","How is efficient and affordable urban mass transport key to the rapid economic development of India?"],["2018","15","Mention core strategies for the transformation of aspirational districts in India and explain the nature of convergence, collaboration and competition for its success."],["2016","12.5","With a brief background of quality of urban life in India, introduce the objectives and strategy of the ‘Smart City Programme’."],["2015","12.5","Smart cities in India cannot sustain without smart villages. Discuss this statement in the backdrop of rural urban integration."]]},{"id":"p46","name":"Urban Poverty and Migration","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","How does smart city in India, address the issues of urban poverty and distributive justice?"],["2024","10","Why do large cities tend to attract more migrants than smaller towns? Discuss in the light of conditions in developing countries."],["2023","15","Does urbanization lead to more segregation and/or marginalization of the poor in Indian metropolises?"]]},{"id":"p47","name":"Emerging Urbanisation Trends","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","How is the growth of Tier 2 cities related to the rise of a new middle class with an emphasis on the culture of consumption?"],["2021","15","What are the main socio-economic implications arising out of the development of IT industries in major cities of India? (250 words)"],["2017","15","The growth of cities as I.T. hubs has opened up new avenues employment but has also created new problems. Substantiate this statement with examples."],["2013","10","Discussion the various social problems which originated out of the speedy process of urbanization in India."]]},{"id":"p48","name":"Globalisation","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Do you think that globalization results in only an aggressive consumer culture?"],["2025","15","How do you account for the growing fast food industries given that there are increased health concerns in modern society? Illustrate your answer with the Indian experience."],["2024","15","Globalization has increased urban migration by skilled, young, unmarried women from various classes. How has this trend impacted upon their personal freedom and relationship with family?"],["2022","15","Elucidate the relationship between globalization and new technology in a world of scarce resources, with special reference to India."],["2020","15","Is diversity and pluralism in India under threat due to globalisation? Justify your answer."],["2019","15","Are we losing our local identity for the global identity? Discuss. (15m,250 words)"],["2018","15","Globalization is generally said to promote cultural homogenization but due to this cultural specificities appear to be strengthened in the Indian Society. Elucidate."],["2016","12.5","To what extent globalization has influenced the core of cultural diversity in India? Explain."],["2015","12.5","Discuss the positive and negative effects of globalization on women in India."],["2013","10","Critically examine the effects of globalization on the aged population in India."]]},{"id":"p49","name":"Caste system","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Why is caste identity in India both fluid and static?"],["2020","10","Has caste lost its relevance in understanding the multi-cultural Indian Society? Elaborate your answer with illustrations."],["2018","10","Caste system is assuming new identities and associational forms. Hence, caste system cannot be eradicated in India. Comment."]]},{"id":"p50","name":"Communalism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Discuss the impact of post-liberal economy on ethnic identity and communalism."],["2018","15","Communalism arises either due to power struggle or relative deprivation. Argue by giving suitable illustrations."],["2017","15","Distinguish between religiousness/religiosity and communalism giving one example of how the former has got transformed into the latter in independent India."]]},{"id":"p51","name":"Miscellaneous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","The ethos of civil service in India stand for the combination of professionalism with nationalistic consciousness – Elucidate."],["2020","15","Customs and traditions suppress reason leading to obscurantism. Do you agree?"]]},{"id":"p52","name":"Regionalism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","Do you agree that regionalism in India appears to be a consequence of rising cultural assertiveness? Argue."],["2016","12.5","What is the basis of regionalism? Is it that unequal distribution of benefits of development on regional basis eventually promotes regionalism? Substantiate your answer."],["2013","10","Growing feeling of regionalism is an important factor in the generation of demand for a separate state. Discuss."]]},{"id":"p53","name":"Secularism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","Are tolerance, assimilation and pluralism the key elements in the making of an Indian form of secularism? Justify your answer."],["2019","10","What are the challenges to our cultural practices in the name of secularism. (10m,150 words)"],["2018","10","How the Indian concept of secularism is different from the western model of secularism? Discuss."],["2014","10","How do the Indian debates on secularism differ from the debates in the West?"]]},{"id":"p54","name":"Social empowerment","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","Despite comprehensive policies for equity and social justice, underprivileged sections are not yet getting the full benefits of affirmative action envisaged by the Constitution. Comment."],["2017","10","What are the two major legal initiatives by the State since Independence, addressing discrimination against Scheduled Tribes (STs)?"],["2016","12.5","Why are the tribals in India referred to as the Scheduled Tribes? Indicate the major provisions enshrined in the Constitution of India for their upliftment."],["2015","12.5","Debate the issue of whether and how contemporary movements for assertion of Dalit identity work towards annihilation of caste."]]}]},{"name":"Geography","chapters":[{"id":"p55","name":"Climatology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","Troposphere is a very significant atmospheric layer that determines weather processes. How?"],["2016","12.5","Discuss the concept of air mass and explain its role in macro-climatic changes."],["2014","10","Most of the unusual climatic happenings are explained as an outcome of the El-Nino effect. Do you agree?"],["2013","5","What do you understand by the phenomenon of temperature inversion in meteorology? How does it affect the weather and the habitants of the place?"],["2013","10","Major hot deserts in northern hemisphere are located between 20-30 degree north and on the western side of the continents. Why?"]]},{"id":"p56","name":"Monsoon","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","Why is the South-West monsoon called ‘Purvaiya’ (easterly) in Bhojpur Region? How has this directional seasonal wind system influenced the cultural ethos of the region?"],["2017","15","What characteristics can be assigned to monsoon climate that succeeds in feeding more than 50 percent of the world population residing in Monsoon Asia?"],["2015","12.5","How far do you agree that the behavior of the Indian monsoon has been changing due to humanizing landscapes? Discuss."]]},{"id":"p57","name":"Geomorphology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Discuss how the changes in shape and sizes of continents and ocean basins of the planet take place due to tectonic movements of the crustal masses."],["2023","10","How are the fjords formed? Why do they constitute some of the most picturesque areas of the world?"],["2022","10","Describe the characteristics and types of primary rocks."],["2021","15","Briefly mention the alignment of major mountain ranges of the world and explain their impact on local weather conditions, with examples."],["2021","10","Why is India considered as a subcontinent? Elaborate your answer."],["2021","15","Briefly mention the alignment of major mountain ranges of the world and explain their impact on local weather conditions, with examples."],["2020","10","Discuss the geophysical characteristics of Circum-Pacific Zone."],["2018","10","Define mantle plume and explain its role in plate tectonics."],["2014","10","Why are the world’s fold mountain systems located along the margins of continents? Bring out the association between the global distribution of Fold Mountains and the earthquakes and volcanoes."],["2013","5","There is no formation of deltas by rivers of the Western Ghat. Why?"],["2013","5","What do you understand by the theory of continental drift? Discuss the prominent evidences in its support."]]},{"id":"p58","name":"Oceanography","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","15","How do ocean currents and water masses differ in their impacts on marine life and the coastal environment? Give suitable examples?"],["2018","10","What are the consequences of spreading of ‘Dead Zones’ on marine ecosystem?"],["2017","15","Account for variations in oceanic salinity and discuss its multi-dimensional effects."],["2015","12.5","Explain the factors responsible for the origin of ocean currents. How do they influence regional climates, fishing and navigation?"],["2014","10","Critically evaluate the various resources of the oceans which can be harnessed to meet the resource crisis in the world."]]},{"id":"p59","name":"Energy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Explain briefly the ecological and economic benefits of solar energy generation in India with suitable examples."],["2025","15","Give a geographical explanation of the distribution of off-shore oil reserves of the world. How are they different from the on-shore occurrences of oil reserves?"],["2022","10","Examine the potential of wind energy in India and explain the reasons for their limited spatial spread."],["2021","15","Discuss the multi-dimensional implications of uneven distribution of mineral oil in the world."],["2020","15","India has immense potential of solar energy though there are regional variations in its development. Elaborate."],["2015","12.5","What are the economic significances of discovery of oil in Arctic Sea and its possible environmental consequences?"],["2013","10","It is said the India has substantial reserves of shale oil and gas, which can feed the needs of country for quarter century. However, tapping of the resources doesn’t appear to be high on the agenda. Discuss critically the availability and issues involved."],["2013","10","With growing scarcity of fossil fuels, the atomic energy is gaining more and more significance in India. Discuss the availability of raw material required for the generation of atomic energy in India and in the world."]]},{"id":"p60","name":"Natural resources Potential","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Discuss the distribution and density of population in the Ganga River Basin with special reference to land, soil and water resources."],["2023","15","Comment on the resource potentials of the long coastline of India and highlight the status of natural hazard preparedness in these areas."],["2022","10","Discuss the natural resource potentials of ‘Deccan Trap’."],["2018","10","Why is India taking keen interest in resources of Arctic Region?"],["2014","10","How does India see its place in the economic space of rising natural resource rich Africa?"]]},{"id":"p61","name":"Primary sector","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","What are non-farm primary activities? How are these activities related to physiographic features in India? Discuss with suitable examples."],["2023","15","From being net food importer in 1960s, India has emerged as a net food exporter to the world. Provide reasons."],["2022","15","Describing the distribution of rubber producing countries, indicate the major environmental issues faced by them."],["2021","10","Despite India being one of the countries of the Gondwanaland, its mining industry contributes much less to Gross Domestic Product (GDP) in percentage. Discuss."],["2018","15","Define blue revolution, explain the problems and strategies for pisciculture development in India."],["2017","10","In spite of adverse environmental impact, coal mining is still inevitable for development.” Discuss."],["2017","10","Mention the advantages of the cultivation of pulse because of which the year 2016 was declared as the International Year of Pulses by the United Nations."],["2014","10","Whereas the British planters had developed tea gardens all along the Shivaliks and Lesser Himalayas from Assam to Himachal Pradesh, in effect they did not succeed beyond the Darjeeling area. Explain."],["2014","10","Why did the Green Revolution in India virtually by-pass the eastern region despite fertile soil and good availability of water?"]]},{"id":"p62","name":"Secondary sector","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","15","Account for the present location of iron and steel industries away from the source of raw material, by giving examples."],["2019","10","Can the strategy of regional-resource based manufacturing help in promoting employment in India?"],["2019","10","Discuss the factors for localization of agro-based food processing industries of North-West India."],["2018","15","What is the significance of Industrial Corridors in India? Identify industrial corridors, explain their main characteristics."],["2017","15","Petroleum refineries are not necessarily located nearer to crude oil producing areas, particularly in many of the developing countries. Explain its implications."],["2014","10","Account for the change in the spatial pattern of the Iron and Steel industry in the world."],["2013","5","Analyze the factors for highly decentralized cotton textile industry in India"],["2013","5","Do you agree that there is a growing trend of opening new sugar mills in the Southern states of India? Discuss with justification"]]},{"id":"p63","name":"Tertiary sector","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","Mention the significance of straits and isthmus in international trade."],["2019","15","How can the mountain ecosystem be restored from the negative impact of development initiatives and tourism?"],["2018","10","Why is Indian Regional Navigational Satellite System (IRNSS) needed? How does it help in navigation?"],["2016","12.5","Enumerate the problems and prospects of inland water transport in India."],["2015","12.5","The states of Jammu and Kashmir, Himachal Pradesh and Uttarakhand reaching the limits of their ecological carrying capacity due to tourism. Critically evaluate."]]},{"id":"p64","name":"Land use planning","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","How can Artificial Intelligence (AI) and drones be effectively used along with GIS and RS techniques in locational and areal planning?"]]},{"id":"p65","name":"Cyclone","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What is sea surface temperature rise? How does it affect the formation of tropical cyclones?"],["2022","10","Discuss the meaning of colour-coded weather warnings for cyclone prone areas given by India Meteorological Department."],["2014","10","Tropical cyclones are largely confined to South China Sea, Bay of Bengal and Gulf of Mexico. Why?"],["2013","5","The recent cyclone on the east coast of India was called “Phailin”. How are the tropical cyclones named across the world?"]]},{"id":"p66","name":"Landslides","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Differentiate the causes of landslides in the Himalayan region and Western Ghats."],["2016","12.5","The Himalayas are highly prone to landslides. Discuss the causes and suggest suitable measures of mitigation."],["2013","5","Bring out the causes for more frequent landslides in the Himalayas than in Western Ghats"]]},{"id":"p67","name":"Volcanic activity","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Mention the global occurrence of volcanic eruptions in 2021 and their impact on regional environment."]]},{"id":"p68","name":"Cloudbursts","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What is the phenomenon of ‘cloudbursts’? Explain."]]},{"id":"p69","name":"Twisters","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","What is a twister? Why are the majority of twisters observed in areas around the Gulf of Mexico?"]]},{"id":"p70","name":"Aurora","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","What are aurora australis and aurora borealis? How are these triggered?"]]},{"id":"p71","name":"Tsunamis","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","What are Tsunamis? How and where are they formed? What are their consequences? Explain with examples."]]},{"id":"p72","name":"Flora and Fauna","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Identify and discuss the factors responsible for diversity of natural vegetation in India. Assess the significance of wildlife sanctuaries in rain forests regions of India."],["2020","15","Examine the status of forest resources of India and its resultant impact on climate change."],["2019","15","Assess the impact of global warming on coral life system with examples."],["2019","10","Discuss the causes of depletion of mangroves and explain their importance in maintaining coastal ecology."]]},{"id":"p73","name":"Climate change","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","How are climate change and the sea level rise affecting the very existence of many island nations? Discuss with examples."],["2023","10","Discuss the consequences of climate change on the food security in tropical countries."],["2020","10","The process of desertification does not have climatic boundaries. Justify with examples."]]},{"id":"p74","name":"Water Management","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","The groundwater potential of the gangetic valley is on a serious decline. How may it affect the food security of India?"],["2023","10","Why is the world today confronted with a crisis of availability of and access to freshwater resources?"],["2020","15","The interlinking of rivers can provide viable solutions to the multi-dimensional inter-related problems of droughts, floods and interrupted navigation. Critically examine."],["2019","15","What is water stress? How and why does it differ regionally in India?"],["2018","15","The ideal solution of depleting ground water resources in India is water harvesting system. How can it be made effective in urban areas?"],["2017","15","In what way can flood be converted into a sustainable source of irrigation and all-weather inland navigation in India?"],["2016","12.5","In what way micro-watershed Development projects help in water conservation in drought prone and semi-arid regions of India."],["2016","12.5","Present an account of the Indus Water Treaty and examine its ecological, economic and political implications in the context of changing bilateral relations."],["2016","12.5","The effective management of land and water resources will drastically reduce the human miseries. Explain"],["2015","12.5","India is well endowed with fresh water resources. Critically examine why it still suffers from water scarcity."]]},{"id":"p75","name":"Cryosphere","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","15","How does the melting of the Arctic ice and glaciers of the Antarctic differently affect the weather patterns and human activities on the Earth? Explain."],["2020","10","How will the melting of Himalayan glaciers have a far-reaching impact on the water resources of India?"],["2017","10","How does the cryosphere affect global climate?"],["2014","10","Bring out the relationship between the shrinking Himalayan glaciers and the symptoms of climate change in the Indian sub-continent."]]},{"id":"p76","name":"Miscellaneous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","How does the Juno Mission of NASA help to understand the origin and evolution of the Earth?"],["2016","12.5","South China Sea has assumed great geopolitical significance in the present context. Comment."],["2015","12.5","Mumbai, Delhi and Kolkata are the three mega cities of the country but the air pollution is much more serious problem in Delhi as compared to the other two. Why is this so?"]]}]}]},{"name":"GS II","subjects":[{"name":"Polity","chapters":[{"id":"p77","name":"Amendments","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Indian Constitution has conferred the amending power on the ordinary legislative institutions with a few procedural hurdles. In view of this statement, examine the procedural and substantive limitations on the amending power of the Parliament to change the Constitution."],["2019","15","“Parliament’s power to amend the Constitution is a limited power and it cannot be enlarged into absolute power.” In the light of this statement explain whether Parliament under Article 368 of the Constitution can destroy the Basic Structure of the Constitution by expanding its amending power?"],["2017","15","Explain the salient features of the constitution(One Hundred and First Amendment) Act, 2016. Do you think it is efficacious enough ‘to remove cascading effect of taxes and provide for common national market for goods and services’?"]]},{"id":"p78","name":"Case Laws","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Explain the constitutional perspectives of Gender Justice with the help of relevant Constitutional Provisions and case laws."],["2022","10","The most significant achievement of modern law in India in the constitutionalization of environmental problems by the Supreme Court. Discuss this statement with the help of relevant case laws."],["2016","12.5","What was held in the Coelho case? In this context, can you say that judicial review is of key importance amongst the basic features of the Constitution?"]]},{"id":"p79","name":"Constitutional Morality","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","“Constitutional morality is the fulcrum which acts as an essential check upon the high functionaries and citizens alike...” In view of the above observation of the Supreme Court, explain the concept of constitutional morality and its application to ensure balance between judicial independence and judicial accountability in India."],["2021","10","‘Constitutional Morality’ is rooted in the Constitution itself and is founded on its essential facets. Explain the doctrine of ‘Constitutional Morality’ with the help of relevant judicial decisions."]]},{"id":"p80","name":"DPSP","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","Discuss the possible factors that inhibit India from enacting for its citizens a uniform civil code as provided for in the Directive Principles of State Policy."]]},{"id":"p81","name":"Fundamental Rights","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","Right to privacy is intrinsic to life and personal liberty and is inherently protected under Article 21 of the Constitution. Explain. In this reference discuss the law relating to D.N.A. testing of a child in the womb to establish its paternity."],["2023","15","”The Constitution of India is a living instrument with capabilities of enormous dynamism. It is a constitution made for a progressive society”. Illustrate with special reference to the expanding horizons of the right to life and personal liberty."],["2022","10","Right of movement and residence throughout the territory of India are freely available to the Indian citizens, but these rights are not absolute. Comment"],["2017","15","Examine the scope of Fundamental Rights in the light of the latest judgement of the Supreme Court on Right to Privacy."],["2015","12.5","Does the right to clean environment entail legal regulations on burning crackers during Diwali? Discuss in the light of Article 21 of the Indian Constitution and Judgement(s) of the Apex Court in this regard."],["2014","12.5","What do you understand by the concept “freedom of speech and expression”? Does it cover hate speech also? Why do the films in India stand on a slightly different plane from other forms of expression? Discuss."],["2013","10","Discuss Section 66A of IT Act, with reference to its alleged violation of Article 19 of the Constitution."]]},{"id":"p82","name":"Making of the Constitution","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","12.5","Did the Government of India Act, 1935 lay down a federal constitution? Discuss."],["2016","12.5","Discuss each adjective attached to the word ‘Republic’ in the preamble. Are they defendable in the present circumstances?"]]},{"id":"p83","name":"Emergency","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Account for the legal and political factors responsible for the reduced frequency of using Article 356 by the Union Governments since mid 1990s."],["2018","10","Under what circumstances can the Financial Emergency be proclaimed by the President of India? What consequences follow when such a declaration remains in force?"]]},{"id":"p84","name":"Special Provisions","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","12.5","To what extent is Article 370 of the Indian Constitution, bearing marginal note “Temporary provision with respect to the State of Jammu and Kashmir”, temporary? Discuss the future prospects of this provision in the context of Indian polity."],["2013","10","Recent directives from Ministry of Petroleum and Natural Gas are perceived by the `Nagas’ as a threat to override the exceptional status enjoyed by the State. Discuss in light of Article 371A of the Indian Constitution."]]},{"id":"p85","name":"Federalism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Examine the evolving pattern of Centre-State financial relations in the context of planned development in India. How far have the recent reforms impacted the fiscal federalism in India?"],["2024","15","What changes has the Union Government recently introduced in the domain of Centre-State relations? Suggest measures to be adopted to build the trust between the Centre and the States and for strengthening federalism."],["2023","15","Explain the significance of the 101st Constitutional Amendment Act. To what extent does it reflect the accommodative spirit of federalism?"],["2020","15","Indian Constitution exhibits centralising tendencies to maintain unity and integrity of the nation. Elucidate in the perspective of the Epidemic Diseases Act, 1897; The Disaster Management Act, 2005 and recently passed Farm Acts."],["2020","10","How far do you think cooperation, competition and confrontation have shaped the nature of federation in India? Cite some recent examples to validate your answer."],["2019","10","From the resolution of contentious issues regarding distribution of legislative powers by the courts, ‘Principle of Federal Supremacy’ and ‘Harmonious Construction’ have emerged. Explain."],["2015","12.5","The concept of cooperative federalism has been increasingly emphasized in recent years. Highlight the drawbacks in the existing structure and the extent to which cooperative federalism would answer the shortcomings."],["2014","12.5","Though the federal principle is dominant in our Constitution and that principle is one of its basic features, but it is equally true that federalism under the Indian Constitution leans in favour of a strong Centre, a feature that militates against the concept of strong federalism. Discuss."],["2013","10","Constitutional mechanisms to resolve the inter-state water disputes have failed to address and solve the problems. Is the failure due to structural or process inadequacy or both? Discuss."],["2013","10","Many State Governments further bifurcate geographical administrative areas like Districts and Talukas for better governance. In light of the above, can it also be justified that more number of smaller States would bring in effective governance at State level? Discuss."]]},{"id":"p86","name":"Union Territory","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Discuss the nature of Jammu and Kashmir Legislative Assembly after the Jammu and Kashmir Reorganization Act, 2019. Briefly describe the powers and functions of the Assembly of the Union Territory of Jammu and Kashmir."],["2016","12.5","Discuss the essentials of the 69th Constitutional Amendment Act and anomalies, if any that have led to recent reported conflicts between the elected representatives and the institution of the Lieutenant Governor in the administration of Delhi. Do you think that this will give rise to a new trend in the functioning of Indian federal politics?"]]},{"id":"p87","name":"Executive Vs Judiciary","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","Critically examine the Supreme Court’s judgement on ‘National Judicial Appointments Commission Act, 2014’ with reference to appointment of judges of higher judiciary in India."]]},{"id":"p88","name":"Judiciary Vs Legislature","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","15","Judicial Legislation is antithetical to the doctrine of separation of powers as envisaged in the Indian Constitution. In this context justify the filing of large number of public interest petitions praying for issuing guidelines to executive authorities."],["2013","10","The Supreme Court of India keeps a check on arbitrary power of the Parliament in amending the Constitution. Discuss critically."]]},{"id":"p89","name":"Executive Vs Legislature","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","“The growth of cabinet system has practically resulted in the marginalisation of the parliamentary supremacy.” Elucidate."],["2022","15","Discuss the essential conditions for exercise of the legislative powers by the Governor. Discuss the legality of re-promulgation of ordinances by the Governor without placing them before the Legislature."],["2021","10","To what extent, in your view, the Parliament is able to ensure accountability of the executive in India?"],["2018","15","Whether the Supreme Court Judgement (July 2018) can settle the political tussle between the Lt. Governor and elected government of Delhi? Examine."],["2015","12.5","Resorting to ordinances has always raised concern on violation of the spirit of separation of powers doctrine. While noting the rationales justifying the power to promulgate ordinances, analyze whether the decisions of the Supreme Court on the issue have further facilitated resorting to this power. Should the power to promulgate ordinances be repealed?"]]},{"id":"p90","name":"Separation of Powers","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","“Constitutionally guaranteed judicial independence is a prerequisite of democracy”. Comment."],["2019","10","Do you think that constitution of India does not accept principle of strict separation of powers rather it is based on the principle of ‘checks and balance’? Explain."]]},{"id":"p91","name":"Local Self Government","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Analyse the role of local bodies in providing good governance at local level and bring out the pros and cons merging the rural local bodies with the urban local bodies."],["2023","10","“The states in India seem reluctant to empower urban local bodies both functionally as well as financially.” Comment."],["2022","10","To what extent, in your opinion, has the decentralisation of power in India changed the governance landscape at the grassroots ?"],["2020","15","The strength and sustenance of local institutions in India has shifted from their formative phase of ‘Functions, Functionaries and Funds’ to the contemporary stage of ‘Functionality’. Highlight the critical challenges faced by local institutions in terms of their functionality in recent times."],["2019","15","“The reservation of seats for women in the institutions of local selfgovernment has had a limited impact on the patriarchal character of the Indian Political Process.” Comment."],["2018","15","Assess the importance of Panchayat system in India as a part of local government. Apart from government grants, what sources the Panchayats can look out for financing developmental projects."],["2017","10","“The local self-government system in India has not proved to be effective instrument of governance”. Critically examine the statement and give your views to improve the situation."],["2015","12.5","In absence of a well-educated and organized local level government system, `Panchayats’ and ‘Samitis’ have remained mainly political institutions and not effective instruments of governance. Critically discuss."]]},{"id":"p92","name":"Constitutional Comparison","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Compare and contrast the President’s power to pardon in India and in the USA. Are there any limits to it in both the countries? What are ‘preemptive pardons’?"],["2025","15","Discuss the evolution of collegium system in India. Critically examine the advantages and disadvantages of the system on appointment of the Judges of the Supreme Court of India and that of the USA."],["2024","15","Discuss India as a secular state and compare with the secular principles of the US constitution"],["2023","10","Compare and contrast the British and Indian approaches to Parliamentary sovereignty."],["2022","15","Critically examine the procedures through which the Presidents of India and France are elected."],["2021","15","Analyze the distinguishing features of the notion of Right to Equality in the Constitutions of the USA and India."],["2020","10","The judicial systems in India and UK seem to be converging as well as diverging in recent times. Highlight the key points of convergence and divergence between the two nations in terms of their judicial practices."],["2019","10","What can France learn from the Indian Constitution’s approach to secularism?"],["2018","15","India and USA are two large democracies. Examine the basic tenants on which the two political systems are based."]]},{"id":"p93","name":"Bicameralism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","15","Explain the constitutional provisions under which Legislative Councils are established. Review the working and current status of Legislative Councils with suitable illustrations."],["2021","15","Explain the constitutional provisions under which Legislative Councils are established. Review the working and current status of Legislative Councils with suitable illustrations."],["2020","15","Rajya Sabha has been transformed from a ‘useless stepney tyre’ to the most useful supporting organ in past few decades. Highlight the factors as well as the areas in which this transformation could be visible."],["2017","15","The Indian Constitution has provisions for holding joint session of the two houses of the Parliament. Enumerate the occasions when this would normally happen and also the occasions when it cannot, with reasons thereof."]]},{"id":"p94","name":"Parliamentary Committees","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Explain the structure of the Parliamentary Committee system. How far have the financial committees helped in the institutionalization of Indian Parliament?"],["2021","15","Do Department-related Parliamentary Standing Committees keep the administration on its toes and inspire reverence for parliamentary control? Evaluate the working of such committees with suitable examples."],["2018","10","Why do you think the committees are considered to be useful for parliamentary work? Discuss, in this context, the role or the Estimates Committee."],["2017","10","Discuss the role of Public Accounts Committee in establishing accountability of the government to the people."]]},{"id":"p95","name":"Parliamentary Privileges","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","12.5","The ‘Powers, Privileges and Immunities of Parliament and its Members’ as envisaged in Article 105 of the Constitution leave room for a large number of un-codified and un-enumerated privileges to continue. Assess the reasons for the absence of legal codification of the ‘parliamentary privileges’. How can this problem be addressed?"]]},{"id":"p96","name":"Presiding Officers","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","Discuss the role of Presiding Officers of state legislatures in maintaining order and impartiality in conducting legislative work and in facilitating best democratic practices."],["2022","10","Discuss the role of the Vice-President of India as the Chairman of the Rajya Sabha."],["2020","10","‘Once a Speaker, Always a Speaker’! Do you think this practice should be adopted to impart objectivity to the office of the Speaker of Lok Sabha? What could be its implications for the robust functioning of parliamentary business in India?"]]},{"id":"p97","name":"Role of MPs","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","15","Individual Parliamentarian’s role as the national lawmaker is on a decline, which in turn, has adversely impacted the quality of debates and their outcome. Discuss."],["2013","10","The role of individual MPs (Members of Parliament) has diminished over the years and as a result healthy constructive debates on policy issues are not usually witnessed. How far can this be attributed to the anti-defection law, which was legislated but with a different intention?"]]},{"id":"p98","name":"Alternate Dispute Resolution","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Explain and distinguish between Lok Adalats and Arbitration Tribunals. Whether they entertain civil as well as criminal cases ?"],["2023","10","Who are entitled to receive free legal aid? Assess the role of the National Legal Services Authority(NALSA) in rendering free legal aid in India."],["2015","12.5","What are the major changes brought in the Arbitration and Conciliation Act, 1996 through the recent Ordinance promulgated by the President? How far will it improve India’s dispute resolution mechanism? Discuss."]]},{"id":"p99","name":"Informal associations and their role in polity","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","Khap Panchayats have been in the news for functioning as extra-constitutional authorities, often delivering pronouncements amounting to human rights violations. Discuss critically the actions taken by the legislative, executive and the judiciary to set the things right in this regard."]]},{"id":"p100","name":"Judiciary","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","Explain the reasons for the growth of public interest litigation in India. As a result of it, has the Indian Supreme Court emerged as the world’s most powerful judiciary?"],["2021","10","Discuss the desirability of greater representation to women in the higher judiciary to ensure diversity, equity and inclusiveness."],["2014","12.5","Starting from inventing the ‘basic structure’ doctrine, the judiciary has played a highly proactive role in ensuring that India develops into a thriving democracy. In light of the statement, evaluate the role played by judicial activism in achieving the ideals of democracy."]]},{"id":"p101","name":"Pressure Groups","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","What are environmental pressure groups? Discuss their role in raising awareness, influencing policies and advocating for environmental protection in India."],["2021","10","“Pressure groups play a vital role in influencing public policy making in India.” Explain how the business associations contribute to public policies."],["2019","10","What are the methods used by the Farmers organizations to influence the policymakers in India and how effective are these methods?"],["2017","10","How do pressure groups influence Indian political process? Do you agree with this view that informal pressure groups have emerged as powerful than formal pressure groups in recent years?"],["2013","10","Pressure group politics is sometimes seen as the informal face of politics. With regards to the above, assess the structure and functioning of pressure groups in India."]]},{"id":"p102","name":"Tribunal","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Comment on the need of administrative tribunals as compared to the court system. Assess the impact of the recent tribal reforms through rationalization of tribunals made in 2021."]]},{"id":"p103","name":"Union Executive","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","The Attorney General of India plays a crucial role in guiding the legal framework of the Union Government and ensuring sound governance through legal counsel.” Discuss his responsibilities, rights and limitations in this regard."],["2019","15","“The Attorney-General is the chief legal adviser and lawyer of the Government of India.” Discuss."],["2014","12.5","Instances of President’s delay in commuting death sentences has come under public debate as denial of justice. Should there be a time limit specified for the President to accept/reject such petitions? Analyse."],["2014","12.5","The size of the cabinet should be as big as governmental work justifies and as big as the Prime Minister can manage as a team. How far the efficacy of a government then is inversely related to the size of the cabinet? Discuss."]]},{"id":"p104","name":"Election Dispute and Disqualification","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Discuss the ‘corrupt practices’ for the purpose of the Representation of the People Act, 1951. Analyze whether the increase in the assets of the legislators and/or their associates, disproportionate to their known sources of income, would constitute ‘undue influence’ and consequently a corrupt practice."],["2022","15","Discuss the procedures to decide the disputes arising out of the election of a Member of the Parliament or State Legislature under The Representation of the People Act, 1951. What are the grounds on which the election of any returned candidate may be declared void? What remedy is available to the aggrieved party against the decision? Refer to the case laws."],["2020","10","“There is a need for simplification of procedure for disqualification of persons found guilty of corrupt practices under the Representation of Peoples Act”. Comment."],["2019","15","On what grounds a people’s representative can be disqualified under the Representation of People Act, 1951? Also mention the remedies available to such person against his disqualification."]]},{"id":"p105","name":"Electoral reforms","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Examine the need for electoral reforms as suggested by various committees with particular reference to “one nation-one election” principle."],["2018","10","In the light of recent controversy regarding the use of Electronic Voting Machines (EVM), what are the challenges before the Election Commission of India to ensure the trustworthiness of elections in India?"],["2017","15","To enhance the quality of democracy in India the Election Commission of India has proposed electoral reforms in 2016. What are the suggested reforms and how far are they significant to make democracy successful?"],["2017","10","‘Simultaneous election to the Lok Sabha and the State Assemblies will limit the amount of time and money spent in electioneering but it will reduce the government’s accountability to the people’ Discuss."]]},{"id":"p106","name":"MCC","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","Discuss the role of the Election Commission of India in the light of the evolution of the Model Code of Conduct."]]},{"id":"p107","name":"Political Parties","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","While the national political parties in India favour centralisation, the regional parties are in favour of State autonomy. Comment."],["2016","12.5","The Indian party system is passing through a phase of transition which looks to be full of contradictions and paradoxes.” Discuss."]]}]},{"name":"Governance","chapters":[{"id":"p108","name":"Constitutional Bodies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","“The duty of the Comptroller and Auditor General is not merely to ensure the legality of expenditure but also its propriety.” Comment."],["2022","10","Discuss the role of the National Commission for Backward Classes in the wake of its transformation from a statutory body to a constitutional body."],["2021","10","How have the recommendations of the 14th Finance Commission of India enabled the States to improve their fiscal position?"],["2018","15","How is the Finance Commission of India constituted? What do you about the terms of reference of the recently constituted Finance Commission? Discuss."],["2018","10","The Comptroller and Auditor General (CAG) has a very vital role to play. Explain how this is reflected in the method and terms of his appointment as well as the range of powers he can exercise."],["2018","10","Whether National Commission for Scheduled Castes (NCSC) can enforce the implementation of constitutional reservation for the Scheduled Castes in the religious minority institutions? Examine."],["2016","12.5","Exercise of CAG’s powers in relation to the accounts of the Union and the States is derived from Article 149 of the Indian Constitution. Discuss whether audit of the Government’s Policy implementation could amount to overstepping its own (CAG) jurisdiction."],["2013","10","Discuss the recommendations of the 13th Finance Commission which have been a departure from the previous commissions for strengthening the local government finances."]]},{"id":"p109","name":"Enforcement Agencies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","15","The jurisdiction of the Central Bureau of Investigation (CBI) regarding lodging an FIR and conducting probe within a particular State is being questioned by various States. However, the power of the States to withhold consent to the CBI is not absolute. Explain with special reference to the federal character of India."]]},{"id":"p110","name":"Quasi judicial Bodies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","10","“The Central Administration Tribunal which was established for redressal of grievances and complaints by or against central government employees, nowadays is exercising its powers as an independent judicial authority.” Explain."],["2018","15","How far do you agree with the view that tribunals curtail the jurisdiction of ordinary courts? In view of the above, discuss the constitutional validity and competency of the tribunals in India."],["2016","12.5","What is a quasi-judicial body? Explain with the help of concrete examples."]]},{"id":"p111","name":"Sectoral Regulatory Bodies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","For achieving the desired objectives, it is necessary to ensure that the regulatory institutions remain independent and autonomous. Discuss in the light of the experiences in recent past."],["2014","12.5","The setting up of a Rail Tariff Authority to regulate fares will subject the cash strapped Indian Railways to demand subsidy for obligation to operate non-profitable routes and services. Taking into account the experience in the power sector, discuss if the proposed reform is expected to benefit the consumers, the Indian Railways or the private container operators."],["2013","10","The product diversification of financial institutions and insurance companies, resulting in overlapping of products and services strengthens the case for the merger of the two regulatory agencies, namely SEBI and IRDA. Justify."]]},{"id":"p112","name":"Statutory Bodies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","The National Commission for Protection of Child Rights has to address the challenges faced by children in the digital era. Examine the existing policies and suggest measures the Commission can initiate to tackle the issue."],["2023","10","Discuss the role of the Competition Commission of India in containing the abuse of dominant position by the Multi-National Corporations in India. Refer to the recent decisions."],["2021","15","Though the Human Rights Commissions have contributed immensely to the protection of human rights in India, yet they have failed to assert themselves against the mighty and powerful. Analyzing their structural and practical limitations, suggest remedial measures."],["2020","15","Which steps are required for constitutionalization of a Commission? Do you think imparting constitutionality to the National Commission for Women would ensure greater gender justice and empowerment in India? Give reasons."],["2018","15","Multiplicity of various commissions for the vulnerable sections or the society leads to problems or overlapping jurisdiction and duplication of functions. Is it better to merge all commissions into an umbrella Human Rights Commission? Argue your case."],["2017","15","Is the National Commission for Women able to strategize and tackle the problems that women face at both public and private spheres? Give reasons in support of your answer."],["2014","12.5","National Human Rights Commission (NHRC) in India can be most effective when its tasks are adequately supported by other mechanisms that ensure the accountability of a government. In light of the above observation assess the role of NHRC as an effective complement to the judiciary and other institutions in promoting and protecting human rights standards."],["2013","10","‘A national Lokpal, however strong it may be, cannot resolve the problems of immorality in public affairs’. Discuss."]]},{"id":"p113","name":"Government Schemes and Policies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","The Gati-Shakti Yojana needs meticulous coordination between the government and the private sector to achieve the goal of connectivity. Discuss."],["2014","12.5","Two parallel run schemes of the Government viz. the Adhaar Card and NPR, one as voluntary and the other as compulsory, have led to debates at national levels and also litigations. On merits, discuss whether or not both schemes need run concurrently. Analyse the potential of the schemes to achieve developmental benefits and equitable growth."],["2013","10","The basis of providing urban amenities in rural areas (PURA) is rooted in establishing connectivity. Comment."]]},{"id":"p114","name":"Structural reforms and Actions","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","“In contemporary development models, decision-making and problem-solving responsibilities are not located close to the source of information and execution, defeating the objectives of development.” Critically evaluate."],["2019","15","‘In the context of neo-liberal paradigm of development planning, multi-level planning is expected to make operations cost effective and remove many implementation blockages.’-Discuss."],["2019","15","The need for cooperation among various service sector has been an inherent component of development discourse. Partnership bridges bring the gap among the sectors. It also sets in motion a culture of ‘Collaboration’ and ‘team spirit’. In the light of statements above examine India’s Development process."],["2018","10","Policy contradictions among various competing sectors and stakeholders have resulted in inadequate ‘protection and prevention of degradation’ to environment. “ Comment with relevant illustration."],["2016","12.5","Has the Indian governmental system responded adequately to the demands of Liberalization, Privatization and Globalization started in 1991? What can the government do to be responsive to this important change?"],["2014","12.5","Though 100 percent FDI is already allowed in non-news media like a trade publication and general entertainment channel, the Government is mulling over the proposal for increased FDI in news media for quite some time. What difference would an increase in FDI make? Critically evaluate the pros and cons."]]},{"id":"p115","name":"Civil Society","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Civil Society Organizations are often perceived as being anti-State actors rather than non-State actors. Do you agree? Justify."],["2023","15","Discuss the contribution of civil society groups for women’s effective and meaningful participation and representation in state legislatures in India."],["2021","15","Can Civil Society and Non-Governmental Organizations present an alternative model of public service delivery to benefit the common citizen? Discuss the challenges of this alternative model."],["2016","12.5","In the Indian governance system, the role of non-state actors has been only marginal. Critically examine this statement."],["2015","12.5","Examine critically the recent changes in the rules governing foreign funding of NGOs under the Foreign Contribution (Regulation) Act (FCRA), 1976."],["2015","12.5","How can the role of NGOs be strengthened in India for development works relating to protection of the environment? Discuss throwing light on the major constraints."]]},{"id":"p116","name":"Donor Agencies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Public charitable trusts have the potential to make India’s development more inclusive as they relate to certain vital public issues. Comment."],["2022","15","Do you agree with the view that increasing dependence on donor agencies for development reduces the importance of community participation in the development process ? Justify your answer."]]},{"id":"p117","name":"SHGs","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Can the vicious cycle of gender inequality, poverty and malnutrition be broken through microfinancing of women SHGs? Explain with examples."],["2020","15","“Micro-Finance as an anti-poverty vaccine, is aimed at asset creation and income security of the rural poor in India”. Evaluate the role of Self Help Groups in achieving the twin objectives along with empowering women in rural India."],["2017","15","‘The emergence of Self Help Groups(SHGs) in contemporary times points to the slow but steady withdrawal of the state from developmental activities’. Examine the role of the SHGs in developmental activities and the measures taken by the Government of India to promote the SHGs."],["2015","12.5","The Self-Help Group (SHG) Bank Linkage Programme (SBLP), which is India’s own innovation, has proved to be one of the most effective poverty alleviation and women empowerment programmes. Elucidate."],["2014","12.5","The penetration of Self Help Groups (SHGs) in rural areas in promoting participation in development programmes is facing socio-cultural hurdles. Examine."],["2013","10","The legitimacy and accountability of Self Help Groups (SHGs) and their patrons, the micro-finance outfits, need systematic assessment and scrutiny for the sustained success of the concept. Discuss."]]},{"id":"p118","name":"Citizens Charter","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","The Citizens’charter has been a land mark initiative in ensuring citizen-centric administration. But it is yet to reach its full potential. Identify the factors hindering the realisation of its promise and suggest measures to overcome them."],["2018","15","Citizens’ Charter is an ideal instrument of organizational transparency and accountability, but it has its own limitations. Identify the limitations and suggest measures for greater effectiveness or the Citizens Charter."],["2013","10","Though Citizen’s charters have been formulated by many public service delivery organizations, there is no corresponding improvement in the level of citizens’ satisfaction and quality of services being provided. Analyze."]]},{"id":"p119","name":"Transaparency and Accountability","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","What are the aims and objects of the recently passed and enforced, The Public Examination (Prevention of Unfair Means) Act, 2024? Whether University/State Education Board examinations, too, are covered under the Act ?"],["2022","10","Reforming the government delivery system through the Direct Benefit Transfer Scheme is a progressive step, but it has its limitations too. Comment."],["2020","10","“Recent amendments to the Right to Information Act will have profound impact on the autonomy and independence of the Information Commission”. Discuss."],["2016","12.5","Effectiveness of the goverment system at various levels and people’s participation in the governance system are inter-dependent. Discuss their relationship with each other in context of India."],["2016","12.5","In the integrity index of Transparency International, India stands very low. Discuss briefly the legal, political, economic, social and cultural factors that have caused the decline of public morality in India."],["2015","12.5","If amendment bill to the Whistleblowers Act, 2011 tabled in the Parliament is passed, there may be no one left to protect. Critically evaluate."],["2015","12.5","In the light of the Satyam Scandal (2009), discuss the changes brought in corporate governance to ensure transparency, accountability."]]},{"id":"p120","name":"E-governance","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","E-governance projects have a built-in bias towards technology and back-end integration than user-centric designs. Examine."],["2024","15","e-governance is not just about the routine application of digital technology in service delivery process. It is as much about multifarious interactions for ensuring transparency and accountability. In this context evaluate the role of the ‘Interactive Service Model’ of e-governance."],["2023","10","e-governance, as a critical tool of governance, has ushered in effectiveness, transparency and accountability in governments. What inadequacies hamper the enhancement of these features?"],["2021","15","Has digital illiteracy, particularly in rural areas, coupled with lack of Information and Communication Technology (ICT) accessibility hindered socio-economic development? Examine with justification."],["2020","10","“The emergence of Fourth Industrial Revolution (Digital Revolution) has initiated e-Governance as an integral part of government”. Discuss."],["2019","10","Implementation of information and Communication Technology (ICT) based Projects / Programmes usually suffers in terms of certain vital factors. Identify these factors, and suggest measures for their effective implementation."],["2018","10","E-Governance is not only about utilization of the power of new technology, but also much about critical importance of the ‘use value’ of information Explain."],["2013","10","Electronic cash transfer system for the welfare schemes is an ambitious project to minimize corruption, eliminate wastage and facilitate reforms. Comment."]]},{"id":"p121","name":"Civil Services","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","The Doctrine of Democratic Governance makes it necessary that the public perception of the integrity and commitment of civil servants becomes absolutely positive. Discuss."],["2020","10","“Institutional quality is a crucial driver of economic performance”. In this context suggest reforms in Civil Service for strengthening democracy."],["2017","15","Initially Civil Services in India were designed to achieve the goals of neutrality and effectiveness, which seems to be lacking in the present context. Do you agree with the view that drastic reforms are required in Civil Services. Comment"],["2016","12.5","Traditional bureaucratic structure and culture have hampered the process of socio-economic development in India. Comment."],["2014","12.5","Has the Cadre based Civil Services Organisation been the cause of slow change in India? Critically examine."]]}]},{"name":"Social Justice","chapters":[{"id":"p122","name":"Children","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","12.5","Examine the main provisions of the National Child Policy and throw light on the status of its implementation."]]},{"id":"p123","name":"Disables","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","The Rights of Persons with Disabilities Act, 2016 remains only a legal document without intense sensitisation of government functionaries and citizens regarding disability. Comment."],["2017","10","Does the Rights of Persons with Disabilities Act, 2016 ensure effective mechanism for empowerment and inclusion of the intended beneficiaries in the society? Discuss"]]},{"id":"p124","name":"Efficacy of Welfare and Development Schemes","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","“Development and welfare schemes for the vulnerable, by its nature, are discriminatory in approach.” Do you agree? Give reasons for your answer."],["2019","15","Performance of welfare schemes that are implemented for vulnerable sections is not so effective due to absence of their awareness and active involvement at all stages of policy process – Discuss."],["2014","12.5","Do government’s schemes for up-lifting vulnerable and backward communities by protecting required social resources for them, lead to their exclusion in establishing businesses in urban economics?"],["2013","10","The Central Government frequently complains on the poor performance of the State Governments in eradicating suffering of the vulnerable sections of the society. Restructuring of Centrally sponsored schemes across the sectors for ameliorating the cause of vulnerable sections of population aims at providing flexibility to the States in better implementation. Critically evaluate."]]},{"id":"p125","name":"Women","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Women’s social capital complements in advancing empowerment and gender equity. Explain."],["2021","15","“Though women in post-Independent India have excelled in various fields, the social attitude towards women and feminist movement has been patriarchial.” Apart from women education and women empowerment schemes, what interventions can help change this milieu?"]]},{"id":"p126","name":"Education","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","The Right of Children to Free and Compulsory Education Act, 2009 remains inadequate in promoting incentive-based system for children’s education without generating awareness about the importance of schooling. Analyse."],["2021","10","“Earn while you learn’ scheme needs to be strengthened to make vocational education and skill training meaningful.” Comment. (150 words)"],["2020","15","National Education Policy 2020 is in conformity with the Sustainable Development Goal-4 (2030). It intends to restructure and reorient education system in India. Critically examine the statement."],["2015","12.5","The quality of higher education in India requires major improvements to make it internationally competitive. Do you think that the entry of foreign educational institutions would help improve the quality of higher and technical education in the country? Discuss."],["2014","12.5","Should the premier institutes like IITs/IIMs be allowed to retain premier status, allowed more academic independence in designing courses and also decide mode/ criteria of selection of students. Discuss in light of the growing challenges."]]},{"id":"p127","name":"Health","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","In a crucial domain like the public healthcare system, the Indian State should play a vital role to contain the adverse impact of marketisation of the system. Suggest some measures through which the State can enhance the reach of public healthcare at the grassroots level."],["2021","10","“Besides being a moral imperative of a Welfare State, primary health structure is a necessary precondition for sustainable development.” Analyse.(150 words)"],["2020","10","In order to enhance the prospects of social development, sound and adequate health care policies are needed particularly in the fields of geriatric and maternal health care. Discuss."],["2018","10","Appropriate local community-level healthcare intervention is a prerequisite to achieve ‘Health for All ‘ in India. Explain."],["2017","10","‘To ensure effective implementation of policies addressing water, sanitation and hygiene needs, the identification of beneficiary segments is to be synchronized with the anticipated outcomes’ Examine the statement in the context of the WASH scheme."],["2015","12.5","Public health system has limitations in providing universal health coverage. Do you think that the private sector could help in bridging the gap? What other viable alternatives would you suggest?"],["2013","10","Identify the Millennium Development Goals (MDGs) that are related to health. Discuss the success of the actions taken by the Government for achieving the same."]]},{"id":"p128","name":"Human Resources","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Skill development programs have succeed in increasing human resources supply to various sectors. In the context of the statement analyze the linkages between education, skill and employment."],["2023","10","The crucial aspect of development process has been the inadequate attention paid to Human Resource Development in India. Suggest measures that can address this adequacy."],["2019","10","Despite Consistent experience of High growth, India still goes with the lowest indicators of human development. Examine the issues that make balanced and inclusive development elusive."],["2016","12.5","Demographic Dividend in India will remain only theoretical unless our manpower becomes more educated, aware, skilled and creative. What measures have been taken by the government to enhance the capacity of our population to be more productive and employable?"],["2014","12.5","An athlete participates in Olympics for personal triumph and nation’s glory; victors are showered with cash incentives by various agencies, on their return. Discuss the merit of state sponsored talent hunt and its cultivation as against the rationale of a reward mechanism as encouragement."]]},{"id":"p129","name":"Miscellenous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","12.5","Professor Amartya Sen has advocated important reforms in the realms of primary education and primary health care. What are your suggestions to improve their status and performance?"]]},{"id":"p130","name":"Hunger","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","10","There is a growing divergence in the relationship between poverty and hunger in India. The shrinking of social expenditure by the government is forcing the poor to spend more on NonFood essential items squeezing their food – budget.- Elucidate."],["2018","15","How far do you agree with the view that the focus on lack of availability of food as the main cause of hunger takes the attention away from ineffective human development policies in India?"],["2013","10","The concept of Mid Day Meal (MDM) scheme is almost a century old in India with early beginnings in Madras Presidency in pre-independent India. The scheme has again been given impetus in most states in the last two decades. Critically examine its twin objectives, latest mandates and success."]]},{"id":"p131","name":"Poverty","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Inequality in the ownership pattern of resources is one of the major causes of poverty. Discuss in the context of ‘paradox of poverty’."],["2024","10","Poverty and malnutrition create a vicious cycle, adversely affecting human capital formation. What steps can be taken to break the cycle?"],["2022","15","Besides the welfare schemes, India needs deft management of inflation and unemployment to serve the poor and the underprivileged sections of the society. Discuss."],["2020","15","“The incidence and intensity of poverty are more important in determining poverty based on income alone”. In this context analyse the latest United Nations Multidimensional Poverty Index Report."],["2017","15","‘Poverty Alleviation Programmes in India remain mere show pieces until and unless they are backed by political will’. Discuss with reference to the performance of the major poverty alleviation programmes in India."],["2015","12.5","Though there have been several different estimates of poverty in India, all indicate reduction in poverty levels over time. Do you agree? Critically examine with reference to urban and rural poverty indicators."]]},{"id":"p132","name":"Miscellenous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","Hunger and Poverty are the biggest challenges for good governance in India still today. Evaluate how far successive governments have progressed in dealing with these humongous problems. Suggest measures for improvement."]]}]},{"name":"International Relations","chapters":[{"id":"p133","name":"Neighbourhood","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","India is an age-old friend of Sri Lanka.’ Discuss India’s role in the recent crisis in Sri Lanka the light of the preceding statement."],["2015","12.5","Project `Mausam’ is considered a unique foreign policy initiative of the Indian Government to improve relationship with its neighbors. Does the project have a strategic dimension? Discuss."],["2015","12.5","Terrorist activities and mutual distrust have clouded India-Pakistan relations. To what extent the use of soft power like sports and cultural exchanges could help generate goodwill between the two countries? Discuss with suitable examples."],["2013","10","Discuss the political developments in Maldives in the last two years. Should they be of any cause of concern to India?"],["2013","10","In respect of India-Sri Lanka relations, discuss how domestic factors influence foreign policy."],["2013","10","The protests in Shahbag Square in Dhaka in Bangladesh reveal a fundamental split in society between the nationalists and Islamic forces. What is its significance for India?"],["2013","10","What is meant by Gujral doctrine? Does it have any relevance today? Discuss."]]},{"id":"p134","name":"Bilateral Relations","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","India–Africa digital partnership is achieving mutual respect, co-development and long-term institutional partnerships. Elaborate."],["2024","10","Discuss the geopolitical and geostrategic importance of Maldives for India with a focus on global trade and energy flows. Further also discuss how this relationship affects India’s maritime security and regional stability amidst international competition?"],["2020","15","What is the significance of Indo-US defence deals over Indo-Russian defence deals? Discuss with reference to stability in the Indo-Pacific region."],["2019","10","‘The time has come for India and Japan to build a strong contemporary relationship, one involving global and strategic partnership that will have a great significance for Asia and the world as a whole.’ Comment."],["2019","15","“What introduces friction into the ties between India and the United States is that Washington is still unable to find for India a position in its global strategy, which would satisfy India’s National self-esteem and ambitions” Explain with suitable examples."],["2018","10","India’s relations with Israel have, of late, acquired a depth and diversity, which cannot be rolled back.” Discuss."],["2015","12.5","Increasing interest of India in Africa has its pros and cons. Critically examine."],["2014","12.5","With respect to the South China sea, maritime territorial disputes and rising tension affirm the need for safeguarding maritime security to ensure freedom of navigation and over flight throughout the region. In this context, discuss the bilateral issues between India and China."],["2013","10","Economic ties between India and Japan, while growing in recent years, are still far below their potential. Elucidate the policy constraints which are inhibiting this growth."]]},{"id":"p135","name":"Groupings beyond South Asia","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","How will I2U2 (India, Israel, UAE and USA) grouping transform India’s position in global politics ?"],["2021","10","“If the last few decades were of Asia’s growth story, the next few are expected to be of Africa’s.” In the light of this statement, examine India’s influence in Africa in recent years."],["2021","15","The newly tri-nation partnership AUKUS is aimed at countering China’s ambitions in the Indo-Pacific region. Is it going to supersede the existing partnerships in the region? Discuss the strength and impact of AUKUS in the present scenario."],["2020","15","‘Quadrilateral Security Dialogue (Quad)’ is transforming itself into a trade bloc from a military alliance, in present times - Discuss."]]},{"id":"p136","name":"Groupings involving Immediate and Extended neighbours","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Critically analyse India’s evolving diplomatic, economic and strategic relations with the Central Asian Republics (CARs) highlighting their increasing significance in regional and global geopolitics."],["2023","10","‘Virus of Conflict is affecting the functioning of the SCO’. In the light of the above statement point out the role of India in mitigating problems."],["2022","10","Do you think that BIMSTEC is a parallel organisation like the SAARC? What are the similarities and dissimilarities between the two? How are Indian foreign policy objectives realized by forming this new organisation?"],["2021","15","Critically examine the aims and objectives of SCO. What importance does it hold for India?"],["2016","12.5","Increasing cross-border terrorist attacks in India and growing interference in the internal affairs of several member-states by Pakistan are not conducive for the future of SAARC (South Asian Association for Regional Cooperation). Explain with suitable examples."],["2016","12.5","Evaluate the economic and strategic dimensions of India’s Look East Policy in the context of the post-Cold War international scenario."]]},{"id":"p137","name":"Energy X Foreign Policy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","“Energy security constitutes the dominant kingpin of India’s foreign policy, and is linked with India’s overarching influence in Middle Eastern countries.” How would you integrate energy security with India’s foreign policy trajectories in the coming years?"],["2022","15","Clean energy is the order of the day. Describe briefly India’s changing policy towards climate change in various international fora in the context of geopolitics."],["2017","15","The question of India’s Energy Security constitutes the most important part of India’s economic progress. Analyze India’s energy policy cooperation with West Asian Countries."]]},{"id":"p138","name":"Geo-politics affecting India’s Interest","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","With the waning of globalization, post-Cold War world is becoming a site of sovereign nationalism. Elucidate."],["2024","10","The West is fostering India as an alternative to reduce dependence on China’s supply chain and as a strategic ally to counter China’s political and economic dominance.’ Explain this statement with examples."],["2023","15","‘The expansion and strengthening of NATO and a stronger US-Europe strategic partnership works well in India.’ What is your opinion about this statement? Give reasons and examples to support your answer."],["2019","15","“The long-sustained image of India as a leader of the oppressed and marginalised Nations has disappeared on account of its new found role in the emerging global order”. Elaborate."],["2018","10","A number of outside powers have entrenched themselves in Central Asia, which is a zone of interest to India. Discuss the implications, in this context, of India’s joining the Ashgabat Agreement, 2018."],["2018","15","In what ways would the ongoing US-Iran Nuclear Pact Controversy affect the national interest of India? How should India respond to this situation?"],["2017","10","‘China is using its economic relations and positive trade surplus as tools to develop potential military power status in Asia’, In the light of this statement, discuss its impact on India as her neighbor."],["2013","10","The proposed withdrawal of International Security Assistance Force (ISAF) from Afghanistan in 2014 is fraught with major security implications for the countries of the region. Examine in light of the fact that India is faced with a plethora of challenges and needs to safeguard its own strategic interests."],["2013","10","What do you understand by ‘The String of Pearls’? How does it impact India? Briefly outline the steps taken by India to counter this."]]},{"id":"p139","name":"Indian Diaspora","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","Indian diaspora has scaled new heights in the West. Describe its economic and political benefits for India."],["2020","10","‘Indian diaspora has a decisive role to play in the politics and economy of America and European Countries’. Comment with examples."],["2017","15","Indian Diaspora has an important role to play in South-East Asian countries’ economy and society. Appraise the role of Indian Diaspora in SouthEast Asia in this context"]]},{"id":"p140","name":"Miscelleneous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","“The USA is facing an existential threat in the form of a China, that is much more challenging than the erstwhile Soviet Union.” Explain."]]},{"id":"p141","name":"International Funding Agencies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","12.5","Some of the International funding agencies have special terms for economic participation stipulating a substantial component of the aid to be used for sourcing equipment from the leading countries. Discuss on merits of such terms and if, there exists a strong case not to accept such conditions in the Indian context."],["2014","12.5","Some of the International funding agencies have special terms for economic participation stipulating a substantial component of the aid to be used for sourcing equipment from the leading countries. Discuss on merits of such terms and if, there exists a strong case not to accept such conditions in the Indian context."],["2014","12.5","India has recently signed to become founding a New Development Bank (NDB) and also the Asian Infrastructure Investment Bank (AIIB) .How will the role of the two Banks be different? Discuss the significance of these two Banks for India."],["2013","10","The World Bank and the IMF, collectively known as the Bretton Woods Institutions, are the two inter-governmental pillars supporting the structure of the world’s economic and financial order. Superficially, the World Bank and the IMF exhibit many common characteristics, yet their role, functions and mandate are distinctly different. Elucidate."]]},{"id":"p142","name":"United Nations and its Agencies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","“The reform process in the United Nations remains unresolved, because of the delicate imbalance of East and West and entanglement of the USA vs. Russo-Chinese alliance.” Examine and critically evaluate the East-West policy confrontations in this regard."],["2024","15","Terrorism has become a significant threat to global peace and security’. Evaluate the effectiveness of the United Nations Security Council’s Counter-Terrorism Committee (CTC) and its associated bodies in addressing and mitigating this threat at the international level."],["2023","15","‘Sea is an important Component of the Cosmos’. Discuss in the light of the above statement the role of the IMO(International Maritime Organisation) in protecting environment and enhancing maritime safety and security."],["2020","10","Critically examine the role of WHO in providing global health security during the Covid-19 pandemic."],["2019","10","‘Too little cash, too much politics, leaves UNESCO fighting for life.’ Discuss the statement in the light of US’ withdrawal and its accusation of the cultural body as being ‘anti-Israel bias’."],["2017","10","What are the main functions of the United Nations Economic and Social Council (ECOSOC)? Explain different functional commissions attached to it."],["2016","12.5","What are the aims and objectives of the McBride Commission of the UNESCO? What is India’s position on these?"],["2015","12.5","Discuss the impediments India is facing in its pursuit of a permanent seat in UN Security Council."]]},{"id":"p143","name":"WTO","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","15","What are the key areas of reform if the WTO has to survive in the present context of ‘Trade War’, especially keeping in mind the interest of India?"],["2016","12.5","The broader aims and objectives of WTO are to manage and promote international trade in the era of globalization. But the Doha round of negotiations seem doomed due to differences between the developed and the developing countries. Discuss in the Indian perspective."],["2014","12.5","The aim of Information Technology Agreements (ITAs) is to lower all taxes and tariffs on information technology products by signatories to zero. What impact should such agreements have on India’s interests?"],["2014","12.5","WTO is an important international institution where decisions taken affect countries in profound manner. What is the mandate of WTO and how binding are their decisions? Critically analyse India’s stand on the latest round of talks on Food security."]]}]}]},{"name":"GS III","subjects":[{"name":"Economic Development","chapters":[{"id":"p144","name":"Unemployment","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Most of the unemployment in India is structural in nature. Examine the methodology adopted to compute unemployment in the country and suggest improvements."],["2015","12.5","The nature of economic growth in India in described as jobless growth. Do you agree with this view? Give arguments in favour of your answer."]]},{"id":"p145","name":"Investment","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","15","Explain the meaning of investment in an economy in terms of capital formation. Discuss the factors to be considered while designing a concession agreement between a public entity and a private entity."]]},{"id":"p146","name":"Care X Monetized Economy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Distinguish between ‘care economy’ and ‘monetized economy’. How can care economy be brought into monetized economy through women empowerment?"]]},{"id":"p147","name":"Demographic Dividend","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","12.5","While we flaunt India’s demographic dividend, we ignore the dropping rates of employability. What are we missing while doing so? Where will the jobs that India desperately needs come from? Explain."]]},{"id":"p148","name":"Digitalization of Economy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","What is the status of digitalization in the Indian economy? Examine the problems faced in this regard and suggest improvements."]]},{"id":"p149","name":"GDP","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Explain the difference between computing methodology of India’s gross domestic product (GDP) before the year 2015 and after the year 2015."],["2020","10","Define potential GDP and explain its determinants. What are the factors that have been inhibiting India from realizing its potential GDP?"],["2019","10","Do you agree with the view that steady GDP growth and low inflation have left the Indian economy in good shape? Give reasons in support of your arguments."]]},{"id":"p150","name":"Monetary policy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What are the causes of persistent high food inflation in India? Comment on the effectiveness of the monetary policy of the RBI to control this type of inflation."]]},{"id":"p151","name":"Miscellaneous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","The increase in life expectancy in the country has led to newer health challenges in the community. What are those challenges and what steps need to be taken to meet them ?"]]},{"id":"p152","name":"Economic Growth","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","Economic growth in the recent past has been led by increase in labour activity.” Explain this statement. Suggest the growth pattern that will lead to creation of more jobs without compromising labour productivity."],["2021","15","Do you agree that the Indian economy has recently experienced a V-shaped recovery? Give reasons in support of your answer."],["2017","10","Among several factors for India’s potential growth, savings rate is the most effective one. Do you agree? What are the other factors available for growth potential?"]]},{"id":"p153","name":"Manufacturing Sector","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Discuss the rationale of the Production Linked Incentive (PLI) scheme. What are its achievements? In what way can the functioning and outcomes of the scheme be improved?"],["2025","15","India aims to become a semiconductor manufacturing hub. What are the challenges faced by the semiconductor industry in India? Mention the salient features of the India Semiconductor Mission."],["2023","10","Faster economic growth requires increased share of the manufacturing sector in GDP, particularly of MSMEs. Comment on the present policies of the Government in this regard."],["2015","12.5","Success of ‘Make in India’ programme depends on the success of ‘Skill India’ programme and radical labour reforms. Discuss with logical arguments."]]},{"id":"p154","name":"Niti Aayog X Planning Commission","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","15","How are the principles followed by the NITI Aayog different from those followed by the erstwhile Planning Commission in India?"]]},{"id":"p155","name":"GST","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","15","Explain the rationale behind the Goods and Services Tax (Compensation to States) Act of 2017. How has COVID-19 impacted the GST compensation fund and created new federal tensions?"],["2019","10","Enumerate the indirect taxes which have been subsumed in the Goods and Services Tax (GST) in India. Also, comment on the revenue implications of the GST introduced in India since July 2017."],["2013","10","Discussion the rationale for introducing Good and services tax in India. Bring out critically the reasons for delay in roll out for its regime."]]},{"id":"p156","name":"Corporate Social Responsibilty","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","With a consideration towards the strategy of inclusive growth, the new Companies Bill, 2013 has indirectly made CSR a mandatory obligation. Discuss the challenges expected in its implementation in right earnest. Also discuss other provisions in the Bill and their implications"]]},{"id":"p157","name":"Financial Inclusion","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","Is inclusive growth possible under market economy ? State the significance of financial inclusion in achieving economic growth in India."],["2016","12.5","Pradhan Mantri Jan-Dhan Yojana (PMJDY) is necessary for bringing unbanked to the institutional finance fold. Do you agree with this for financial inclusion of the poorer section of the Indian society? Give arguments to justify your opinion."]]},{"id":"p158","name":"Inclusive Growth","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Distinguish between the Human Development Index (HDI) and Inequality-adjusted Human Development Index (IHDI) with special reference to India. Why is the IHDI considered a better indicator of inclusive growth?"],["2017","15","What are the salient features of ‘inclusive growth’? Has India been experiencing such a growth process? Analyze and suggest measures for inclusive growth."],["2016","12.5","Comment on the challenges for inclusive growth which include careless and useless manpower in the Indian context. Suggest measures to be taken for facing these challenges."]]},{"id":"p159","name":"Inclusive Growth X Capitalism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","12.5","Capitalism has guided the world economy to unprecedented prosperity. However, it often encourages shortsightedness and contributes to wide disparities between the rich and the poor. In this light, would it be correct to believe and adopt capitalism driving inclusive growth in India? Discuss."]]},{"id":"p160","name":"Inclusive Growth X Infrastructure","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","15","Investment in infrastructure is essential for a more rapid and inclusive economic growth. Discuss in the light of India’s experience."],["2016","12.5","What are ‘Smart Cities? Examine their relevance for urban development in India. Will it increase rural-urban differences? Give arguments for Smart Villages’ in the light of PURA and RURBAN Mission."]]},{"id":"p161","name":"Inclusive Growth X Public Expenditure","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Examine the pattern and trend of public expenditure on social services in the post-reforms period in India. To what extent this has been in consonance with achieving the objective of inclusive growth?"]]},{"id":"p162","name":"Inclusive Growth X Sustainable Development","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","Explain intra-generational and inter-generational issues of equity from the perspective of inclusive growth and sustainable development."],["2019","15","It is argued that the strategy of inclusive growth is intended to meet the objectives of inclusiveness and sustainability together. Comment on this statement."]]},{"id":"p163","name":"Current Budget","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","Comment on the important changes introduced in respect of the Long-term Capital Gains Tax (LCGT) and Dividend Distribution Tax (DDT) in the Union Budget for 20182019."],["2017","15","One of the intended objectives of Union Budget 2017-18 is to ‘transform, energize and clean India’. Analyse the measures proposed in the Budget 2017-18 to achieve the objective."]]},{"id":"p164","name":"Gender Budgeting","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","12.5","Women empowerment in India needs gender budgeting. What are the requirements and status of gender budgeting in the Indian context?"]]},{"id":"p165","name":"Fiscal Policy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Explain how the Fiscal Health Index (FHI) can be used as a tool for assessing the fiscal performance of states in India. In what way would it encourage the states to adopt prudent and sustainable fiscal policies?"],["2021","10","Distinguish between capital budget and revenue budget. Explain the components of both these Budgets."],["2019","15","The public expenditure management is a challenge to the government of India in the context of budget-making during the post-liberalization period. Clarify it."],["2013","10","What are the reasons for introduction of Fiscal responsibility and Budget Management (FRBM) act, 2003? Discuss critically its salient features and their effectiveness."],["2013","10","What is meaning of the term tax-expenditure? Taking housing sector as an example, discuss how it influences budgetary policies of the government."]]},{"id":"p166","name":"Food Processing Sector","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Examine the scope of the food processing industries in India. Elaborate the measures taken by the government in the food processing industries for generating employment opportunities."],["2022","10","Elaborate the scope and significance of the food processing industry in India."],["2020","10","What are the challenges and opportunities of food processing sector in the country? How can income of the farmers be substantially increased by encouraging food processing?"],["2019","15","Elaborate on the policy taken by the government of India to meet the challenges of the food processing sector."],["2017","10","What are the reasons for poor acceptance of cost effective small processing unit? How the food processing unit will be helpful to uplift the socio-economic status of poor farmers?"],["2015","12.5","What are the impediments in marketing and supply chain management in developing the food processing industry in India? Can e-commerce help in overcoming these bottlenecks?"]]},{"id":"p167","name":"Revolutions and Missions","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","India needs to strengthen measures to promote the pink revolution in food industry for better nutrition and health. Critically elucidate the statement."]]},{"id":"p168","name":"Balance of Payment","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","Craze for gold in Indians have led to a surge in import of gold in recent years and put pressure on balance of payments and external value of rupee. In view of this, examine the merits of Gold Monetization Scheme."]]},{"id":"p169","name":"FDI","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","12.5","Justify the need for FDI for the development of the Indian economy. Why there is gap between MOUs signed and actual FDIs? Suggest remedial steps to be taken for increasing actual FDIs in India."],["2014","12.5","Foreign direct investment in the defence sector is now said to be liberalised. What influence this is expected to have on Indian defence and economy in the short and long run?"],["2013","5","Discuss the impact of FDI entry into multi-trade retail sector on supply chain management in commodity trade pattern of the economy."],["2013","5","Though India allowed foreign direct investment (FDI) in what is called multi brand retail through joint venture route in September 2012, the FDI even after a year, has not picket up. Discuss the reasons."]]},{"id":"p170","name":"LPG Reform and Impact","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","15","“Industrial growth rate has lagged behind in the overall growth of Gross-Domestic-Product(GDP) in the post-reform period” Give reasons. How far the recent changes in Industrial Policy are capable of increasing the industrial growth rate?"],["2016","12.5","How globalization has led to the reduction of employment in the formal sector of the Indian economy? Is increased informalization detrimental to the development of the country?"],["2014","12.5","Normally countries shift from agriculture to industry and then later to services, but India shifted directly from agriculture to services. What are the reasons for the huge growth of services vis-a-vis industry in the country? Can India become a developed country without a strong industrial base?"],["2013","10","Examine the impact of liberalization on companies owned by Indian. Are the competing with the MNCs satisfactorily?"]]},{"id":"p171","name":"Protectionism and Currency Manipulations","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","What are the challenges before the Indian economy when the world is moving away from free trade and multilateralism to protectionism and bilateralism? How can these challenges be met?"],["2018","15","How would the recent phenomena of protectionism and currency manipulations in world trade affect macroeconomic stability of India?"]]},{"id":"p172","name":"Special Economic Zones","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","There is a clear acknowledement that Special Economic Zones (SEZs) are a tool of industrial development, manufacturing and exports. Recognizing this potential, the whole instrumentality of SEZs requires augmentation. Discuss the issues plaguing the success of SEZs with respect to taxation, governing laws and administration."]]},{"id":"p173","name":"Labour-intensive X Capital-intensive Export","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","Account for the failure of the manufacturing sector in achieving the goal of labour-intensive exports. Suggest measures for more labour intensive rather capital-intensive export."]]},{"id":"p174","name":"Labour Reform","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","Discuss the merits and demerits of the four ‘Labour Codes’ in the context of labour market reforms in India. What has been the progress so far in this regard?"]]},{"id":"p175","name":"Airports X Infrastructure","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","What is the need for expanding the regional air connectivity in India? In this context, discuss the government’s UDAN Scheme and its achievements."],["2014","12.5","International civil aviation laws provide all countries complete and exclusive soverignity over the airspace above the territory. What do you understand by airspace? What are the implications of these laws on the space above this airspace? Discuss the challenges which this poses and suggests ways to contain the threat."]]},{"id":"p176","name":"PPP X Infrastructure","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","Why is Public Private Partnership (PPP) required in infrastructural projects ? Examine the role of PPP model in the redevelopment of Railway Stations in India."],["2017","10","Examine the developments of Airports in India through Joint Ventures under Public-Private Partnership(PPP) model. What are the challenges faced by the authorities in this regard."],["2014","12.5","Explain how private public partnership agreements, in longer gestation infrastructure projects, can transfer unsuitable liabilities to the future. What arrangements need to be put in place to ensure that successive generations’ capacities are not compromised?"],["2013","10","Adaptation of PPP model for infrastructure development of the country has not been free from criticism. Critically discuss the pros and cons of the model."]]},{"id":"p177","name":"Renewable Energy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","Do you think India will meet 50 percent of its energy needs from renewable energy by 2030 ? Justify your answer. How will the shift of subsidies from fossil fuels to renewables help achieve the above objective ? Explain."],["2020","15","Describe the benefits of deriving electric energy from sunlight in contrast to the conventional energy generation. What are the initiatives offered by our Government for this purpose?"],["2018","15","With growing energy needs should India keep on expanding its nuclear energy programme? Discuss the facts and fears associated with nuclear energy."],["2018","10","Access to affordable, reliable, sustainable and modern energy is the sine qua non to achieve Sustainable Development Goals (SDGs). Comment on the progress made in India in this regard."],["2016","12.5","Give an account of the current status and the targets to be achieved pertaining to renewable energy sources in the country. Discuss in brief the importance of National Programme on Light Emitting Diodes (LEDs)."],["2015","12.5","To what factors can the recent dramatic fall in equipment costs and tariff of solar energy be attributed? What implications does the trend have for the thermal power producers and the related industry?"],["2013","10","Write a note on India’s green energy corridor to alleviate the problems of conventional energy."],["2013","5","What do you understand by run of the river hydroelectricity project? How is it different from any other hydroelectricity project?"]]},{"id":"p178","name":"Transport","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","12.5","National urban transport policy emphasizes on moving people instead of moving vehicles. Discuss critically the success of various strategies of the government in this regard."]]}]},{"name":"Agriculture","chapters":[{"id":"p179","name":"Crop Diversification","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Explain the factors influencing the decision of the farmers on the selection of high value crops in India."],["2021","15","What is the present challenges before crop diversification? How do emerging technologies provide an opportunity for crop diversification?"],["2017","15","What are the major reasons for declining rice and wheat yield in the cropping system? How crop diversification is helpful to stabilize the yield of the crop in the system?"]]},{"id":"p180","name":"Cropping pattern","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Explain the changes in cropping pattern in India in the context of changes in consumption pattern and marketing conditions."],["2020","15","What are the major factors responsible for making rice-wheat system a success? In spite of this success how has this system become bane in India?"],["2018","15","How has the emphasis on certain crops brought about changes in cropping patterns in recent past? Elaborate the emphasis on millets production and consumption."],["2016","12.5","What is allelopathy? Discuss its role in major cropping systems of irrigated agriculture."]]},{"id":"p181","name":"Horticulture","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","15","Assess the role of National Horticulture Mission (NHM) in boosting the production, productivity and income of horticulture farms. How far has it succeeded in increasing the income of farmers?"]]},{"id":"p182","name":"Integrated Farming System","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","What is Integrated Farming System ? How is it helpful to small and marginal farmers in India ?"],["2019","10","How far is the Integrated Farming System (IFS) helpful in sustaining agricultural production?"]]},{"id":"p183","name":"Millets","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Explain the role of millets for ensuring health and nutritional security in India."]]},{"id":"p184","name":"Organic Farming","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","Sikkim is the first ‘Organic State’ in India. What are the ecological and economical benefits of Organic State?"]]},{"id":"p185","name":"Irrigation system","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","What are the major challenges faced by Indian irrigation system in recent times? State the measures taken by the government for efficient irrigation management."],["2020","15","Suggest measures to improve water storage and irrigation system to make its judicious use under depleting scenario."]]},{"id":"p186","name":"Micro-Irrigation","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","How and to what extent would micro-irrigation help in solving India’s water crisis?"],["2016","12.5","What is water-use efficiency? Describe the role of micro-irrigation in increasing the water-use efficiency."]]},{"id":"p187","name":"Water Conservation","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","What are the salient features of the Jal Shakti Abhiyan launches by the Government of India for water conservation and water security?"],["2019","10","Elaborate on the impact of the National Watershed Project in increasing agricultural production from water-stressed areas."]]},{"id":"p188","name":"Agri-Marketing","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Elaborate the scope and significance of supply chain management of agricultural commodities in India."],["2022","15","What are the main bottlenecks in upstream and downstream process of marketing of agricultural products in India ?"],["2020","10","What are the main constraints in transport & marketing of agricultural produce in India?"],["2018","10","Examine the role of supermarkets in supply chain management of fruits, vegetables and food items. How do they eliminate number of intermediaries?"],["2014","12.5","There is also a point of view that agriculture produce market committees (APMCs) set up under the state acts have not only impeded the development of agriculture but also have been the cause of food inflation in India. Critically examine."]]},{"id":"p189","name":"Tech in Agri Production and Marketing","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","How does e-Technology help farmers in production and marketing of agricultural produce? Explain it."]]},{"id":"p190","name":"Tech in Agriculture Credit","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","12.5","“In the villages itself no form of credit organization will be suitable except the cooperative society”. All India Rural Credit Survey. Discuss this statement in the background of agricultural finance in India. What constraints and challenges do financial institutions supplying agricultural finance face? How can technology be used to better reach and serve rural clients?"]]},{"id":"p191","name":"Tech in Farm Productivity and Income","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","How does nanotechnology offer significant advancements in the field of agriculture? How can this technology help to uplift the socio-economic status of farmers?"],["2015","12.5","How can the ‘Digital India’ programme help farmers to improve farm productivity and income? What steps has the Government taken in this regards?"]]},{"id":"p192","name":"Agriculture Subsidy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","What are the direct and indirect subsidies provided to farm sector in India? Discuss the issues raised by the World Trade Organization(WTO) in relation to agricultural subsidies."],["2015","12.5","In what way could replacement of price subsidy with Direct Benefit Transfer (DBT) change the scenario of subsidies in India? Discuss."],["2013","10","What are the different types of agriculture subsidies given to farmers at the national and state levels? Critically analyze the agriculture subsidy regime with the reference to the distortions created by it."]]},{"id":"p193","name":"Agriculture Vulnerability & Crop Insurance","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","12.5","Given the vulnerability of Indian agriculture to vagaries of nature, discuss the need for crop insurance and bring out the salient features of the Pradhan Mantri Fasal Bima Yojana (PMFBY)"]]},{"id":"p194","name":"Buffer stock & food security","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","Elucidate the importance of buffer stocks for stabilizing agricultural prices in India. What are the challenges associated with the storage of buffer stock? Discuss."],["2013","10","Food security bill is expected to eliminate hunger and malnutrition in India. Critically discuss various apprehensions in its effective implementation along with the concerns it has generated in WTO."]]},{"id":"p195","name":"Miscellaneous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","15","How do subsidies affect the cropping pattern, crop diversity and economy of farmers? What is the significance of crop insurance, minimum support price and food processing for small and marginal farmers?"]]},{"id":"p196","name":"MSP","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","What do you mean by Minimum Support Price (MSP)? How will MSP rescue the farmers from the low income trap?"]]},{"id":"p197","name":"PDS","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","What are the major challenges of Public Distribution System (PDS) in India ? How can it be made effective and transparent ?"],["2021","15","What are the salient features of the National Food Security Act, 2013? How has the Food Security Bill helped in eliminating hunger and malnutrition in India?"],["2019","15","What are the reformative steps taken by the government to make food grain distribution system more effective?"]]},{"id":"p198","name":"Revolutions and Missions","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","Explain various types of revolutions, took place in Agriculture after Independence in India. How these revolutions have helped in poverty alleviation and food security in India?"]]},{"id":"p199","name":"Non-Farm Activities (Livestock)","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","Livestock rearing has a big potential for providing non-farm employment and income in rural areas. Discuss suggesting suitable measures to promote this sectors in India"]]},{"id":"p200","name":"Act based","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","12.5","The right to fair compensation and transparency land acquisition, rehabilitation and resettlement act, 2013 has come into effect from 1 January 2014. What implication would it have on industrialisation and agriculture in India?"]]},{"id":"p201","name":"Contract farming & Land leasing","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","In view of the declining average size of land holdings in India which has made agriculture non-viable for a majority of farmers, should contract farming and land leasing be promoted in agriculture? Critically evaluate the pros and cons."]]},{"id":"p202","name":"Land Reforms","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What were the factors responsible for the successful implementation of land reforms in some parts of the country? Elaborate."],["2023","10","State the objectives and measures of land reforms in India. Discuss how land ceiling policy on landholding can be considered as an effective reform under economic criteria."],["2021","10","How did land reforms in some parts of the country help to improve the socio-economic conditions of marginal and small farmers?"],["2016","12.5","Discuss the role of land reforms in agricultural development. Identify the factors that were responsible for the success of land reforms in India."]]},{"id":"p203","name":"Miscellaneous","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","Establish the relationship between land reform, agriculture productivity and elimination of poverty in Indian Economy. Discussion the difficulty in designing and implementation of the agriculture friendly land reforms in India."]]}]},{"name":"Science & Technology","chapters":[{"id":"p204","name":"Innovative Technologies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","5","How does the 3D printing technology work? List out the advantages and disadvantages of the technology."],["2013","5","What is digital signature? What does its authentication mean? Giver various salient built in features of a digital signature."]]},{"id":"p205","name":"Material Science and Industry Applications","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","5","What is an FRP composite material? How are they manufactured? Discuss their applications in aviation and automobile industry"]]},{"id":"p206","name":"Medical and Health Technologies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","What is the basic principle behind vaccine development? How do vaccines work? What approaches were adopted by the Indian vaccine manufacturers to produce COVID-19 vaccines ?"],["2017","10","Stem cell therapy is gaining popularity in India to treat a wide variety of medical conditions including Leukaemia, Thalassemia, damaged cornea and several burns. Describe briefly what stem cell therapy is and what advantages it has over other treatments?"],["2014","12.5","Can overuse and the availability of antibiotics without doctor’s prescription, the contributors to the emergence of drug-resistant diseases in India? What are the available mechanisms for monitoring and control? Critically discuss the various issues involved."],["2013","10","What do you understand by fixed dose drug combinations (FDCs)? Discuss their merits and demerits."]]},{"id":"p207","name":"General Science","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","Each year a large amount of plant material, cellulose, is deposited on the surface of Planet Earth. What are the natural processes this cellulose undergoes before yielding carbon dioxide, water and other end products ?"]]},{"id":"p208","name":"Nobel Prizes","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","15","The Nobel Prize in Physics of 2014 was jointly awarded to a Akasaki, Amano and Nakamura for the invention of Blue LEDs in1990s. How has this invention impacted the everyday life of human beings?"]]},{"id":"p209","name":"Sports and Technology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","What do you understand by Umpire decision review in cricket? Discuss its various components. Explain how silicon tape on the edge of a bat may fool the system?"]]},{"id":"p210","name":"Tech in crisis Management","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","The world is facing an acute shortage of clean and safe freshwater. What are the alternative technologies which can solve this crisis? Briefly discuss any three such technologies citing their key merits and demerits."],["2020","15","COVID-19 pandemic has caused unprecedented devastation worldwide. However, technological advancements are being availed readily to win over the crisis. Give an account of how technology was sought to aid management to the pandemic."]]},{"id":"p211","name":"Tech solutions for daily challenges","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What is the technology being employed for electronic toll collection on highways? What are its advantages and limitations? What are the proposed changes that will make this process seamless? Would this transition carry any potential hazards?"],["2020","10","How is science interwoven deeply with our lives? What are the striking changes in agriculture triggered off by the science-based technologies?"]]},{"id":"p212","name":"Achievements of Indians in S&T","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","10","How was India benefited from the contributions of Sir M.Visvesvaraya and Dr. M. S. Swaminathan in the fields of water engineering and agricultural science respectively?"],["2018","10","Discuss the work of ‘Bose-Einstein Statistics’ done by Prof. Satyendra Nath Bose and show how it revolutionized the field of Physics."],["2014","12.5","Scientific research in Indian universities is declining, because a career in science is not as attractive as our business operations, engineering or administration, and the universities are becoming consumer oriented. Critically comment."]]},{"id":"p213","name":"Nuclear Technology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","The fusion energy programme in India has steadily evolved over the past few decades. Mention India’s contributions to the international fusion energy project International Thermonuclear Experimental Reactor (ITER). What will be the implications of the success of this project for the future of global energy?"],["2017","15","Give an account of the growth and development of nuclear science and technology in India. What is the advantage of fast breeder reactor programme in India?"]]},{"id":"p214","name":"Artificial Intelligence","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","Introduce the concept of Artificial Intelligence (AI). How does AI help clinical diagnosis? Do you perceive any threat to privacy of the individual in the use of AI in the healthcare?"]]},{"id":"p215","name":"Bio-Technology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","How can India achieve energy independence through clean technology by 2047? How can biotechnology play a crucial role in this endeavour?"],["2023","10","Discuss several ways in which microorganisms can help in meeting the current fuel shortage."],["2021","15","What are the research and developmental achievements in applied biotechnology? How will these achievements help to uplift the poor sections of the society?"],["2019","15","How can biotechnology improve the living standards of farmers?"],["2018","15","Why is there so much activity in the field of biotechnology in our country? How has this activity benefitted the field of biopharma?"]]},{"id":"p216","name":"Defence Technology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","How is S-400 air defence system technically superior to any other system presently available in the world?"]]},{"id":"p217","name":"Intellectual Property Rights","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What is the present world scenario of intellectual property rights with respect to life materials? Although, India is second in the world to file patents, still only a few have been commercialized. Explain the reasons behind this less commercialization."],["2019","15","How is the government of India protecting traditional knowledge of medicine from patenting by pharmaceutical companies?"],["2015","12.5","India’s Traditional Knowledge Digital Library (TKDL) which has a database containing formatted information on more than 2 million medicinal formulations is proving a powerful weapon in the country’s fight against erroneous patents. Discuss the pros and cons making this database publicly available under open-source licensing"],["2014","12.5","In a globalised world, intellectual property rights assume significance and are a source of litigation. Broadly distinguish between the terms – copyrights, patents and trade secrets."],["2013","10","Bring out the circumstances in 2005 which forced amendment to section 3(d) in the Indian Patent Law, 1970. Discuss how it has been utilized by Supreme court in its judgment rejecting Novartis patent application for “Glivec”. Discuss briefly the pros and cons of the decision."]]},{"id":"p218","name":"IT","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","Discuss the advantage and security implications of cloud hosting of servers vis-a-vis in-house machine-based hosting for government businesses."]]},{"id":"p219","name":"Nano Technology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","What do you understand by nanotechnology and how is it helping in health sector?"],["2016","12.5","Why is nanotechnology one of the key technologies of the 21st century? Describe the salient features of Indian Government’s Mission on Nanoscience and Technology and the scope of its application in the development process of the country."]]},{"id":"p220","name":"Robotics","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","12.5","What are the areas of prohibitive labour that can be sustainably managed by robots? Discuss the initiatives that can propel research in premier research institutes for substantive and gainful innovation."]]},{"id":"p221","name":"Space Technology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","What are asteroids? How real is the threat of them causing extinction of life? What strategies have been developed to prevent such a catastrophe?"],["2023","15","What is the main task of India’s third mood mission which could not be achieved in its earlier mission? List the countries that have achieved this task. Introduce the subsystems in the spacecraft launched and explain the role of the ‘Virtual Launch Control Centre’ at the Vikram Sarabhai Space Centre which contributed to the successful launch from Sriharikota"],["2022","15","Launched on 25th December, 2021, James Webb Space Telescope has been much in the news since then. What are its unique features which make it superior to its predecessor Space Telescopes ? What are the key goals of this mission ? What potential benefits does it hold for the human race?"],["2019","10","What is India’s plan to have its own space station and how will it benefit our space programme?"],["2017","10","India has achieved remarkable successes in unmanned space missions including the Chandrayaan and Mars Orbitter Mission, but has not ventured into manned space mission, both in terms of technology and logistics? Explain critically."],["2016","12.5","Discuss India’s achievements in the field of Space Science and Technology. How the application of this technology has helped India in its socio-economic development?"],["2015","12.5","What do you understand by ‘Standard Positioning Systems’ and ‘Protection Positioning Systems’ in the GPS era? Discuss the advantages India perceives from its ambitious IRNSS programme employing just seven satellites."]]}]},{"name":"Environment","chapters":[{"id":"p222","name":"Biodiversity","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","15","How does biodiversity vary in India? How is the Biological Diversity Act, 2002 helpful in conservation of flora and fauna?"]]},{"id":"p223","name":"Climate Change","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","15","‘Climate Change’ is a global problem. How India will be affected by climate change? How Himalayan and coastal states of India will be affected by climate change?"]]},{"id":"p224","name":"Sustainable Development","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","15","Define the concept of carrying capacity of an ecosystem as relevant to an environment. Explain how understanding this concept is vital while planning for sustainable development of a region."]]},{"id":"p225","name":"EIA","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","What role do environmental NGOs and activists play in influencing Environmental Impact Assessment (EIA) outcomes for major projects in India? Cite four examples with all important details."],["2020","10","How does the draft Environment Impact Assessment (EIA) Notification, 2020 differ from the existing EIA Notification, 2006?"],["2016","12.5","Rehabilitation of human settlements is one of the important environmental impacts which always attracts controversy while planning major projects. Discuss the measures suggested for mitigation of this impact while proposing major developmental projects."],["2014","12.5","Environmental impact assessment studies are increasingly undertaken before project is cleared by the government. Discuss the environmental impacts of coal-fired thermal plants located at Pitheads."]]},{"id":"p226","name":"Air Pollution and Related Issues","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","What is Carbon Capture, Utilization and Storage (CCUS)? What is the potential role of CCUS in tackling climate change?"],["2022","10","Discuss in detail the photochemical smog emphasizing its formation, effects and mitigation. Explain the 1999 Gothenburg Protocol."],["2021","10","Describe the key points of the revised Global Air-Quality Guidelines (AQGs) recently released by the World Health Organisation (WHO). How are these different from its last update in 2005? What changes in India’s National Clean Air Programme are required to achieve these revised standards?"],["2020","15","What are the key features of the National Clean Air Programme (NCAP) initiated by the Government of India?"]]},{"id":"p227","name":"Solid wastes","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","What are the impediments in disposing the huge quantities of discarded solid wastes which are continuously being generated? How do we remove safely the toxic wastes that have been accumulating in our habitable environment?"]]},{"id":"p228","name":"Water Pollution and Related Issues","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Examine the factors responsible for depleting groundwater in India. What are the steps taken by the government to mitigate such depletion of groundwater?"],["2025","10","Seawater intrusion in the coastal aquifers is a major concern in India. What are the causes of seawater intrusion and the remedial measures to combat this hazard?"],["2024","10","Industrial pollution of river water is a significant environmental issue in India. Discuss the various mitigation measures to deal with this problem and also the government’s initiatives in this regard."],["2023","10","What is oil pollution? What are its impacts on the marine ecosystem? In what way is oil pollution particularly harmful for a country like India?"],["2015","12.5","The Namami Gange and National mission for clean Ganga (NMCG) programmes and causes of mixed results from the previous schemes. What quantum leaps can help preserve the river Ganga better than incremental inputs?"],["2013","10","Enumerate the National Water Policy of India. Taking river Ganges as an example, discuss the strategies which may be adopted for river water pollution control and management. What are the legal provisions for management and handling of hazardous wastes in India?"]]},{"id":"p229","name":"EVs","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","The adoption of electric vehicles is rapidly growing worldwide. How do electric vehicles contribute to reducing carbon emissions and what are the key benefits they offer compared to traditional combustion engine vehicles?"]]},{"id":"p230","name":"IPCC Reports","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","The Intergovernmental Panel on Climate Change(IPCC) has predicted a global sea level rise of about one metre by AD 2100. What would be its impact in India and the other countries in the Indian Ocean region?"]]},{"id":"p231","name":"Mining and Erosion","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Mineral resources are fundamental to the country economy and these are exploited by mining. Why is mining considered an environmental hazard? Explain the remedial measures required to reduce the environmental hazard due to mining."],["2022","15","Explain the causes and effects of coastal erosion in India. What are the available coastal management techniques for combating the hazard ?"],["2019","10","Coastal sand mining, whether legal or illegal, poses one of the biggest threats to our environment. Analyse the impact of sand mining along the Indian coasts, citing specific examples."],["2013","10","What are the consequences of illegal mining? Discuss the ministry of environment and forests’ concept of “GO AND NO GO” zones for coal mining."]]},{"id":"p232","name":"River Iinking and Impact","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","Not many years ago, river linking was a concept but it is becoming reality in the country. Discuss the advantages of river linking and its possible impact on the environment."]]},{"id":"p233","name":"UNFCCC","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Write a review on India’s climate commitments under the Paris Agreement (2015) and mention how these have been further strengthened in COP26 (2021). In this direction, how has the first Nationally Determined Contribution (NDC) intended by India been updated in 2022?"],["2022","15","Discuss global warming and mention its effects on the global climate. Explain the control measures to bring down the level of greenhouse gases which cause global warming, in the light of the Kyoto Protocol, 1997."],["2021","15","Describe the major outcomes of the 26th session of the Conference of the Parties (COP) to the United Nations Framework Convention on Climate Change (UNFCCC). What are the commitments made by India in this conference?"],["2021","10","Explain the purpose of the Green Grid Initiative launched at world leaders Summit of the COP 26 UN Climate Change Conference in Glassgow in November, 2021. When was this idea first floated in the International Solar Alliance (ISA)?"],["2014","12.5","Should the pursuit of carbon credit and clean development mechanism set up under UNFCCC be maintained even through there has been a massive slide in the value of carbon credit? Discuss with respect to India’s energy needs for economic growth."]]},{"id":"p234","name":"Wetlands","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","Comment on the National Wetland Conservation Programme initiated by the Government of India and name a few India’s wetlands of international importance included in the Ramsar Sites."],["2018","10","What is wetland? Explain the Ramsar concept of ‘wise use’ in the context of wetland conservation. Cite two examples of Ramsar sites from India."]]}]},{"name":"Disaster Management","chapters":[{"id":"p235","name":"Cloudburst","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","Explain the mechanism and occurrence of cloudburst in the context of the Indian subcontinent. Discuss two recent examples."],["2016","12.5","With reference to National Disaster Management Authority (NDMA) guidelines, discuss the measures to be adopted to mitigate the impact of the recent incidents of cloudbursts in many places of Uttarakhand."]]},{"id":"p236","name":"Disaster Preparedness and Resilience","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","What is disaster resilience? How is it determined? Describe various elements of a resilience framework. Also mention the global targets of the Sendai Framework for Disaster Risk Reduction (2015-2030)."],["2020","15","Discuss the recent measures initiated in disaster management by the Government of India departing from the earlier reactive approach."],["2019","15","Disaster preparedness is the first step in any disaster management process. Explain how hazard zonation mapping will help in disaster mitigation in the case of landslides."],["2018","15","Describe various measures taken in India for Disaster Risk Reduction (DRR) before and after signing ‘Sendai Framework for DRR (2015-2030)’. How is this framework different from ‘Hyogo Framework for Action, 2005?"]]},{"id":"p237","name":"Vulnerability and Risk Assessment","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","10","Vulnerability is an essential element for defining disaster impacts and its threat to people. How and in what ways can vulnerability to disasters be characterized? Discuss different types of vulnerability with reference to disasters."],["2013","10","How important are vulnerability and risk assessment for pre-disaster management. As an administrator ,what are key areas that you would focus in a disaster management"]]},{"id":"p238","name":"Drought","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","12.5","Drought has been recognised as a disaster in view of its party expense, temporal duration, slow onset and lasting effect on various vulnerable sections. With a focus on the September 2010 guidelines from the National disaster management authority, discuss the mechanism for preparedness to deal with the El Nino and La Nina fallouts in India."]]},{"id":"p239","name":"Earthquake","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Discuss about the vulnerability of India to earthquake related hazards. Give examples including the salient features of major disasters caused by earthquakes in different parts of India during the last three decades."],["2015","12.5","The frequency of earthquakes appears to have increased in the Indian subcontinent. However, India’s preparedness for mitigating their impact has significant gaps. Discuss various aspects."]]},{"id":"p240","name":"Landslide","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","15","Describe the various causes and effects of landslides. Mention the important components of the National Landslide Risk Management Strategy."]]},{"id":"p241","name":"Dam failures","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","Dam failures are always catastrophic, especially on the downstream side, resulting in a colossal loss of life and property. Analyze the various causes of dam failures. Give two examples of large dam failures."]]},{"id":"p242","name":"Tsunami","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","15","On December 2004, tsumani brought havoc on 14 countries including India. Discuss the factors responsible for occurrence of Tsunami and its effects on life and economy. In the light of guidelines of NDMA (2010) describe the mechanisms for preparedness to reduce the risk during such events."]]},{"id":"p243","name":"Urban floods","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","Flooding in urban areas is an emerging climate-induced disaster. Discuss the causes of this disaster. Mention the features of two such major floods in the last two decades in India. Describe the policies and frameworks in India that aim at tackling such floods."],["2016","12.5","The frequency of urban floods due to high intensity rainfall is increasing over the years. Discussing the reasons for urban floods. highlight the mechanisms for preparedness to reduce the risk during such events."]]}]},{"name":"Internal Security","chapters":[{"id":"p244","name":"Left-Wing Extremism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","The Government of India recently stated that Left Wing Extremism (LWE) will be eliminated by 2026. What do you understand by LWE and how are the people affected by it? What measures have been taken by the government to eliminate LWE?"],["2022","15","Naxalism is a social, economic and developmental issue manifesting as a violent internal security threat. In this context, discuss the emerging issues gest a multilayered strategy to tackle the menace of Naxalism."],["2020","15","What are the sound determinants of left-wing extremism in Eastern part of India? What strategy should Government of India, civil administration and security forces adopt to counter the threat in the affected areas?"],["2018","10","Left Wing Extremism (LWE) is showing a downward trend, but still affects many parts of the country. Briefly explain the Government of India’s approach to counter the challenges posed by LWE."],["2015","12.5","The persisting drives of the government for development of large industries in backward areas have resulted in isolating the tribal population and the farmers who face multiple displacements with Malkangiri and naxalbari foci, discuss the corrective strategies needed to win the left wing extremism (LWE) doctrine affected citizens back into the mainstream of social and economic growth."],["2013","10","Article 244 of Indian Constitution relates to Administration of Scheduled areas and tribal areas. Analyze the impact of non-implementation of the provisions of fifth schedule on the growth of Left Wing Extremism."]]},{"id":"p245","name":"N-E Insurgency","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","What are the major challenges to internal security and peace process in the North-Eastern States? Map the various peace accords and agreements initiated by the government in the past decade."],["2017","10","The north-eastern region of India has been infested with insurgency for a very long time. Analyze the major reasons for the survival of armed insurgency in this region."]]},{"id":"p246","name":"Threat from External state and Non-state actors","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","15","Analyse the multidimensional challenges posed by external state and non-state actors, to the internal security of India. Also discuss measures required to take to be taken to combat the threats."],["2018","10","The China-Pakistan Economic Corridor (CPEC) is viewed as a cardinal subset of China’s larger ‘One Belt One Road’ initiative. Give a brief description of CPEC and enumerate the reasons why India has distanced itself from the same."],["2016","12.5","Use of Internet and social media by non-state actors for subversive activities is a major concern. How have these have misused in the recent past? Suggest effective guidelines to curb the above threat."],["2014","12.5","The diverse nature of India as a multi-religious and multi-ethnic society is not immune to the impact of radicalism which has been in her neighbourhood. Discuss along with the strategies to be adopted to counter this environment."],["2014","12.5","China and Pakistan have entered into an agreement for development of an economic corridor. What thread does it dispose for India’s security? Critically examine."]]},{"id":"p247","name":"Act based","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Describe the context and salient features of the Digital Personal Data Protection Act, 2023."]]},{"id":"p248","name":"Cyber security","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","15","What are the different elements of cyber security ? Keeping in view the challenges in cyber security, examine the extent to which India has successfully developed a comprehensive National Cyber Security Strategy."],["2021","10","Keeping in view India’s internal security, analyse the impact of cross-border cyber attacks. Also discuss defensive measures against these sophisticated attacks."],["2020","10","Discuss different types of cyber crimes and measures required to be taken to fight the menace."],["2019","10","What is the CyberDome Project? Explain how it can be useful in controlling internet crimes in India."],["2018","15","Data security has assumed significant importance in the digitized world due to rising cyber crimes. The Justice B. N. Srikrishna Committee Report addresses issues related to data security. What, in your view, are the strengths and weakness of the Report relating to protection of personal data in cyber space?"],["2017","10","Discuss the potential threats of Cyber attack and the security framework to prevent it."],["2015","12.5","Considering the threats cyberspace poses for the country, India needs a “Digital Armed Force” to prevent crimes. Critically evaluate the National Cyber Security Policy, 2013 outlining the challenges perceived in its effective implementation."],["2013","10","Cyber warfare is considered by some defense analysts to be a larger threat than even Al Qaeda or terrorism. What do you understand by Cyber warfare? Outline the cyber threats which India is vulnerable to and bring out the state of the country’s preparedness to deal with the same."]]},{"id":"p249","name":"Drug trafficking","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","15","India’s proximity to two of the world’s biggest illicit opium-growing states has enhanced her internal security concerns. Explain the linkages between drug trafficking and other illicit activities such as gunrunning, money laundering and human trafficking. What counter-measures should be taken to prevent the same?"]]},{"id":"p250","name":"Mob Violence","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","15","Mob violence is emerging as a serious law and order problem in India. By giving suitable examples, analyze the causes and consequences of such violence."]]},{"id":"p251","name":"Money-laundering and Prevention","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Discuss how emerging technologies and globalisation contribute to money laundering. Elaborate measures to tackle the problem of money laundering both at national and international levels."],["2013","10","Money laundering poses a serious threat to country’s economic sovereignty. What is its significance for India and what steps are required to be taken to control this menace?"]]},{"id":"p252","name":"Digital Media and Security Threats","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","Social media and encrypting messaging services pose a serious security challenge. What measures have been adopted at various levels to address the security implications of social media? Also suggest any other remedies to address the problem."],["2015","12.5","Religious indoctrination via digital media has resulted in Indian youth joining the ISIS. What is ISIS and its mission? How can ISIS be dangerous for the internal security of our country?"],["2013","10","What are social networking site and what security implications do these sites present?"]]},{"id":"p253","name":"Border Area Management","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","India has a long and troubled border with China and Pakistan fraught with contentious issues. Examine the conflicting issues and security challenges along the border. Also give out the development being undertaken in these areas under the Border Area Development Programme (BADP) and Border Infrastructure and Management (BIM) Scheme."],["2023","10","The use of unmanned aerial vehicles(UAVs) by our adversaries across the borders to ferry arms/ammunitions, drugs, etc., is a serious threat to the internal security. Comment on the measures being taken to tackle this threat."],["2020","10","For effective border area management, discuss the steps required to be taken to deny local support to militants and also suggest ways to manage favourable perception among locals."],["2019","15","Cross-border movement of insurgents is only one of the several security challenges facing the policing of the border in North-East India. Examine the various challenges currently emanating across the India-Myanmar border. Also, discuss the steps to counter the challenges."],["2016","12.5","Border management is a complex task due to difficult terrain and hostile relations with some countries. Elucidate the challenges and strategies for effective border management."],["2014","12.5","How illegal transborder migration does pose a threat to India’s security? Discuss the strategies to curb this, bring out the factors which give impetus to such migration."],["2013","10","How far are India’s internal security challenges linked with border management, particularly in view of the long porous borders with most countries of South Asia and Myanmar?"]]},{"id":"p254","name":"Maritime Security challenges","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Why is maritime security vital to protect India’s sea trade? Discuss maritime and coastal security challenges and the way forward."],["2022","10","What are the maritime security challenges in India ? Discuss the organisational, technical and procedural initiatives taken to improve the maritime security."],["2014","12.5","In 2012, the longitudinal marking of the high-risk areas for piracy was moved from 65° East to 78° east in the Arabian Sea by International Maritime organisation. What impact does this have on India’s maritime security concerns?"]]},{"id":"p255","name":"Organized Crime and Terrorism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Terrorism is a global scourge. How has it manifested in India? Elaborate with contemporary examples. What are the counter measures adopted by the State? Explain."],["2024","10","Explain how narco-terrorism has emerged as a serious threat across the country. Suggest suitable measures to counter narco-terrorism."],["2023","15","Give out the major sources of terror funding in India and efforts being made to curtail these sources. In the light of this, also discuss the aim and objective of the ‘ No Money for Terror [NMFT]’ Conference recently held at New Delhi in November 2022."],["2023","10","Winning of ‘Hearts and Minds’ in terrorism affected areas is an essential step in restoring the trust of the population. Discuss the measures adopted by the Government in this respect as part of the conflict resolution in Jammu and Kashmir."],["2022","10","Discuss the types of organised crimes. Describe the linkages between terrorists and organised crime that exist at the national and transnational levels."],["2021","15","Analyse the complexity and intensity of terrorism, its causes, linkages and obnoxious nexus. Also suggest measures required to be taken to eradicate the menace of terrorism."],["2019","10","The banning of ‘Jamaat-e – islaami’ in Jammu and Kashmir brought into focus the role of over-ground workers (OGWs) in assisting terrorist organizations. Examine the role played by OGWs in assisting terrorist organizations in insurgency affected areas. Discuss measures to neutralize the influence of OGWs."],["2017","15","The scourge of terrorism is a grave challenge to national security. What solutions do you suggest to curb this growing menace? What are the major sources of terrorist funding?"],["2016","12.5","Terrorism is emerging as a competitive industry over the last few decades. Analyse the above statement."],["2016","12.5","The terms ‘Hot Pursuit’ and ‘Surgical Strikes’ are often used in connection with armed action against terrorist attacks. Discuss the strategic impact of such actions."]]},{"id":"p256","name":"Act based","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","15","The Indian government has recently strengthened the anti-terrorism laws by amending the Unlawful activities (Prevention) Act (UAPA), 1967 and the NIA Act. Analyze the changes in the context of prevailing security environment while discussing the scope and reasons for opposing the UAPA by human rights organizations."],["2015","12.5","Human rights activists constantly highlight the view that the Armed Forces (Special Powers) Act, 1958 (AFSPA) is a draconian act leading to cases of human rights abuses by the security forces. What sections of AFSPA are opposed by the activists? Critically evaluate the requirement with reference to the view held by the Apex Court."]]},{"id":"p257","name":"Mandates of Security forces","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","15","What are the internal security challenges being faced by India? Give out the role of Central Intelligence and Investigative Agencies tasked to counter such threats."],["2020","15","Analyze internal security threats and transborder crimes along Myanmar, Bangladesh and Pakistan borders including Line of Control (LoC). Also discuss the role played by various security forces in this regard."]]}]}]},{"name":"GS IV","subjects":[{"name":"Ethics","chapters":[{"id":"p258","name":"Applied Ethics x Environment","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Keeping the national security in mind, examine the ethical dilemmas related to controversies over environmental clearance of development projects in ecologically sensitive border areas in the country."],["2024","10","Gobal warming and climate change are the outcomes of human greed in the name of development, indicating the direction in which extinction of organisms including human beings is heading towards loss of life on Earth. How do you put an end to this to protect life and bring equilibrium between the society and the environment ?"],["2018","10","Suppose the Government of India is thinking of constructing a dam in a mountain valley bound by forests and inhabited by ethnic communities. What rational policy should it resort to in dealing with unforeseen contingencies?"],["2015","10","What is meant by ‘environmental ethics’? Why is it important to study? Discuss any one environmental issue from the viewpoint of environmental ethics."]]},{"id":"p259","name":"Applied Ethics x Technology","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","In the present digital age, social media has revolutionised our way of communication and interaction. However, it has raised several ethical issues and challenges. Describe the key ethical dilemmas in this regard."],["2024","10","The application of Artificial Intelligence as a dependable source of input for administrative rational decision-making is a debatable issue. Critically examine the statement from the ethical point of view."],["2022","10","Online methodology is being used for day-to-day meetings, institutional approvals in the administration and for teaching and learning in education sector to the extent telemedicine in the health sector is getting popular with the approvals of the competent authority. No doubt it has advantages and disadvantages for both the beneficiaries and system at large. Describe and discuss the ethical issues involved in the use of online method particularly to vulnerable section of society."],["2021","10","Impact of digital technology as a reliable source of input for rational decision making is a debatable issue. Critically evaluate with a suitable example."],["2020","10","The current internet expansion has instilled a different set of cultural values which are in conflict with traditional values. Discuss."]]},{"id":"p260","name":"Consequences of Ethics","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","It is believed that adherence to ethics in human actions would ensure in smooth functioning of an organization/system. If so, what does ethics seek to promote in human life? How do ethical values assist in the resolution of conflicts faced by him in his day-to-day functioning?"],["2020","10","Discuss the role of ethics and values in enhancing the following three major components of Comprehensive National Power (CNP) viz. human capital, soft power (culture and policies), and social harmony."],["2017","10","Increased national wealth did not result in equitable distribution of its benefits. It has created only some “enclaves of modernity and prosperity for a small minority at the cost of the majority.” Justify."],["2016","10","Explain how ethics contributes to social and human well-being."],["2014","10","The current society is plagued with widespread trust-deficit. What are the consequences of this situation for personal well-being and for societal well-being? What can you do at the personal level to make yourself trustworthy?"]]},{"id":"p261","name":"Normative Ethics (Deontology vs Teleology)","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","With regard to morality of actions, one view is that means are of paramount importance and the other view is that the ends justify the means. Which view do you think is more appropriate? Justify your answer."],["2014","10","Human beings should always be treated as ‘ends’ in themselves and never as merely ‘means’. Explain the meaning and significance of this statement, giving its implications in the modern techno-economic society."]]},{"id":"p262","name":"Determinants of Ethics","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","“The concept of Just and Unjust is contextual. What was just a year back, may turn out to be unjust in today’s context. Changing context should be constantly under scrutiny to prevent miscarriage of justice.” Examine the above statement with suitable examples."],["2024","10","“Ethics encompasses several key dimensions that are crucial in guiding individuals and organizations towards morally responsible behaviour.” Explain the key dimensions of ethics that influence human actions Discuss how these dimensions shape ethical decision-making in the professional context."],["2017","10","Without commonly shared and widely entrenched moral values and obligations, neither the law, nor democratic government, nor even the market economy will function properly. What do you understand by this statement? Explain with illustration in the contemporary times."],["2013","10","Some people feel that values keep changing with time and situation, while others strongly believe that there are certain universal and eternal human values. Give your perception in this regard with due justification."]]},{"id":"p263","name":"Essence of Ethics","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","Distinguish between laws and rules. Discuss the role of ethics in formulating them."],["2013","10","It is often said that ‘politics’ and ‘ethics’ do not go together. What is your opinion in this regard? Justify your answer with illustrations."]]},{"id":"p264","name":"Ethics in Private and Public sphere","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2014","10","In the context of defence services, ‘patriotism’ demands readiness to even lay down one’s life in protecting the nation. According to you, what does patriotism imply in everyday civil life? Explain with illustrations and justify your answer."],["2014","10","What does ethics seek to promote in human life? Why is it all the more important in public administration?"],["2013","10","The good of an individual is contained in the good of all. What do you understand by this statement? How can this principle be implemented in public life?"],["2013","10","What do you understand by ‘values’ and ‘ethics’? In what way is it important to be ethical along with being professionally competent?"]]},{"id":"p265","name":"Term Based","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","Differentiate ‘moral intuition’ from ‘moral reasoning’ with suitable examples."],["2022","10","Write short notes on the following in 30 words each : (i) Constitutional morality (ii) Conflict of interest (iii) Probity in public life (iv) Challenges of digitalization (v) Devotion to duty"],["2017","10","Examine the relevance of the following in the context of civil service: (a) Transparency (b) Accountability (c) Fairness and justice (d) Courage of conviction (e) Spirit of service."],["2015","10","Differentiate between the following (200 words); a) Law and Ethics; b) Ethical management and Management of ethics; c) Discrimination and Preferential treatment; d) Personal ethics and Professional ethics"],["2013","15","What do you understand by the following terms in the context of public service? (5 terms x 3 marks each: a) Integrity b) Perseverance c) Spirit of service d) Commitment e) Courage of conviction f) Personal opinion"]]},{"id":"p266","name":"Crisis of Ethical Values","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","“Corruption is the manifestation of the failure of core values in the society.” In your opinion, what measures can be adopted to uplift the core values in the society?"],["2017","10","The crisis of ethical values in modern times is traced to a narrow perception of the good life. Discuss."],["2014","10","We are witnessing increasing instances of sexual violence against women in the country. Despite existing legal provisions against it, the number of such incidences is on the rise. Suggest some innovative measures to tackle this menace."]]},{"id":"p267","name":"Role of Educational institutions","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","“Education is not an injunction, it is an effective and pervasive tool for all-round development of an individual and social transformation”.Examine the New Education Policy,2020 (NEP,2020) in light of the above statement."]]},{"id":"p268","name":"Teachings of Great Leaders","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","What are the major teachings of Mahavir? Explain their relevance in the contemporary world."],["2023","10","What were the major teachings of Guru Nanak? Explain their relevance in the contemporary world."],["2020","10","What are the main factors responsible for gender inequality in India ? Discuss the contribution of Savitribai Phule in this regard."],["2020","10","What teachings of Buddha are most relevant today and why? Discuss."],["2017","10","“Great ambition is the passion of a great character. Those endowed with it may perform very good or very bad acts. All depends on the principles which direct them.” – Napoleon Bonaparte. Stating examples mention the rulers (i) who have harmed society and country, (ii) who worked for the development of society and country."],["2016","10","Discuss Mahatma Gandhi’s concept of seven sins."],["2014","10","Which eminent personality has inspired you the most in the context of ethical conduct in life? Give the gist of his/her teachings giving specific examples, describe how you have been able to apply these teachings for your own ethical development."]]},{"id":"p269","name":"Value Based Questions","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","10","Social values are more important than economic values. Discuss the above statement with examples in the context of inclusive growth of a nation."],["2014","10","All human beings aspire for happiness. Do you agree? What does happiness mean to you? Explain with examples."]]},{"id":"p270","name":"Attitude for Civil Servants","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","To achieve holistic development goal, a civil servant acts as an enabler and active facilitator of growth rather than a regulator. What specific measures would you suggest to achieve this goal?"],["2024","10","Mindless addiction to Form, ignoring the Substance of the matter, results in rendering of injustice. A perceptive civil servant is one who ignores such literalness and carries out true intent. Examine the above statement with suitable illustrations."],["2022","10","The Rules and Regulations provided to all the civil servants are same, yet there is difference in the performance. Positive minded officers are able to interpret the Rules and Regulations in favour of the case and achieve success, whereas negative minded officers are unable to achieve goals by interpreting the same Rules and Regulations against the case. Discuss with illustrations."],["2021","10","Attitude is an important component that goes as input in the development of human beings. How to build a suitable attitude needed for a public servant?"],["2020","10","A positive attitude is considered to be an essential characteristic of a civil servant who is often required to function under extreme stress. What contributes a positive attitude in person.?"],["2016","10","Our attitudes towards life, work, other people and society are generally shaped unconsciously by the family and social surroundings in which we grow up. Some of these unconsciously acquired attitudes and values are often undesirable in the citizens of modern democratic and egalitarian society. (a) Discuss such undesirable values prevalent in today’s educated Indians. (b) How can such undesirable attitudes be changed and socio-ethical values be cultivated in the aspiring and serving civil servants?"],["2015","10","Two different kinds of attitudes exhibited by public servants towards their work have been identified as the bureaucratic attitude and the democratic attitude. A) Distinguish between these two terms and write their merits and demerits. B) Is it possible to balance the two to create a better administration for the faster development of our country?"]]},{"id":"p271","name":"Attitude for Individuals","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","‘Hatred is destructive of a person‘s wisdom and conscience that can poison a nation’s spirit. Do you agree with this view? Justify your answer."],["2016","10","Anger is a harmful negative emotion. It is injurious to both personal life and work life. (a) Discuss how it leads to negative emotions and undesirable behaviours. (b) How can it be managed and controlled?"],["2014","10","What factors affect the formation of a person’s attitude towards social problems? In our society, contrasting attitudes are prevalent about many social problems. What contrasting attitudes do you notice about the caste system in our society? How do you explain the existence of these contrasting attitudes?"]]},{"id":"p272","name":"Moral and Political Attitude","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","Young people with ethical conduct are not willing to come forward to join active politics. Suggest steps to motivate them to come forward."]]},{"id":"p273","name":"Organisational Attitude","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","In the context of work environment, differentiate between ‘coercion’ and ‘undue influence’ with suitable examples."],["2017","10","Discipline generally implies following the order and subordination. However, it may be counter-productive for the organisation. Discuss."]]},{"id":"p274","name":"Social influence and persuasion","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","“For any kind of social re-engineering by successfully implementing welfare schemes, a civil servant must use reason and critical thinking in an ethical framework.” Justify this statement with suitable examples."],["2016","10","How could social influence and persuasion contribute to the success of Swatchh Bharat Abhiyan?"]]},{"id":"p275","name":"EI in Administration","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2017","10","How will you apply emotional intelligence in administrative practices?"]]},{"id":"p276","name":"EI X Crisis of Conscience","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","In case of a crisis of conscience does emotional intelligence help to overcome the same without compromising the ethical and moral stand that you are likely to follow? Critically examine."]]},{"id":"p277","name":"EI: Concept and utility","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","What are the main components of emotional intelligence (EI) ? Can they be learned? discuss."],["2019","10","“Emotional Intelligence is the ability to make your emotions work for you instead of against you.” Do you agree with this view? Discuss."],["2013","10","What is ‘emotional intelligence’ and how can it be developed in people? How does it help an individual in taking ethical decisions?"]]},{"id":"p278","name":"EQ vs IQ","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","What really matters for success, character, happiness and lifelong achievements is a definite set of emotional skills – your EQnot just purely cognitive abilities that are measured by conventional IQ tests.” Do you agree with this view ? Give reasons in support of your answer."]]},{"id":"p279","name":"A.P.J. Abdul Kalam","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","“If a country is to be corruption free and become a nation of beautiful minds, I strongly feel there are three key societal members who can make a difference. They are the father, the mother and the teacher.” – Abdul Kalam."],["2019","10","“Where there is righteousness in the heart, there is beauty in the character. When there is beauty in the character, there is harmony in the home. When there is harmony in the home, there is order in the nation. When there is order in the nation, there is peace in the world.”"],["2017","10","“If a country is to be corruption free and become a nation of beautiful minds, I strongly feel there are three key societal members who can make a difference. they are father, the mother and the teacher.” – A. P. J. Abdul Kalam. Analyse."]]},{"id":"p280","name":"Abraham Lincoln","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","The true rule, in determining to embrace, or reject any thing, is not whether it has any evil in it; but whether it has more evil than good. There are few things wholly evil or wholly good. Almost every thing, especially of governmental policy, is an inseprarable compound of the two; so that our best judgement of the preponderance between them is continually demand. - Abraham Lincoln."],["2013","10","Nearly all men can withstand adversity, but if you want to test a man’s character, give him power.—Abraham Lincoln"]]},{"id":"p281","name":"Aristotle","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2013","10","I count him braver who overcomes his desires than him who overcomes his enemies.—Aristotle"]]},{"id":"p282","name":"Dalai Lama","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","“Judge your success by what you had to give up in order to get it.” Dalai Lama."],["2021","10","“We can never obtain peace in the outer world until and unless we obtain peace within ourselves”"]]},{"id":"p283","name":"Erik Erikson","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","“Life doesn’t make any sense without interdependence. We need each other, and the sooner we learn that it is better for us all” – Erik Erikson"]]},{"id":"p284","name":"Immanuel Kant","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","“In law, a man is guilty when he violates the rights of others. In ethics, he is guilty if he only thinks of doing so.” — Immanuel Kant"]]},{"id":"p285","name":"Jawaharlal Nehru","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","“To awaken the people, it is the women who must be awakened. Ones she is on the move, the family moves, the village moves, the nation moves.” – Jawaharlal Nehru"]]},{"id":"p286","name":"John Rawls’s concept of social Justice","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","10","Analyse John Rawls’s concept of social justice in the Indian context."]]},{"id":"p287","name":"Kautilya","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2016","10","Corruption causes misuse of government treasury, Administrative inefficiency and obstruction in the path of national Development. Discuss Kautilya’s views."]]},{"id":"p288","name":"Mahatma Gandhi","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","“The simplest acts of kindness are by far more powerful than a thousand heads bowing in prayer.” – Mahatma Gandhi"],["2020","10","“The best way to find yourself is to lose yourself in service of others .” Mahatma Gandhi"],["2019","10","“A man is but the product of his thoughts. What he thinks, he becomes.” – M.K.Gandhi"],["2018","10","Anger and intolerance are the enemies of correct understanding. -Mahatma Gandhi"],["2015","10","“The weak can never forgive; forgiveness is the attribute of the strong.”"],["2013","10","There is enough on this earth for every one’s need but for no one’s greed. Mahatma Gandhi."]]},{"id":"p289","name":"Plato","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","10","We can easily forgive a child who is afraid of the dark; the real tragedy of life is when men are afraid of the light."]]},{"id":"p290","name":"Potter Stewart","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","Ethics is knowing the difference between what you have the right to do and what is right to do.’-Potter Stewart ."]]},{"id":"p291","name":"Sardar Patel","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","“Faith is of no avail in the absence of strength. Faith and strength, both are essential to accomplish any great work.” — Sardar Patel"]]},{"id":"p292","name":"Socrates","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2020","10","”A system of morality which is based on relative emotional values is a mere illusion, a thoroughly vulgar conception which has nothing sound in it and nothing true.” – Socrates."],["2019","10","“An unexamined life is not worth living.” – Socrates"]]},{"id":"p293","name":"Swami Vivekananda","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","“The strength of a society is not in its laws, but in the morality of its people.” – Swami Vivekananda"],["2024","10","“Learn everything that is good from others, but bring it in, and in your own way absorb it, do not become others.” — Swami Vivekananda"],["2023","10","Do not hate anybody, because that hatred that comes out from you must, in the long run, come back to you. If you love, that love will come back to you, completing the circle.” – Swami Vivekanand."],["2021","10","“Every work has got to pass through hundreds of difficulties before succeeding. Those that persevere will see the light, sooner or later” – Swami Vivekananda"],["2020","10","”Condemn none: if you can stretch out a helping hand do so. If not fold your hands, bless your brothers and let them go their own way.” – Swami Vivekanand"]]},{"id":"p294","name":"Tirukkural","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","“Those who in trouble untroubled are, Will trouble trouble itself.” – Thiruvalluvar"],["2018","10","Falsehood takes the place of truth when it results in unblemished common good. -Tirukkural"]]},{"id":"p295","name":"William James","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","“The greatest discovery of my generation is that a human being can alter his life by altering his attitudes.” – William James"]]},{"id":"p296","name":"Empathy and Compassion","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","Apart from intellectual competency and moral qualities, empathy and compassion are some of the other vital attributes that facilitate the civil servants to be more competent in tackling the crucial issues or taking critical decisions. Explain with suitable illustrations."]]},{"id":"p297","name":"Foundational values","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Identify five ethical traits on which one can plot the performance of a civil servant. Justify their inclusion in the matrix."],["2021","10","Identify ten essential values that are needed to be an effective public servant. Describe the ways and means to prevent non-ethical behaviour in public servants."],["2019","10","What do you understand by the term ‘public servant’? Reflect on the expected role of a public servant."],["2019","10","What are the basic principles of public life? Illustrate any three of these with suitable examples."],["2018","10","State the three basic values, universal in nature, in the context of civil services and bring out their importance."],["2013","10","Indicate two more attributes which you consider important for public service. Justify your answer."]]},{"id":"p298","name":"Impartiality and Non-Partisanship","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Should impartial and being non-partisan be considered indispensable qualities to make a successful civil servant? Discuss with illustrations."],["2016","10","Why should impartiality and non-partisanship be considered as foundational values in public services, especially in the present day socio-political context ? Illustrate your answer with examples."]]},{"id":"p299","name":"Integrity","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","“Integrity is a value that empowers the human being’’. Justify with suitable illustration."],["2017","10","One of the tests of integrity is complete refusal to be compromised. Explain with reference to a real life example."],["2014","10","Integrity without knowledge is weak and useless, but knowledge without integrity is dangerous and dreadful. What do you understand by this statement? Explain your stand with illustrations from the modern context."]]},{"id":"p300","name":"Integrity X Intelligence X Energy","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","In looking for people to hire, you look for three qualities: integrity, intelligence and energy. And if they do not have the first, the other two will you. - Warren Buffett. What do you understand by this statement in the present-day scenario? Explain."]]},{"id":"p301","name":"Trustworthiness and Fortitude","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2015","10","How do the virtues of trustworthiness and fortitude get manifested in public service? Explain with examples."]]},{"id":"p302","name":"Accountability and Ethical Governance","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","“Constitutional morality is not a natural sentiment but a product of civil education and adherence of the rule of law.” Examine the significance of constitutional morality for public servant highlighting the role in promoting good governance and ensuring accountability in public administration."],["2023","10","Explain the term social capital. How does it enhance good governance?"],["2022","10","What do you understand by term ‘good governance’? How far recent initiatives in terms of e-Governance steps taken by the State have helped the beneficiaries? Discuss with suitable examples."],["2021","10","An independent and empowered social audit mechanism is an absolute must in every sphere of public service, including the judiciary, to ensure performance, accountability and ethical conduct. Elaborate."],["2016","10","What do you understand by the terms ‘governance’, ‘good governance’ and ‘ethical governance’?"],["2014","10","What does ‘accountability’ mean in the context of public service? What measures can be adopted to ensure individual and collective accountability of public servants?"]]},{"id":"p303","name":"Public/Civil Service Values","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","“One who is devoted to one’s duty attains highest perfection in life.” Analyse this statement with reference to sense of responsibility and personal fulfilment as a civil servant."],["2019","10","“Non-performance of duty by a public servant is a form of corruption” Do you agree with this view? Justify your answer (150 words, 10m)"],["2018","10","In doing a good thing, everything is permitted which is not prohibited expressly or by clear implication. Examine the statement with suitable examples in the context of a public servant discharging his/her duties."],["2018","10","What is meant by public interest? What are the principles and procedures to be followed by the civil servants in public interest?"],["2016","10","Max Weber said that it is not wise to apply to public administration the sort of moral and ethical norms we apply to matters of personal conscience. It is important to realise that the State bureaucracy might possess its own independent bureaucratic morality. Critically analyse this statement."]]},{"id":"p304","name":"Corporate Governance","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2023","10","What do you understand by ‘moral integrity’ and ‘professional efficiency’ in the context of corporate governance in India ? Illustrate with suitable examples."],["2022","10","In contemporary world, corporate sector’s contribution in generating wealth and employment is increasing. In doing so, they are bringing in unprecedented onslaught on the climate, environmental sustainability and living conditions of human beings. In this background, do you find that Corporate Social Responsibility (CSR) is efficient and sufficient enough to fulfill the social roles and responsibilities needed in the corporate world for which the CSR is mandated? Critically examine."],["2017","10","Corporate social responsibility makes companies more profitable and sustainable. Analyse."]]},{"id":"p305","name":"Conflict of interest","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2018","10","What is meant by conflict of interest? Illustrate with examples, the difference between the actual and potential conflicts of interest."],["2017","10","Conflict of interest in the public sector arises when (a) official duties, (b) public interest, and (c) personal interest are taking priority one above the other. How can this conflict in administration be resolved? Describe with an example."],["2015","10","Public servants are likely to confront with the issues of ‘Conflict of Interest’. What do you understand by the term ‘Conflict of Interest’ and how does it manifest in the decision making by public servants? If faced with the conflict of interest situation, how would you resolve it? Explain with the help of examples."]]},{"id":"p306","name":"Ethical dilemmas in Public Administration","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2021","10","Besides domain knowledge, a public official needs innovativeness and creativity of a high order as well, while resolving ethical dilemmas. Discuss with a suitable example."],["2018","10","Explain the process of resolving ethical dilemmas in Public Administration."]]},{"id":"p307","name":"Ethical Issues in International Relations and funding","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Carl von Clausewitz once said, “War is a diplomacy by other means.” Critically analyse the above statement in the present context of contemporary geo-political conflict."],["2024","10","“It is not enough to talk about peace, one must believe in it; and it is not enough to believe in it, one must act upon it” In the present context, the major weapon industries of the developed nations are adversely influencing continuation of number of wars for their own self-interest, all around the world. What are the ethical considerations of the powerful nations in today’s international arena to stop continuation of ongoing conflicts?"],["2023","10","‘International aid’ is an accepted form of helping ‘resource-challenged’ nations. Comment on ‘ethics in contemporary international aid’. Support your answer with suitable examples."],["2022","10","Russia and Ukraine war has been going on for the last seven months. Different countries have taken independent stands and actions keeping in view their own national interests. We are all aware that war has its own impact on the different aspects of society, including human tragedy. What are those ethical issues that are crucial to be considered while launching the war and its continuation so far? Illustrate with justification the ethical issues involved in the given state of affair."],["2021","10","“Refugees should not be turned back to the country where they would face prosecution or human rights violation.” Examine the statement with reference to the ethical dimension being violated by the nation claiming to be democratic with an open society."],["2020","10","‘The will to power exits, but it can be tamed and be guided by rationality and principles of moral duty.’ Examine this statement in the context of international relations."],["2017","10","Strength, peace and security are considered to be the pillars of international relations. Elucidate."],["2015","10","At the international level, the bilateral relations between most nations are governed on the policy of promoting one’s own national interest without any regard for the interest of other nations. This leads to conflicts and tensions between the nations. How can ethical consideration help resolve such tensions? Discuss with specific examples."]]},{"id":"p308","name":"Laws, Rules, Regulations and Conscience as Ethical Guidance","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","The soul of the new law, Bharatiya Nyaya Sanhita (BNS) is Justice, Equality and Impartiality based on Indian culture and ethos. Discuss this in the light of major shift from a doctrine of punishment to justice in the present judicial system."],["2023","10","Is conscience a more reliable guide when compared to laws, rules and regulations in the context of ethical decision making ? Discuss."],["2019","10","What is meant by ‘crisis of conscience’? How does it manifest itself in the public domain?"],["2019","10","What is meant by constitutional morality? How does one uphold constitutional morality?"],["2016","10","Law and ethics are considered to be the two tools for controlling human conduct so as to make it conducive to civilized social existence. (a) Discuss how they achieve this objective. (b) Giving examples, show how the two differ in their approaches."],["2015","10","A mere compliance with law is not enough, the public servant also has to have a well-developed sensibility to ethical issues for effective discharge of duties.” Do you agree? Explain with the help of two examples, where (i) an act is ethically right, but not legally and (ii) an act is legally right, but not ethically."],["2013","10","What do you understand by the term ‘voice of conscience’? How do you prepare yourself to heed to the voice of conscience?"],["2013","10","What is meant by ‘crisis of conscience’? Narrate one incident in your life when you were faced with such a crisis and how you resolved the same."]]},{"id":"p309","name":"Challenges of Corruption","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2022","10","Whistle blower, who reports corruption and illegal activities, wrongdoing and misconduct to the concerned authorities, runs the risk of being exposed to grave danger, physical harm and victimization by the vested interests, accused persons and his team. What policy measures would you suggest to strengthen protection mechanism to safeguard the whistle blower?"],["2014","10","It is often said that poverty leads to corruption. However, there is no dearth of instances where affluent and powerful people indulge in corruption in a big way. What are the basic causes of corruption among people? Support your answer with examples."]]},{"id":"p310","name":"Citizen’s Charter","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","10","Explain the basic principles of citizens’ charter movement and bring out its importance."]]},{"id":"p311","name":"Codes of Ethics and Codes of Conduct","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","The ‘Code of Conduct and ‘Code of Ethics’ are the sources of guidance in public administration. There is code of conduct already in operation, whereas code of ethics is not yet put in place. Suggest a suitable mode. for code of ethics to maintain integrity, probity and transparency. governance."],["2018","10","Distinguish between “Code of ethics” and “Code of conduct” with suitable examples."],["2016","10","Discuss the Public Services Code as recommended by the 2nd Administrative Reforms Commission."]]},{"id":"p312","name":"Work Culture","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","It is said that for an ethical work culture, there must be code of ethics in place in every organisation. To ensure value-based and compliance-based work culture, what suitable measures would you adopt in your work place?"]]},{"id":"p313","name":"Transparency X RTI","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2019","10","There is a view that the official secrets act is an obstacle to the implementation of the Rights to Information act. Do you agree with the view? Discuss"],["2018","10","The Right to Information Act is not all about citizens’ empowerment alone, it essentially redefines the concept of accountability. Discuss."],["2015","10","Some recent developments such as introduction of RTI Act, media and judicial activism, etc., are proving helpful in bringing about greater transparency and accountability in the functioning of the government. However, it is also being observed that at times the mechanisms are misused. Another negative effect is that the officers are now afraid to take prompt decisions. Analyze this situation in detail and suggest how this dichotomy can be resolved. Suggest how these negative impacts can be minimized."],["2015","10","Today we find that in spite of various measures like prescribing codes of conduct, setting up vigilance cells/commissions, RTI, active media and strengthening of legal mechanisms, corrupt practices are not coming under control. A) Evaluate the effectiveness of these measures with justifications. B) Suggest more effective strategies to tackle this menace."]]},{"id":"p314","name":"Probity in Governance","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","“In Indian culture and value system, an equal opportunity has been provided irrespective of gender identity. The number of women in public service has been steadily increasing over the years.” Examine the gender specific challenges faced by female public servants and suggest to increase their efficiency in discharging their duties and maintaining high standards of probity."],["2023","10","‘Probity is essential for an effective system of governance and socio-economic development.’ Discuss."],["2019","10","What do you understand by probity in governance? Based on your understanding of the term, suggest measures for ensuring probity in government."],["2014","10","What do you understand by ‘probity’ in public life? What are the difficulties in practicing it in the present times? How can these difficulties be overcome?"]]},{"id":"p315","name":"Utilization of public funds","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","India is an emerging economic power of the world as it has recently secured the status of fourth largest economy of the world as per IMF projection. However, it has been observed that in some sectors, allocated funds remain either under-utilised or misutilised. What specific measures would you recommend for ensuring accountability in this regard to stop leakages and gaining the status of third largest economy of the world in near future?"],["2019","10","Effective utilisation of public funds is crucial to meet development goals. Critically examine the reasons for under-utilization and mis-utilisation of public funds and their implications."],["2014","10","There is a heavy ethical responsibility on the public servants because they occupy positions of power, handle huge amounts of public funds, and their decisions have wide-ranging impact on society and environment. What steps have you taken to improve your ethical competence to handle such responsibility?"]]},{"id":"p316","name":"Quality of Service Delivery","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","10","Mission Karmayogi is aiming for maintaining a very high standard of conduct and behaviour to ensure efficiency for serving citizens and in developing oneself. How will this scheme empower the civil servants in enhancing productive efficiency and delivering the services at the grassroots level?"],["2022","10","Wisdom lies in knowing what to reckon with and what to overlook. An officer being engrossed with the periphery, ignoring the core issues before him, is no rare in the bureaucracy. Do you agree that such preoccupation of an administrator leads to travesty of justice to the cause of effective service delivery and good governance? Critically evaluate."]]},{"id":"p317","name":"First Phase","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["Third Phase (Pre-Prelims)","Fourth Phse (Post-Prelims)","Second phase"]]},{"id":"p318","name":"Aspirants struggle with content overload and basic concepts.","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["Switching to prelims mindset.","Intensive preparation for the Mains exam.","Aspirants may experience burnout and self-doubt."]]},{"id":"p319","name":"Mentors help them make sense of what to read, how to approach subjects, and how to revise effectively.","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["Pre-tests and post- tests to discussions to assess retention and identify strengths and weaknesses.","Hands-on classes and post-test discussions.","Mentors provide personalized support and motivation."]]},{"id":"p320","name":"Regular tests are given to anchor marks to understand performance through personalized feedback.","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["Personalized strategies for improving accuracy and tackling difficult questions.","Value enrichment sessions and X-factor notes are needed to gain an edge.","Focus on consolidating notes and knowledge gained. Introduction to more complex and challenging subjects."]]},{"id":"p321","name":"Answer writing practice begins in the first few weeks.","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["Guidance on online re- sources and study mate- rials","Double down on GS and Optional answer writing. Frequent practice and continuous feedback.","Guidance on revising material and reflecting it in answers."]]}]}]},{"name":"Essay","subjects":[]},{"name":"Optional I","subjects":[{"name":"Western Philosophy","chapters":[{"id":"o1_1","name":"Plato and Aristotle","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","\"Ideas are timeless and spaceless.\" Elucidate this statement with reference to Plato."],["2025","10","\"In the empirical world, everything is a compound of Matter and Form.\" Evaluate this statement with reference to Aristotle."],["2024","10","Differentiate between Plato's and Aristotle's conceptions of form."],["2023","15","Present an exposition of Aristotle’s distinction between actuality and potentiality. Does it provide a solution to the problem of being and becoming as presented in ancient Greek philosophy? Discuss with suitable examples."],["2022","10","How does Plato use the theory of forms to establish the relation between epistemology and metaphysics? Discuss."],["2022","15","Is Aristotle’s view of nature of identity in consonance with his metaphysical view of causes as processes? Discuss giving suitable examples."],["2021","10","“There is a red chair.” How would Plato explain this statement with the use of his theory of forms? Examine."],["2021","10","“Potentiality is indefinable” according to Aristotle. Explain the relationship between potentiality and actuality with reference to the above philosophical position by taking the example of a “wooden table”."],["2020","10","How does Aristotle argue for the priority of Form over Matter and Actuality over Potentiality? Critically discuss."],["2019","10","What does Plato want to prove by his ‘Allegory of Cave’?"],["2019","15","What are the reasons for development changes in substance according to Aristotle?"],["2018","15","Is the relation between the Idea and the World as discussed by Plato logically consistent? Discuss Aristotle’s views regarding this and also give arguments in favour of your answer."],["2017","10","In what sense can ideas be both immanent and transcendent? Discuss in this context Plato’s theory of universal and particulars."],["2017","15","Explain Aristotle’s theory of form and matter. How does it help him resolve the problem of change and permanence?"],["2016","20","Does Plato’s ‘Theory of Form’ explain the ‘change’ and ‘sensibility’ of matter? Give reasons for your answer."],["2016","20","Does Aristotle treat matter as a ‘Substance’? Give reasons for your answer."],["2015","10","Aristotle’s distinction between ‘actuality’ and ‘potentiality’."],["2015","20","Explain Plato’s theory of forms? Does it entail a kind of essentialism? Discuss."],["2014","15","Explain the significance of Aristotle’s doctrine of form & matter in his theory of causation."],["2014","20","Discuss between knowledge and belief according to Plato. How is it based on his metaphysics? Explain."],["2013","12.5","Explain Plato’s ontological theory of Forms. Is knowledge one of the Forms? Explain."],["2013","10","Discuss how by refuting different concepts of Substances Aristotle establishes his own theory of a Substance?"]]},{"id":"o1_2","name":"Rationalism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","20","What are the basic tenets of Rationalism? How does Descartes build a system of Philosophy in consonance with them? Discuss."],["2025","15","\"All determination is negation.\" Comment with reference to Spinoza."],["2024","15","Among the rationalists, whose account of mind-body problem is compatible with the notion of human freedom and free will? Critically discuss."],["2024","15","How does Spinoza establish that God alone is absolutely real with his statement - \"Whatever is, is in God\"? Critically discuss."],["2023","10","“That thing is said to be free which exists solely from the necessity of its own nature, and is determined to action by itself alone.” Discuss Spinoza’s views on freedom and determinism in the light of the above statement."],["2023","15","Discuss Descartes’ theory of innate ideas and the grounds on which Locke refutes it."],["2022","15","Discuss the concept of substance according to Spinoza. Does his discussion on substance lead to pantheism? Substantiate your view."],["2022","15","How does Rene Descartes explain the notion of certainty with reference to knowledge of the self? Critically discuss the way it differs from the knowledge of the world."],["2020","10","How does Leibnitz’s conception of Monads bear upon his views on determinism and freedom? Discuss with your own comments."],["2020","15","From the necessity of the divine nature there must follow infinitely many ways. “Explain this statement by Spinoza along with some possible criticisms."],["2019","10","How does Descartes prove the existence of things other than himself and God? Discuss."],["2019","15","What do you understand by Spinoza’s statement that what is, cannot be other than what it is? Explain."],["2018","20","What is the reason for the difference in the definitions and classifications of substances made by Descartes, Spinoza and Leibniz in spite of the fact that they all belonged to the rationalist school of thought? Discuss."],["2018","10","Is there any place for freedom in Leibniz’s philosophy, when he speaks of “pre-established harmony’? Discuss."],["2017","20","What according to Descartes is a clear and distinct idea? what is the epistemological status of clear and distinct ideas? Does this account help Descartes prove that material objects exist? Explain"],["2015","15","Explain Leibnitz’s principle of ‘identity of indiscernible’."],["2015","15","Does Descartes cogito principle entail that he is an essentialist? Discuss."],["2014","15","Explain the doctrine of Cartesian Dualism and examine critically arguments in favour of it."],["2014","10","Does Leibnitz’s theory of pre-established harmony necessarily lead to determinism? Discuss."],["2013","12.5","Write a short critical essay on Spinoza’s conception of freedom of an individual."],["2013","12.5","Explain Descarte’s method of doubt. Can this method be used to justify his belief in the existence of God?Argue your case."],["2013","12.5","Give a critical account of Leibnitz’s principle of the identity of indiscernibles."]]},{"id":"o1_3","name":"Empiricism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Examine Hume's refutation of Causal relation and Kant's response to it."],["2025","15","Explain Berkeley's doctrine of nominalism and his refutation of Abstract ideas."],["2024","20","Is rejection of Locke's notion of primary qualities instrumental in Berkeley's leaning towards idealism? In this context, also discuss how Berkeley's subjective idealism is different from the absolute idealism proposed by Hegel."],["2023","20","Critically analyse Hume’s argument that causality is a matter of habit/custom involving psychological principle of association."],["2022","15","Why and how does John Locke refute the innate ideas? Elucidate the nature and source of knowledge in Locke’s epistemology."],["2021","10","“Sensible things are those only which are immediately perceived by sense.” Explain Berkeley’s theory of knowledge with reference to the above statement."],["2021","10","Examine the concept of personal identity by Locke."],["2021","10","“The relation between cause and effect is one of constant conjunction”. Examine Hume’s “criticism of causation in the light of the above statement."],["2020","20","“I never can catch myself at any time without perception , and never can observe anything but perception.” How does this statement by Hume problematize the philosophical notion of personal identity? How does Kant deal with this problem in his critique of Pure Reason?"],["2019","15","Is there any element of necessity in causal relations according to Hume? Discuss."],["2018","10","Are the two truths-”The Sun will rise tomorrow” and ‘2+2-4’ of the same necessity for Hume? Give reasons in favour of your answer."],["2018","20","How does Berkeley establish that Mind and its ideas alone are real? How do Moore and Russell react to Berkeley’s view in this regard? Do you find any difference between Moore’s reaction and Russell’s one? Discuss."],["2017","10","Show how Hume’s analysis experience leaves no ground for belief in any permanent reality either physical or mental."],["2017","20","How does Locke draw a distinction between primary and secondary qualities? Does he also draw a distinction between the Idea of primary qualities and primary qualities as well as the Idea of secondary qualities and secondary qualities? Discuss"],["2016","10","What is the logical necessity for Locke to introduce the concept of secondary qualities? Give reasons for your answer"],["2016","15","Critically examine Hume’s views on the relation of cause and effect."],["2015","10","esse est percipi."],["2014","15","Evaluate critically Hume’s criticism of theory of causation."],["2013","12.5","Give a critical account of Hume’s theory of self."]]},{"id":"o1_4","name":"Kant","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","15","Critically examine Kant's objections against the ontological argument for the existence of God."],["2024","10","How does Kant respond to Hume's scepticism with regard to a priori judgments? Discuss."],["2023","10","“Precepts without concepts are blind and concepts without precepts are empty.” In the light of this statement discuss how Kant reconciles rationalism with empiricism."],["2023","10","What are the main arguments offered by Kant to prove that a-priori synthetic judgements are possible? Discuss with examples."],["2022","10","What is apperception, according to Immanuel Kant? Discuss with reference to his transcendental exposition of space and time."],["2022","20","How does Kant construct antinomies to illustrate the illusory tendencies of pure reason? Explain and examine the antinomies presented by Kant."],["2021","15","Explain how Cartesian formulation of ontological argument is criticized by Kant."],["2020","15","When does Pure Reason enter into the realm of Antinomies according to Kant? Is Kant’s notion of Antinomies of Pure reason a natural culmination of his distinction between Phenomena and Noumena? Give reasons in favour of your answer."],["2019","20","How does Kant argue for the transcendence of Space and Time? Discuss."],["2018","15","Explain the significance of the Kantian dictum, ‘Understanding makes Nature’. How far do you agree that Hegel’s Absolutism is the culmination of the Kantian Dualism? Discuss. Give reasons in favour of your answer."],["2017","20","How is ‘all bodies are extended’ an analytic judgement but ‘all bodies are heavy’ a synthetic judgement? Is ‘every event has a cause’ an analytic or a synthetic judgement? Explain."],["2017","20","Elaborate Kant’s theory of space and time. How does this theory enable him to explain how mathematical propositions can be both synthetic and apriori?"],["2016","15","What, according to Kant, are ‘pure concepts’? Examine their role in the process of knowing."],["2016","10","Examine Kant’s criticism on Descartes’ view of Self."],["2015","20","Explain Kant’s division of categories."],["2014","10","How are synthetic apriori judgement justifiable according to Kant? Explain."],["2013","12.5","Explain Kant’s view of causality. How far is Kant able to answer Hume’s objection that causal relation lacks logical necessity."],["2013","10","What is Antinomy? Describe the major antinomies discussed by Kant."]]},{"id":"o1_5","name":"Hegel","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","How does Hegel challenge Kant's distinction between Phenomena and Noumena? Discuss."],["2023","10","“History is a process of dialectical change.” In the light of this statement discuss Hegel’s approach in understanding history."],["2022","15","What is the dialectical method in the philosophy of Georg Wilhelm Hegel? How does this method help in realizing the Absolute? Discuss."],["2021","20","Discuss Hegel’s Dialectical method. Explain how his dialectical method lead him to the Absolute Idealism."],["2020","10","Examine the reality of the phenomenal world in the light of Hegel’s Absolutism Idealism."],["2019","10","What is the role of dialectics in realizing the truth in Hegel’s philosophy?"],["2017","10","Elaborate Hegel’s dictum “All identity is identity and difference.”"],["2016","15","What is Hegel’s view on God? Do you think that his interpretation of God was contributive to the colonial and imperial expansionist designs? Explain"],["2013","12.5","Comment : ‘ Movement is contradiction itself ’ Examine in this context Hegel’s dialectical method ."]]},{"id":"o1_6","name":"Moore, Russell and Early Wittgenstein","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","\"The golden mountain is very high.\" Discuss this statement in the context of Russell's theory of descriptions."],["2025","15","\"Blue is one object of sensation and green is another, and consciousness, which both sensations have in common, is different from either.\" Present an account of Moore's refutation of idealism with reference to this statement."],["2024","20","Explain Russell's notion of incomplete symbols. Also explain how this notion leads to the doctrine of logical atomism."],["2024","10","What arguments are offered by Moore to prove that there are certain truisms, knowledge of which is a matter of common sense? Critically discuss."],["2023","15","Why according to Russell is the proposition – “The present king of France is bald” problematic? Critically discuss."],["2022","10","What is Bertrand Russell’s method of logical analysis? How does it ultimately end in establishing atomic theory of meaning? Discuss."],["2022","15","Is there any difference between pictorial form and logical form in Ludwig Wittgenstein’s picture theory-of-language? How does the logical form define the relation between language and reality? Explain."],["2021","20","What are the main arguments put forward by Moore in his paper “ A Defence Of Common Sense ” to prove that there are possible propositions about the world that are known to be true with certainty? Do you think Moore’s arguments provide a sufficient response to objections presented by the sceptic against the possibility of knowledge? Give reasons in support of your answers."],["2021","15","What does Wittgenstein mean by the statement – “Whereof one cannot speak, thereof one must be silent?” Critically discuss."],["2020","15","Critically discuss the following statement by Moore: “If anyone tells us that to say ‘Blue exists’ is the same thing as to say that ‘Both blue and consciousness exists makes a mistake and a self contradictory mistake. “"],["2020","15","“The reason that I call my doctrine logical atomism is because the atoms that I wish to arrive at as the sort of last residue in analysis are logical atoms and not physical atoms” Write a note on the nature of atomic facts according to Russell in the light of the above statement."],["2019","15","Why is Moore’s philosophy called common-sense realism?"],["2018","15","How is Russell’s theory of definite description related to his Logical Atomism? Discuss and give reasons for your answer."],["2018","15","How does Wittgenstein apply the distinction between ‘saying’ and ‘showing’ to point to a single way of apprehending the most decisive problems of philosophy? Is he justified? Give reasons for your answer."],["2017","10","How is the statement ‘ I met a man ’ , semantically problematic for Russell? How does he account for the meaningfulness of this statement?"],["2017","15","What is Wittgenstein’s theory of picture theory of meaning? What are his reasons for giving up his theory and suggesting the use theory of meaning?"],["2016","15","Explain Russell’s view that “the physical object is a logical construction from sense-data”. Why does he call his metaphysical view ‘neutral monism’?"],["2016","10","Why does Wittgenstein reject the possibility of private language?"],["2015","10","G.E.Moore’s refutation of idealism."],["2015","15","What do you understand by incomplete symbols? What role do they play in Russell’s theory of meaning?"],["2014","15","Are G.E.Moore’s arguments in defence of common sense satisfactory. Give reasons."],["2014","15","Why does Wittgenstein disagree Bertrand Russell’s interpretation of atomism in the philosophy of Tractatus? Discuss"],["2013","12.5","Distinguish between atomic and general proposition. Show how they are justified true ."],["2013","12.5","Comment : ‘ Moore’s defence of common sense essentially is defence of common language ’"]]},{"id":"o1_7","name":"Logical Positivism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Present an exposition of the verification theory of meaning as propounded by the logical positivists. In this context also differentiate between the \"strong\" and the \"weak\" sense of the word \"verifiable\"."],["2024","15","Is the sentence \"All objects are either red or not red\" meaningful in the same way as \"This page is white\" is, according to the logical positivists? Discuss with arguments."],["2023","20","Does the rejection of metaphysics as proposed by Logical Positivists relate to problem of meaning or problem of knowledge or nature of things or all of them together? Discuss with suitable examples."],["2021","15","What according to Logical Positivists are “pseudo statements”? How does one identify “pseudo statements”? Critically discuss with examples."],["2020","10","“The Soul of Superman is Good” Critically examine the above statement in the light of Logical Positivism."],["2019","20","How do the logical positivists account for the meaning of general statements? Can the same account be applied to metaphysical statements? Discuss."],["2018","15","How do the logical positivists show that metaphysical sentences are meaningless? Can their verification theory of meaning account for the meaningfulness of all scientific sentences? Discuss."],["2017","15","Does the sentence ‘ whatever is coloured is extended’, satisfy the criterion of meaningfulness proposed by the logical positivists? Explain."],["2016","10","Explain verification theory. Does it lead to elimination of metaphysics?"],["2014","20","Are empirical statements verifiable? Discuss the limitations of ‘ verification theory of meaning’."],["2013","10","Distinguish necessary from empirical proposition. How is necessary proposition is justified? Explain"]]},{"id":"o1_8","name":"Later Wittgenstein","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","20","\"We should look not to an ideal language which derives its meaning from facts and has a precise logical structure but empirically, to the ways in which languages are actually used.\" Explain the transition from early views of Wittgenstein to his later views on language and meaning with reference to this statement."],["2024","10","Why does later Wittgenstein think that there cannot be a language that only one person can speak - a language that is essentially private? Discuss."],["2023","15","What were the main reasons that led Wittgenstein to shift from picture-theory of meaning to use-theory of meaning. Critically discuss."],["2022","10","Establish the tenability of later Wittgenstein’s notion of language as form of life."],["2020","15","“But could we also imagine a language in which a person could write down or give vocal expression to his inner experiences - his feelings, moods and the rest-for his private use? ” Critically discuss the answer offered offered by Wittgenstein to this question."],["2019","15","Show how Wittgenstein’s critique of solipsism culminates in the critique of private language."],["2018","10","How does the notion of ‘family resemblance help Wittgenstein to uphold that ‘Language is a game’? Discuss."],["2015","20","Bring out the relationship between language games and forms of life."],["2014","10","Bring out the significance of ‘Language Games’ in Wittgenstein’s Use theory of meaning."],["2013","10","Explain Wittgenstein’s arguments against the possibility of private language."]]},{"id":"o1_9","name":"Phenomenology – Husserl","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","20","How is Husserl's account of \"I think\" different from that of Descartes? Critically discuss."],["2024","15","Why does Husserl think that essences exhibit a kind of continuity between consciousness and being? Discuss."],["2023","15","Elucidate the significance of bracketing and reduction in Husserl’s phenomenological method."],["2022","10","What is psychologism? Critically discuss the way Edmund Husserl avoids the problem of psychologism in the discourse of transcendental phenomenology."],["2020","10","What, according to Husserl, is wrong with psychologism? How does Husserl address the problems with psychologism in his phenomenological method?"],["2019","10","Can hallucination be regarded as an intentional act of Husserl? Explain."],["2018","20","What is Epoché? How does Heidegger reject this method of phenomenological reduction? Explain Heidegger’s concept of ‘being in the world’ as opposed to the concept of a transcendental ego."],["2017","10","Explain Husserl’s reasons for advocating phenomenological reductionism."],["2015","10","Husserl’s notion of ‘bracketing’."],["2014","10","Explain the significance of ‘bracketing’ in Husserl Phenomenology."]]},{"id":"o1_10","name":"Existentialism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Explain the difference between being-for-itself and being-in-itself as presented by Sartre."],["2024","20","What do the existentialist thinkers mean by the slogan \"existence precedes essence\"? How is human existence related to human freedom according to them? Discuss."],["2024","10","How does Kierkegaard define truth in terms of subjectivity? Critically discuss."],["2023","10","How does Kierkegaard argue against Hegel’s idea of universal spirit in favour of the individual as the essence of spirit? Critically discuss."],["2023","15","“Consciousness is what it is not and is not what it is.” In the light of this statement bring out the chief features of Sartre’s conception of consciousness."],["2022","20","Provide a critical account of Heidegger’s Being-in-the-world and discuss the problem of ‘authenticity’ in the context of Dasein."],["2022","20","How does Soren Kierkegaard define the notion of ‘subjectivity’? Explain it with reference to three stages of existence as propounded by him."],["2021","15","“I can always choose, but I ought to know that if I do not choose, I am still choosing”. Critically discuss Sartre’s conception of choice and responsibility in the light of above statement."],["2020","20","What does Kierkegaard mean by saying “Subjectivity is the truth” in the context of the problem of ‘the single individual’?"],["2020","20","“You can always make something out of what you have been made into.” Critically discuss this statement by Sartre with reference to his views on existentialism."],["2019","20","Is Dasein authentic existence for Heidegger? How does he relate temporality with Dasein? Discuss."],["2019","15","How does Sartre look at the problem of freedom of choice and determinism? Explain."],["2018","10","How does Sartre connect inauthenticity with bad faith? Why does Sartre show that inauthenticity and bad faith lead to alienation? Discuss."],["2017","15","Discuss Heidegger’s concept of authenticity and explain how an inauthentic Dasein regains the lost self?"],["2016","15","Discuss Sartre’ s notion of ‘Nothingness’."],["2015","15","Discuss why Heidegger introduces the concept of Dasein in his metaphysics."],["2015","15","Bring out the relationship between existence and essence in case of human being. Explain the issues it gives rise to for human beings according to Sartre."],["2014","20","Explain Kierkegaard’s concept of choice. How does the concept of choice in meta-ethics differ from normative ethics? Explain."],["2014","15","State and evaluate Heidegger’s claim that temporality is the horizon against which the being of any entity is understood."],["2013","12.5","Examine Sartre’s distinction between Being-for-itself and Being-in-itself."],["2013","12.5","Analyse Kierkegaard’s concept of choice. Can there be , in his view , correct or incorrect choice? Discuss."]]},{"id":"o1_11","name":"Quine and Strawson","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","\"We can affirm the truth of any sentence in our total system, in the face of whatever experience, just so long as we are prepared to make adjustments elsewhere.\" Discuss this statement in the light of Quine's 'Two Dogmas of Empiricism'."],["2024","15","Explain the nature of the two dogmas that Quine refers to in his paper 'Two Dogmas of Empiricism'."],["2023","20","Why does Strawson consider person to be a primitive concept? What implication does it have for the mind-body dualism? Discuss."],["2021","15","What according to Strawson are basic particulars? What reasons does Strawson offer to believe that ‘material bodies’ and ‘persons’ are basic particulars? Critically discuss."],["2021","15","Critically examine Quine’s postulate of empiricism without the dogmas with reference to his ‘Two Dogmas of Empiricism’."],["2020","15","Evaluate the role of spatio-temporal thinking in objective thinking with reference to Strawson’s theory of basic particulars."],["2019","10","Explain Quine’s arguments against synthetic-analytic distinction."],["2018","10","How does Strawson explain the concept of person in his philosophy? Discuss."],["2017","15","What are the two dogmas of empiricism that Quine attacks? What are his arguments against what he calls the second dogma?"],["2016","10","Discuss Quine’s attack on the analytic-synthetic distinction."],["2015","10","Strawson’s distinction between ‘M’ and ‘P’ predicates."],["2015","15","Elucidate Quine’s arguments to show that analyticity is not synonymity."],["2014","10","How far are Quine’s arguments in ‘two dogmas of empiricism’ justified? Discuss."],["2013","10","Explain and evaluate Strawson’s arguments for his conception of the nature of Person."]]}]},{"name":"Indian Philosophy","chapters":[{"id":"o1_12","name":"Carvaka","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Discuss Cārvāka’s critique of the belief in the existence of suprasensible entities. (asked in Paper II)"],["2025","10","Explain the ground on which Carvaka rejects inference (anumana) as a valid source of knowledge."],["2024","20","Differentiate between the Carvaka's refutation of self as a transcendental category and the Buddhist rejection of atma."],["2024","10","Do you think Carvaka's philosophy is positivistic in nature? Give reasons and justifications for your answer."],["2022","15","How do Naiyāyikas respond to Cārvāka’s objections against inference (anumāna) and establish inference as an independent means of knowledge? Critically discuss."],["2021","10","Comment on the bearing of Cārvāka epistemology on the rejection of transcendental entities by them."],["2020","15","Critically evaluate Carvakas’ rejection of Akasa as one of the elements of reality and examine their criticism of transmigration of Soul."],["2020","15","Explain the differences of conception of Reality between Carvaka and Jainism."],["2019","10","Are the Carvakas consistent when they hold that inference is not a source of knowledge? Discuss."],["2019","15","What is wrong according to the Carvakas with the following argument? All men are mortal. Socrates is a man. Therefore, Socrates is mortal. Justify your answer with arguments."],["2018","15","Is Cārvāka rejection of inference acceptable to the other systems of Indian philosophy? If not, why? Do you think the views of other systems to be justified? Give reasons for your answer."],["2017","10","“ The soul is nothing but conscious body.” What are the reasons for Carvaka in holding this view?"],["2016","15","What would be Carvaka’s view on Vyapti? Can this view be acceptable to the Naiyayikas? Give reasons for your answer."],["2015","15","Explain the the arguments of Carvaka to reject transcendental entities."],["2014","10","“Limits of knowledge and world are determined by my sense perception”. Discuss this claim of Carvaka."]]},{"id":"o1_13","name":"Jainism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Is Jaina philosophy pluralistic and realistic? Critically discuss."],["2024","15","What is the distinction between Bhavabandha and Dravyabandha, according to the Jainas? Discuss."],["2023","10","All human knowledge is empirical and therefore relative. Critically examine Jaina theory of sevenfold judgement (saptabhanginaya) in the light of above statement."],["2022","15","The doctrine of “Relativism of Jain Philosophy cannot be logically sustained without postulating “Absolutism’. Critically examine this view and give reasons in the favour of your answer."],["2022","10","How does Jaina view of Karma bear upon their soteriology? Critically discuss."],["2021","15","Explain the Jain view of seven-fold (sapta-bhangī) ‘Naya’."],["2020","10","Examine the concept of Karma according to Jainism. How does it bear upon their conception of Liberation?"],["2019","20","How is reality defined by the Jainas? How is this theory of reality reflected in their view on judgements? Discuss."],["2018","15","How do the Jaina philosophers explain ‘bondage’? What, according to them, is the distinction between “liberated soul’ and ‘bound soul’? What do the Jainas think about the condition of the ‘liberated soul’? Discuss."],["2017","15","“The Jaina metaphysics is relativistic and realistic pluralism”. Discuss"],["2016","15","Can the ‘Tattvartha’ theory of Jainism be acceptable for scientific explanations?"],["2016","10","Examine Jaina stance of ‘Naya’. How does it differ from ‘Syadvada’?"],["2016","10","Differentiate the concept of ‘Kaivalya’ as discussed in Jaina and Yoga philosophies."],["2015","10","Jain concept of Dravya."],["2015","15","What do samvara and nirjara mean? Explain their significance in Jaina theory of liberation."],["2014","15","Explain the concept of Karma and discuss various types of according to Jaina philosophy."],["2013","10","Analyse the relation between the theory of Saptabhanginaya and Anekantvada."]]},{"id":"o1_14","name":"Samkhya","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","20","Why does Sankara consider Samkhya Philosophy as his chief opponent (Pradhana malla)? Examine his arguments against Samkhya Philosophy."],["2024","20","Present an account of evolution of Prakrti as propounded in Samkhya karika. In this context, also explain the difference between buddhi, mahat and ahamkara."],["2023","10","“If Purusa and Prakṛti are two completely independent realities, then no relation between the two is possible.” In the light of this statement make a brief presentation of Sankara’s criticism of Samkhya dualism."],["2022","10","Examine and evaluate the proofs given by Samkhya philosophy to prove the existence of Puruṣa."],["2021","15","Explain the Sānkhya view on three gunas (guṇa-traya) and their modifications."],["2020","20","A mango tree is grown out of a mango seed,” How will Samkhya system explain this process through their theory of causation by rejecting their rival perspectives?"],["2019","10","Critically discuss the metaphysical status of a Jiva and a Purusa according to Sankhya philosophy."],["2019","15","Which Sankhya proof for the existence of Prakrti actually shows that there can be only one Prakrti? Justify your answer."],["2018","10","Is Purusa one or many? Explain the Sámkhya position in this regard and give arguments in support of your answer."],["2017","15","Given the theory of causation , is it possible for Samkhya to explain the presence of consciousness in the world? Discuss."],["2016","10","Critically examine the role of ‘Prakriti’ in the process of evolution."],["2015","10","Satkaryavada"],["2015","15","State and examine Samkhya proofs for the existence of Purusa."],["2014","15","Examine the Samkhya view about liberation that “ self is neither bound nor liberates , nor transmigrate.”"],["2014","20","How is theory of causation central to the theory of reality in classical Indian tradition.? Discuss."],["2014","10","Are the arguments given in favour of existence of Prakriti adequate in Samkhya’s philosophy? Discuss."],["2013","12.5","Evaluate relation ‘if any’ between prakriti and purusha."],["2013","10","Explain the possibility of jivanmukti . Critically compare it with the Yoga account of kaivelya ."]]},{"id":"o1_15","name":"Schools of Buddhism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Is Buddhist notion of Nirvana in consonance with their conception of Ksanikavada (momentariness) and Nairatmyavada (no-soul theory)? Critically discuss."],["2024","15","How do the two schools of Buddhism arrive at two opposed conclusions, namely \"everything is void\" and \"everything is real\" from the same doctrine of Pratityasamutpada? Answer with arguments."],["2023","20","“Ignorance of dependent origination is suffering while its knowledge is cessation. of suffering.” Present an account of Buddhist soteriology in the light of above statement."],["2022","20","How compatible is Buddhist theory of momentariness with their theory of Karma? In this regard how do Buddhists respond to objections raised by their opponents? Critically discuss."],["2022","15","Explain Buddhist concept of Trratna and their internal relation. Critically examine the consistency of Trratnas with the Buddhist concept of No-soul (Nairātmyavāda)."],["2021","10","Distinguish between pudgala-nairātmyavāda and dharma-nairātmyavāda with reference to Buddhist Philosophy."],["2021","15","If everything is momentary then how do the Buddhists explain the problem of memory and ‘personal identity? Critically discuss."],["2020","20","How is Ksanikavada a logical derivative of Pratityasamutpada in Buddhism? Explain."],["2020","15","How does Buddhism explain Self in terms of Pancaskandhas? What is Liberation for Buddhism if there is no Soul?"],["2019","10","How do the Yogacara Buddhists deny the existence of the external world? Discuss."],["2019","15","What is Pratityasamutpada? How do the Buddhists apply this concept to prove that everything is momentary?"],["2018","15","Is it consistent for the Buddhists to admit the theory of Nairātmyavāda and the doctrine of Nirvana simultaneously? Give reasons in favour of your answer."],["2018","10","How do the Madhyamika Buddhists apply the notion of Pratityasamutpada to establish their doctrine of Sunyata? Discuss."],["2017","10","Elucidate the role of catuskoti in explaining the nature of reality according to Madhyamika school of thought."],["2017","15","What are the arguments of the Buddhists to establish Ksanikvada? Do they necessarily lead to krtanasa and akrtabhyupagam?"],["2017","20","How do Madhyamika, yogacaravadins and sarvastivadins differ among themselves in concerning the nature of reality? How do sarvastivadins differ among themselves with regard to knowledge of reality?"],["2016","10","How does Ksanikavada strengthen the arguments for ‘Nairatmyavada’? Explain."],["2016","20","Does the ‘Doctrine of Dependent Origination’ reconcile the two extreme views on the law of causation, namely Satkaryavada and Asatkaryavada? Give reasons for your answer."],["2015","10","Alayavijnana"],["2015","15","What is the role of Pratityasamutpada in explaining dukkha? Elucidate means to overcome it."],["2014","15","How does Nagarjuna explain the concept of sunyata?"],["2013","10","Explain the Buddhist notion of ‘Impermanence’ and show how the idea of Impermanence leads to theory of momentariness of reality."],["2013","12.5","Comment : ‘ Accepting Shunyavada makes one indifferent to the pursuit of dharma’. Examine in this context , Nagarjuna’s arguments for Shunyavada."]]},{"id":"o1_16","name":"Nyaya-Vaisheshika","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","20","Present a detailed account of Gautama's definition of Perception."],["2025","10","Present an exposition of Nyaya-Vaisesika's theory of causation."],["2025","15","Present an exposition of the debate between Naiyayikas and Buddhists with reference to the notion of Pramana and Pramanaphala."],["2024","10","Explain the six reasons offered by the Naiyayikas to prove the existence of the self."],["2024","10","Do these two sentences \"Air does not have heat\" and \"Air is not fire\" refer to the same type of absence or abhava, according to the Vaisesikas? Discuss."],["2023","10","Present an account of Vaiseṣika’s view of negation in the light of their statement- “Negation always has a counter positive and absolute negation is an impossibility.”"],["2023","15","Present Bhatta’s view of anupalabdhi (non-cognition) as a valid means of knowledge."],["2023","15","Elucidate Naiyayikas view of ordinary) and (extraordinary perception, Are justified in accepting that universals are perceived Discuss."],["2023","20","Elucidate Naiyayikas account of fallacies of the middle term in relation to five characteristics of valid middle term."],["2023","15","Write a note on Nyaya notion of Prāgabhāva (prior non-existence). How does this notion help Naiyayikas in defending their position on causation against the Samkhya view of causation? Critically discuss."],["2023","15","Do words refer to universals or particulars or both? Present an exposition of Nyaya and Mimämsä position with regard to above question along with suitable examples."],["2022","10","What is the ontological status of Sāmānya, according to Vaiśesika Philosophy? Critically examine."],["2021","10","Does the seed contain the tree? Discuss with reference to Nyāya-Vaišeṣika Philosophy."],["2021","10","Explain with reference to Nyāya Philosophy, the nature of sabda as the advice of āpta (a reliable person)."],["2021","10","Is ‘inseparability’ (ayuta-siddhatva) a necessary condition or a sufficient condition for defining characteristics (laksana) of samavaya (inherence)? Explain with reference to Vaiseṣika Philosophy.’"],["2020","15","Explain the concepts of ‘Anyathasiddha and ‘Ananyathasiddha’ in the context of Asatkaryavada."],["2020","15","Critically evaluate the logical and metaphysical status of Visesa in the context of Vaisesika Philosophy."],["2019","10","Justify the status of Abhava as a category in Vaisesika philosophy."],["2019","15","What is the role of Jnanalaksana-pratyaka is explaining Anyathakhyati?"],["2019","20","How does Udayana prove the existence of God through Karyat, Ayojanat, Dhrtyadeh and Sruteh? Discuss."],["2018","10","How do the Vaišeṣika philosophers explain the difference of the relationships in the Iwo cases-(i) the brown colour of the table and (ii) the book on the table? Discuss."],["2018","10","How do the Buddhists and the Nyāya philosophers explain our knowledge of ‘the absence of the jar on the table’? Answer in detail."],["2018","20","How do thc Naiyāyikas prove the existence of God? Do the Yoga philosophers prove God in the same way? If yes, how? And if no, why? Give reasons for your answer."],["2017","10","What are the necessary characteristics of padartha according to vaisesika philosophy?"],["2017","10","Explain the conditions of valid hetu as propounded in Nyaya philosophy."],["2017","20","Explain the early Nyaya definition of perception. Why this definition is considered inadequate by the later Naiyayikas?"],["2016","20","How do the Nyayayikas justify the introduction of 'Abhava' as an independent category? Explain."],["2015","15","‘Our knowledge is confined to gunas only’. Examine this statement in the light of Vaisesika and Buddhist controversy."],["2015","15","Is anyathakhyativada an adequate explanation of error?"],["2014","20","Bring out the philosophical implications of introducing extraordinary (aluakik) perception in Nyaya philosophy."],["2013","10","What is Samavaya? What are the grounds for accepting samavaya as distinct padartha?"],["2013","12.5","Analyse the Nyaya concept of vyapti and examine its relation with tark ."],["2013","12.5","Examine Nyaya-Vaisesika’s arguments for the existence of jivatma(soul)."]]},{"id":"o1_17","name":"Mimamsa","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Discuss the debate between the Bhatta and the Prabhakara mimamsakas with reference to the nature of Non-existence (Abhava) and its knowledge."],["2025","10","Delineate the main points of difference between the theory of intrinsic validation (svatah pramanyavada) and theory of extrinsic validation (paratah pramanyavada) in classical Indian philosophy."],["2024","15","On what grounds do the Prabhakaras and the Naiyayikas reject memory as a source of knowledge? Discuss."],["2024","15","\"A candidate who is never seen to be studying during the day-time secures a high position in a competitive exam.\" How would the Bhatta Mimamsakas and the Naiyayikas explain the success of this candidate? Discuss."],["2024","20","How do I know that I know? Answer this question with reference to the Naiyayikas, the Bhatta Mimamsakas and the Prabhakaras."],["2024","10","How does Bhatta's view of nature of word-meaning and sentential-meaning differ from Prabhakara's view? Critically discuss."],["2022","15","How do Mīmāṃsakas refute the Nyāya view that Implication (arthāpatti) is reducible to Inference (anumäna) and establish Implication as an independent means of valid knowledge (pramāṇa)? Critically discuss."],["2022","20","Inspite of accepting the intrinsic validity of knowledge, why and how Prabhākar and Kumārila differ in their interpretation of erroneous cognition? Discuss."],["2021","15","What, according to Mīmāṃsakas, is the ontological status of abhāva (absence) and how does one know it? Explain and examine."],["2020","10","Why is memory not a valid knowledge according to Mimamasa?"],["2019","10","How does Mimamsa establish the authority of Vedic knowledge?"],["2017","15","Explain the theory of validity of knowledge (pramanyavada) according to mimamsa. How do they criticize the Nyaya theory of validity?"],["2016","15","What is the logical necessity for the Mimamsas to treat ‘Arthapatti’ as anindependent Pramana? Discuss."],["2015","20","Elaborate Nyaya-Mimamsa debate on Pramanyavada."],["2014","15","How is an absence of an object known according to Naiyayikas and Mimamsakas? Discuss."],["2014","10","Can Arthapatti (postulation) be reduced to Anumana (inference )? Discuss it from Mimamsa point of view."],["2013","12.5","Evaluate Prabhakar Mimamsaka’s arguments for accepting sruti as pramana."],["2013","10","How is the pramanya (validity/truth) of a statement determined? Examine in this context the theory of paratah pramanyavada."]]},{"id":"o1_18","name":"Schools of Vedanta","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","20","Discuss the idea of Bimba-pratibimbavada as presented in Vedanta philosophy along with its soteriological significance."],["2025","20","How is Brahman conceptualised in Advaita philosophy as both Nimitta and Upadana Karana of the World? Discuss with suitable examples."],["2025","10","Examine Ramanuja's seven objections against Mayavada of Advaita."],["2024","10","\"In Visistadvaita philosophy, the relationship between God and the world is parallel to that between an individual self and its body.\" Critically discuss."],["2023","20","Discuss Rāmānuja’s criticism of Sankara’s conception of Brahman and Isvara (God)."],["2023","10","What is Advaitin interpretation of the great sentence (mahāvākya) ‘Thou art that’ ( tat tvam asi)? Briefly discuss."],["2023","15","Liberation is defined by Advaita Vedäntins as attainment of that which is already attained’. How does Sankara illustrate this statement Discuss with your own comments."],["2022","20","‘Brahma satyam jagat mithyā, jīvo Brahmaiva näparah’. In the light of this statement explain the ontological status of Isvara, Jiva and Sākṣi as elucidated in Advaita Vedānta."],["2022","10","Do you agree with the view that “Vivartavāda is the logical development of Pariṇāmavada”? Give reasons in support of your answer."],["2022","15","How does the concept of Liberation (Moksa) of Madhvācārya differ from that of Rāmānujācārya? Explain."],["2021","20","How do the advocates of anirvachniya-khyati refute the position of Naiyayikas and establish the position of Advaitins regarding the problem of error? Critically discuss."],["2021","15","Compare and contrast the views of Sankara and Rāmānuja regarding the status of the world."],["2021","15","Explain the status of jiva and jagat in the philosophy of Mādhvācārya."],["2020","10","Point out the significance of the five-fold differences in the Dualistic School of Vedänta."],["2020","10","Discuss the nature and types of matter according to Nimbarka."],["2020","15","Discuss the nature and relationship of Jiva and Jiva-sakshi to non-dualism."],["2019","20","Explain the logical consequences of the metaphysical absolutism of Advaitism."],["2018","10","What is the difference between the indescribability (Anirvacaniyatā) of Brahman and the indescribability (Anirvacaniyata) of Māya in the Advaita Vedānta system? Discuss"],["2018","20","Give a comparative cxposition of the concept of Moksa as found in the systems of Višistādvaita, Dvaita, Suddhadvaita and Acintyabhedābheda."],["2018","15","How do the Advaita Vedāntins react to the Prakrtipariṇāmavāda of the Samkhya philosophy? How do the Särhkhyas defend their own position in this regard? Discuss."],["2018","15","How does Rāmānuja refute the doctrine of Maya as propounded by Sankara? Whyis Māyā needed by both Råmånuja and Sankara lo establish their doctrincs? Discuss."],["2018","20","Does the admission of Svayamprakaśavada necessarily lead to the admission of Svatahprāmāṇyavāda? Discuss after the Naiyayikas, the Mīmāṃsakas and the Advaita Vedantins."],["2017","15","Distinguish between vivartavada and parinamvada with reference to causation and explain how in the light of these theories Sankara and Ramanuja differ on the status of the world."],["2017","15","Explain Ramanuja’s conception of God and examine the difficulties he faced in explaining the relation of God to matter and spirits."],["2016","10","Evaluate Sankara’s position on Isvara."],["2015","10","Pancavidhbheda."],["2015","20","Compare and contrast the notion of Brahman in Sankar and Ramanuja."],["2014","20","How does nature of Brahman differ in the philosophy of Shankar, Ramanuja and Madhva? Discuss critically."],["2014","10","Bring out the significance of the concept of adhyasa in Sankara’s philosophy to develop his metaphysics."],["2013","12.5","Describe the five types of differences (Panchvidbheda). Bring out their philosophical significance for Madhva’s theory."],["2013","12.5","How can Isvara (God) be distinguished from Brahman( Absolute)? Which of the two concepts are philosophically better?"],["2013","12.5","Distinguish between svarup lakshan and tatastha lakshan of Brahman after Sankara."],["2013","12.5","Evaluate Ramanuja’s critique of Sankara’s theory of maya."]]},{"id":"o1_19","name":"Yoga","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","Explain the nature of God and its role in Kaivalya in yoga philosophy."],["2024","15","\"So long as there are changes and modifications in citta, the self is reflected therein, and, in the absence of discriminative knowledge, identifies itself with them.\" Present an appraisal of Yoga Soteriology in the light of the above statement."],["2023","15","Explain Chitta and its modifications in the philosophy of Yoga. Why does Yoga philosophy prescribe cessation of modifications of Chitta? Give reasons in support of your answer."],["2022","10","Discuss the nature and different stages of Samādhi as per Pātanjala yoga and examine the role of Isvara in it."],["2021","20","Explain with reference to yoga philosophy the nature of Klesas. How does the removal of these lead to Kaivelya?"],["2020","10","Explain the difference between Samprajnata Samadhi and Asamprajnata Samadhi."],["2019","15","How would Yoga philosophy comprehend the Citta-levels of a Scientist, a God-realized Devotee and a Self-realized Yogi? Justify your answer."],["2017","10","What is meant by ‘yogacittavrittinirodha’? Explain cittavritti and its effects according to yoga philosophy."],["2016","15","What are Klesha's? How can these be eliminated? Explain."],["2015","20","What is bondage according to Yoga philosophy?Explain the method of attaining Kaivelya in Patanjali’s Yogasutra."],["2014","15","Explain the nature and levels of samprajnata Samadhi. How does each level lead more towards to asamprajnata Samadhi?"],["2013","12.5","Give a critical account of the accept of cittavritti in Yoga philosophy."]]},{"id":"o1_20","name":"Aurobindo","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","15","\"Both Ascetic and materialist are partial in their negation of each other.\" Explain Sri Aurobindo's integral philosophy in the light of the above statement."],["2024","15","\"Our Yoga is a double movement of ascent and descent.\" Discuss the above statement in the context of Sri Aurobindo's conception of Integral Yoga."],["2023","10","Explain the nature and role of Supermind in evolution as per Aurobindo’s philosophy."],["2022","15","Explain and evaluate the role of integral yoga in the process of triple transformation for individual evolution as expounded by Sri Aurobindo."],["2021","20","According to SriAurobindo, “the awakening of the psychic being and its gradual prominence over all other parts of the being is the first step in the conscious evolution of man.” Explain the significance."],["2020","20","What does Aurobindo mean by lite divine as a possibility and inevitability?"],["2019","15","Explain the unique position of the supermind in the metaphysical scheme of Aurobindo’s philosophy."],["2018","15","What is Evolution according to Sri Aurobindo? Describe the process of triple transformation and the nature of gnostic being in his philosophy."],["2017","15","How does Sri Aurobindo’s integral yoga help in the realization of supramental consciousness? Discuss"],["2016","20","Discuss Aurobindo’s views on ‘Evolution’ and ‘Involution’. How do they differ from traditional Yoga philosophy?"],["2015","10","Sri Aurobindo’s Integral Yoga"],["2014","15","How is Sri Aurobindo’s integral yoga is an advancement over Patajala’s yoga? Discuss."],["2013","10","Explain Sri Aurobindo’s conception of cosmic salvation through spiritual salvation of individual."]]}]}]},{"name":"Optional II","subjects":[{"name":"Socio-Political Philosophy","chapters":[{"id":"o2_1","name":"Social, Political Ideals – Equality, Justice, Liberty","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","10","Why does Rawls consider it necessary that the two principles of justice be applied in lexical order? Explain."],["2026","15","Negative liberty seems to embody the idea of ultimate personal freedom, whereas positive liberty enables individuals to achieve their full potential. Discuss."],["2025","10","Discuss the salient features of equality according to J.S. Mill."],["2025","20","How are both equality and liberty inadequate as social and political ideals without justice? Discuss."],["2024","10","Briefly discuss Plato’s concept of justice."],["2024","15","Critically evaluate the concepts of liberty and equality as political ideals."],["2023","10","What is meant by justice as fairness? Explain Rawls’ theory of justice."],["2022","10","“Complete liberty may lead to inequality while order and restrictions imply a necessary loss of freedom.” Critically discuss."],["2021","20","Discuss whether Amartya Sen’s idea of justice is an improvement upon Rawls’s theory of justice."],["2021","10","Discuss critically the distributive theory of justice as propounded by R. Nozick."],["2021","10","How does Rousseau distinguish between natural and artificial inequality? Explain."],["2020","10","Is the concept of liberty realizable in the modern technological society? Explain."],["2019","10","How far do you think John Rawls is continuing with Plato’s concept of justice?"],["2019","15","Does liberty put limitations to equality? Discuss."],["2018","20","How far can liberty and equality be considered as distinctive features of democracy? Discuss."],["2017","10","Discuss the different aspects of the fundamental distinction between democratic equality and the Marxian notion of equality."],["2017","15","How far do Marx, Gandhi and Amartya Sen agree and disagree on the concept of justice in the Indian democracy? Discuss"],["2016","10","A well-ordered society, according to Rawls, is effectively regulated by a public conception of justice. Do you agree? Give reasons."],["2016","15","Is liberty a positive and equal opportunity of self-realization? Discuss."],["2015","10","“Equality does not mean treating everyone equal”. Discuss."],["2015","15","“Equality will be of no value without fraternity and liberty.” Discuss."],["2014","15","Discuss Amartya Sen’s principle of Niti as critique of Nyaya."],["2013","15","Explain evaluate Aristotle’s concept of justice."],["2013","15","What is meant by ‘justice’ as fairness? Explain the basic tenets of Rawls’ theory of justice ."],["2013","20","How is Amartya Sen’s approach to justice is different from that of Rawls?"]]},{"id":"o2_2","name":"Sovereignty","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","20","Evaluate the importance of Kautilya’s theory of Rajamandala in the context of sovereignty."],["2026","15","Explain the contrast between the monistic and pluralistic approaches to sovereignty."],["2025","15","‘There is no permanent friend or permanent enemy.’ Discuss this statement in the light of Kautilya’s view on Sovereignty."],["2024","15","What insights does the Arthaśāstra offer with regard to the concept of sovereignty? Does it have any relevance in the modern times? Critically discuss."],["2023","20","Elucidate why the absolute nature of sovereignty was rejected by Laski."],["2022","20","What arguments does Bodin present to contend that sovereignty must be absolute, perpetual and undivided? Is Bodin’s conception of sovereignty compatible with the social and political ideals of equality, justice and liberty? Critically discuss."],["2021","10","Is Austin’s theory of sovereignty compatible with democracy? Discuss."],["2021","15","Discuss Kautilya’s contribution regarding the concept of sovereignty. Is it applicable in a democratic form of government? Explain."],["2020","10","Explain the importance of Bodin’s theory of sovereignty."],["2020","15","State and explain the relevance of the doctrine of sovereignty in times of globalization."],["2019","20","Discuss how far does Austin’s concept of sovereignty go along with Kautilya’s concept of sovereignty."],["2018","15","Critically evaluate Laski’s view on sovereignty as a satisfactory position in political theory."],["2018","10","Discuss Kautilya’s concept of sovereignty in the light of Danda-neeti’."],["2017","15","Discuss whether Kautilya’s concept of sovereignty turns into a despotic rule. How far is it comparable to Bodin’s concept? Discuss"],["2016","10","“Sovereignty is the supreme power over citizens and subjects, unrestrained by law.” Discuss."],["2016","15","On what grounds does Laski criticize Austin’s concept of sovereignty?"],["2015","10","Explain Harold Laski’s critique of sovereignty."],["2014","10","Explain the significance of John Austin’s theory of sovereignty. How does it differ from that of Hobbes?"]]},{"id":"o2_3","name":"Individual and State","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","10","Is Plato’s vision of an ideal state compatible with the rights and liberties of individual citizens? Discuss."],["2025","15","“Duties are of the nature of obligation while Rights are of the nature of entitlement. Therefore there is no necessary connection between the two.” Do you agree with this statement? Give reasons and justification for your answer."],["2024","10","Present a brief account of origin and development of Social Contract Theory."],["2024","20","Do you agree with the view that Aristotle was more successful than Plato in steering a middle course between ‘Statism’ and ‘individualism’? Discuss with arguments."],["2023","15","Do you agree that duty and accountability must be given priority over rights for the better functioning of a State? Justify your answer."],["2021","15","Evaluate whether the social contract theory adequately addresses the different issues of human rights."],["2020","15","Is Indian tradition antagonistic to Individual Rights? Consider it by taking recourse to the doctrine of Human Rights."],["2019","20","Do rights make citizens accountable to the state? Argue in the context of the present Indian scenario."],["2018","20","“Human rights and human dignity would no longer be the product of a particular culture, rather a common human aspiration for an ideal world.” Discuss."],["2017","10","Out of rights and duties which one is prior to the other? Discuss in the context of accountability."],["2016","10","Evaluate the statement that all human beings have certain unalienable rights."],["2016","20","“The right of free speech implies the genuine independence of the judiciary and its complete separation from the executive.” Evaluate."],["2015","10","How are individual and group rights reconciled in democracy? Explain ."],["2014","20","“All human rights are centered on individual rights.” Discuss."],["2013","10","What is the significance of including duties of citizens in the Indian constitution?"]]},{"id":"o2_4","name":"Forms of Government","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","15","“The two antagonistic state structures – monarchy and democracy, both share some common features with dictatorship”. Do you agree with this view? Give reasons and justifications for your answer."],["2025","10","Comment on Plato’s critique of Democracy."],["2025","15","Can Theocracy be accepted as a valid form of Government? Give reasons and justification in support of your answer."],["2023","10","If monarchs are above politics, can monarchy be a systematic form of government? Discuss."],["2023","15","Explain the challenges faced by a democratic state and the ways to overcome them."],["2022","20","Discuss propaganda as a challenge to democratic form of government."],["2021","10","Does monarchy as a form of government leave room for individual freedom? Explain."],["2020","10","How far do the liberal democracies safeguard the interests of minorities? Evaluate critically."],["2019","10","Discuss the status of theocracy in the modern secular state."],["2019","20","Examine whether there is any difference between the views of Mahatma Gandhi and Dr. Babasaheb Ambedkar on the philosophical foundations of secular democracy."],["2018","10","What is meant by liberal democracy? Does it require deeper principles for social cohesion to balance its own strong affirmation of individual rights? Give reasons from the Indian context."],["2017","10","Discuss whether a blending of monarchy with democracy is conceivable to avoid their undesirable defects for making the governance better for citizens and state."],["2016","10","“Socialism itself is the fulfilment of democracy.” Analyse."],["2015","10","Is civil disobedience in a democratic state justifiable? Discuss."],["2015","20","Evaluate the nature o and functions of parliamentary democracy."],["2014","15","In what sense is democracy better form of government than theocracy?"],["2013","15","What is meant by democracy? What are various forms of democratic governments?"],["2013","15","Is a democratic government able to represent the interest of minority groups?"],["2013","20","Is a democratic government better than a benevolent dictatorship? Give reasons for your answer ."],["2013","10","Does the combination of democracy and socialism lead to a more equitable society?"]]},{"id":"o2_5","name":"Political Ideologies","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","10","Anarchism is not an independent political ideology in itself, rather it is inspired by liberalism on the one hand and socialism on the other. Analyze."],["2026","10","On what grounds does Marxism criticize pure democracy?"],["2025","15","Evaluate Marxism as a Political Ideology."],["2024","10","Present an exposition of the concept of alienation as propounded by Marx."],["2024","10","Compare socialism and communism as two distinct political ideologies."],["2023","10","Critically examine the anarchist’s view that “all States always and everywhere are illegitimate and unjust.”"],["2023","20","Explain Historical Materialism and discuss its relevance in the extract of social development and change."],["2022","15","Explain the difference between the notion of equity and equality with reference to Marxian philosophy."],["2022","15","Does idea of unconditional rights necessarily lead to anarchy? Critically examine."],["2022","15","Are monarchy and theocracy necessarily related? Discuss with reference to the theory of Divine Right."],["2021","20","Discuss anarchism as a political ideology. Is it possible to dispense with political authority completely? Give reasons for your answers."],["2021","15","Discuss the distinctive features of Gandhian Socialism and its contemporary relevance."],["2020","15","How far is Marxism as a philosophical doctrine relevant in the present context? Justify your answer."],["2020","10","Do you think that the prevailing pandemic will lead to anarchism in society? Discuss."],["2019","10","Evaluate Mahatma Gandhi as a political anarchist."],["2019","15","What do you consider to be the future of Marxism in the context of the prevalent free market economy?"],["2018","15","Are Marxian Socialism and individual freedom consistent? Discuss critically."],["2018","15","Do you subscribe to the political ideology of Anarchists? Justify your answer."],["2017","10","Discuss in the context of Anarchy whether the freedom of an individual is consistent with the sovereignty of the state?"],["2017","20","Does Marxism curb individual freedom in the name of protecting social justice? Discuss"],["2016","20","Is the State an agency for expressing the will of the ruling classes? Examine."]]},{"id":"o2_6","name":"Humanism, Secularism and Multiculturalism","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","15","Examine the challenges faced by a multicultural society in creating a harmonious balance between group rights and individual rights."],["2025","10","Is the idea of secularism necessarily related to the idea of religious pluralism? Discuss."],["2025","15","How does the reconciliation of opposites take place in the Humanism of Tagore? Evaluate."],["2024","20","Delineate the central tenets of Humanism. How does advent of enlightenment in Europe pave the way for Humanism? Discuss."],["2024","15","Present an exposition of Gandhi’s views on secularism as one of the foundational principles of democracy."],["2024","15","Discuss the role of ethical principles of tolerance and coexistence for the rise of multicultural societies."],["2023","10","Critically examine the challenges faced by a multicultural society with reference to India."],["2023","15","Secularism is not a rejection of religion but acceptance of all religions. Discuss."],["2022","10","Discuss the role of enlightenment movement in the rise of humanism."],["2022","15","Critically analyze the descriptive and normative aspects of multiculturalism."],["2021","15","Can humanism be a substitute for religion? Explain and evaluate in the context of the present Indian society."],["2020","10","Do you think that secularism requires complete separation of religion and ‘state’? Discuss."],["2020","15","What do you understand by multiculturalism? Explain the structural Characteristics that make a nation multicultural."],["2019","15","What are the descriptive and normative perspectives on ideas of multiculturalism?"],["2018","15","What form of humanism do you approve as relevant in the present day context? Discuss in detail."],["2018","20","What do you understand by multiculturalism? How are globalization and multi-culturalism related? How does their relationship affect cultural changes?"],["2018","10","Do you subscribe to the view that Indian cultural identity needs to integrate the principles of multiculturalism and respect for the dignity of each person? Justify your answer."],["2017","20","Do you agree with the view that secularism as a western ideal is redundant in the Indian context? Discuss in the context of the multicultural Indian society."],["2016","15","Can we consider “freedom from domination” as one of the justifications for multiculturalism? Give reasons for your answer."],["2015","15","Is multiculturalism a need of global society? Discuss."],["2015","20","How is religious nationalism a threat to secular society? Explain."],["2014","15","Explain descriptive and normative perspectives on multiculturalism."],["2014","10","How does multiculturalism redefine liberal notions like identity, freedom and equality and reformulate its assumptions?"],["2014","10","How do we distinguish liberal humanism and Marxist humanism?"],["2013","10","Does the idea of equal respect to all religion provide a viable and consistent state policy?"]]},{"id":"o2_7","name":"Crime and Punishment","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","10","How does value based education address the problem of corruption?"],["2026","20","Retributivism presents a deontological justification for capital punishment, whereas deterrence presents a consequential justification for it. Explain."],["2025","10","“Corrupt practices reveal an inherent tension between particularistic and universalistic normative standards.” Do you agree with this statement? Give reasons and justification for your answer."],["2025","20","Can one’s right to life be absolute? Answer with reference to the idea of Capital Punishment."],["2024","15","On what grounds would you accept or reject the idea of capital punishment as an effective deterrent? Discuss."],["2023","20","Severity of punishment should be proportionate to the seriousness of the crime,” – Do you agree that while punishing a juvenile, the nature of the crime should be considered? Justify your answer."],["2022","10","Is corruption a systemic issue or an ethical issue? Give your critical comments."],["2022","10","What are the moral justifications of capital punishment? Discuss."],["2021","15","Explain the reformative theory of punishment and discuss whether this is in tune with human dignity."],["2020","15","Do you think that retributive theory of punishment is against human rights? Discuss."],["2020","15","How far do the social and political regimes condition corrupt practices in a nation-state? Discuss."],["2019","10","Is corruption not a form of mass violence? Discuss."],["2019","15","Does capital punishment weaken the doctrine of social justice? Discuss."],["2018","10","What measures do you suggest to eradicate corruption in Indian democracy?"],["2017","15","Can you justify capital punishment for crimes like rape, murder and corruption? Discuss"],["2016","10","“The goal in punishing should be to reform the individual.” Comment."],["2015","15","“The aim of punishment is to defend the moral law and to do justice to criminal.”Discuss."],["2014","20","Analyse the statement with reasons that “Power corrupts , absolute power corrupts absolutely”."],["2014","20","Which theory of punishment retributive or restorative, do you recommend and why?"],["2014","10","Can we say that racial supremacy is the main reason for genocide? Give reasons for your answer."],["2013","10","Does corruption have not only a moral dimension but also an economic dimension?"]]},{"id":"o2_8","name":"Development and Social Progress","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","15","Examine the relationship between democracy and development. Does democracy promote or hinder development?"],["2025","15","Is it possible to reconcile the concept of development with tribal values to bring social and economic progress? Discuss."],["2024","15","Is economic development a necessary condition, sufficient condition, both or neither, in order to achieve social progress? Give reasons and justifications for your answer."],["2023","15","In the present scenario, will the emphasis on skill education enhance development? Evaluate."],["2022","20","Do you agree that economic development does not on its own lead to human development and social progress? Give reasons and justifications for your answer."],["2020","20","State and examine the Gandhian concept of social development."],["2019","15","Does technological development lead to progress in the ethical standards of the society? Explain."],["2017","15","Critically evaluate whether the ideal of social progress gives a secondary significance to an individual’s freedom over his duties."],["2017","20","Evaluate the concept of social development as rooted in ethical principles against the concept of social progress being based on economic and political ideals."],["2016","15","Is it possible to measure social progress independent of economic development? Discuss."],["2015","10","“Inequitable development leads to social conflicts rather than social progress.” Explain."],["2014","15","By eliminating alienation can we bring social progress?"]]},{"id":"o2_9","name":"Gender Discrimination","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","15","Does providing land and property rights to women constitute a necessary condition or a sufficient condition or both for ensuring social equality among the genders? Discuss."],["2025","10","How does gender as a social construct affect individuals’ opportunities, rights, and access to resources? Critically discuss."],["2024","20","Discuss gender equality as a necessary condition to achieve empowerment of women. Also examine the role of women empowerment in curbing the menace of female foeticide."],["2023","15","How does gender discrimination lead to female foeticide and social imbalance? Discuss."],["2023","10","Do you agree that the rights concerning land and property have empowered women? Discuss."],["2022","15","Discuss gender as a cultural category as opposed to sex as a biological category."],["2021","10","How far can land and property rights be effective in empowerment of women? Explain."],["2021","15","What are the main causes of female foeticide in India? It is the result of demonic application fo technology only? Discuss."],["2020","20","Do you agree that empowering women can eliminate gender discrimination? Discuss."],["2019","10","Can gender equality be realised within a socialist regime? Analyse."],["2019","15","Consider critically, that gender discrimination is a rather man-made concept but not naturally endowed."],["2018","15","Is feminism an ideology for empowerment or for equality? Discuss."],["2018","15","How do you evaluate gender discrimination in the context of female foeticide?"],["2017","15","Is empowerment of women a sufficient means to their equal rights to land, property and divorce? Discuss in the context of religious sanction."],["2017","15","Will a severe punishment for crimes against women change the mindset of society? Justify your position."],["2016","15","“To me the female sex is not the weaker sex. It is the nobler of the two.” Evaluate this statement of Gandhi."],["2016","15","Do you agree that women become empowered through collective reflection and decision-making? Discuss."],["2015","15","What does gender discrimination mean? Is not a violation of equality and social justice? Discuss."],["2015","15","Does economic empowerment of women eliminate gender discrimination? Discuss."],["2014","15","“One is not born woman , but she becomes a woman. Critically comment on it."],["2013","15","What do you understand by ‘gender equality’ and why is it important?"],["2013","15","Is economic independence essential for equality between men and women?"],["2013","20","Why is adequate representation of women in political institution important in this context?"]]},{"id":"o2_10","name":"Caste Discrimination – Gandhi and Ambedkar","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","20","How has Ambedkar applied the concept of ‘Social Endosmosis’ for annihilation of castes. Evaluate its relevance for contemporary debates on identity and the politics of difference."],["2025","20","Present a detailed account of the debate between Gandhi and Ambedkar on the issue of caste discrimination."],["2024","10","Discuss the main factors responsible for caste discrimination."],["2023","15","Critically analyse the social and political significance of Ambedkar’s notion of annihilation of caste."],["2022","15","Critically evaluate Gandhi’s views on eradication of caste discrimination."],["2021","20","Discuss the views of Dr B.R. Ambedkar regarding caste discrimination in Indian society. What are the measures suggested by him for its elimination? Explain."],["2020","20","State and examine B.R. Ambedkar’s contribution towards social changes in Independent India."],["2018","10","It is said that the traditional hold of caste-based groups on Indian social behaviour has survived all attempts to build alternate identities. Discuss in the light of M.K. Gandhi."],["2017","10","Is caste discrimination a result of the superiority complex of a privileged class of the society or of religious rituals? Discuss with reference to the views of propounded by Dr B. R. Ambedkar."],["2016","20","How did Ambedkar analyse the caste system from the historical and social perspectives? Explain."],["2015","20","Evaluate Ambedkar’s critique of caste system."],["2015","15","“Man must grow materially as well as spiritually.” Evaluate this statement of Ambedkar."],["2014","15","What are the basic differences between Gandhi and Ambedkar regarding caste discrimination?"],["2014","10","If caste discrimination has any continuity and hierarchy which principle of justice can dissolve this problem?"],["2013","10","Is there any impact of caste discrimination on democracy in Indian context?"]]}]},{"name":"Philosophy of Religion","chapters":[{"id":"o2_11","name":"Notions of God","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","15","Discuss the difference between personalistic and impersonalistic notions of God in the context of devotion."],["2026","15","Present an account of criticisms against omniscience and omnipotence as attributes of God."],["2024","15","How does the notion of God in Spinoza’s philosophy embedded in his metaphysics of substance and attributes? Critically discuss."],["2024","15","“In order to be conceived as the ultimate cause of the world, God must necessarily have some form of physical manifestation.” Do you agree with this view? Give reasons and justifications for your answer."],["2023","10","Elucidate the personalistic and impersonalistic aspects of God."],["2023","15","In what sense is God both immanent and transcendent in theism? Discuss."],["2022","10","Write an essay on Spinoza’s notion of God and His attributes."],["2022","15","Explain the relation between the God and the Self according to Ramanujācārya."],["2021","10","Discuss the nature of God as propounded in Nyaya philosophy."],["2020","10","Discuss the significance of ‘Religion’ vis-à-vis the present scientific and technological development."],["2020","10","Is there any compatibility between ‹Freedom of Will› and ‹Omnipotent God’? Discuss."],["2020","20","Discuss the nature of God in Hinduism with special reference to Vishishtadvaita (Qualified non-dualism)."],["2020","15","Distinguish between prayer and worship and determine their place in religion."],["2019","10","Is religion a uniting force for humanity in the globalizing world as of today? Discuss."],["2019","10","Can there be a philosophical argument to support violence in the name of religion? Discuss."],["2019","15","State and evaluate the personalistic and impersonalistic aspects of God."],["2019","15","Discuss the relationship between man and God according to any one of the religions in India."],["2018","10","Is Hinduism polytheistic? Give reasons for your answer."],["2018","20","The terms “Sacred’ and ‘Holy’ have come to serve as generic names for the object of religion. Do you agree that one can have God as the object of religion? Discuss."],["2017","10","Critically discuss the relationship of man with God in the Yoga system of philosophy."],["2017","15","What is a non-theological concept of God? How is it different from theological concept of God? Discuss with arguments."],["2016","10","Critically discuss the view that ‘modern sensibility and total obedience to a despotic God’ do not go hand in hand."],["2016","20","Compare and contrast the relation of man to the world in the oriental religions."],["2016","15","Show how the attributes of immanence and transcendence of God go with omnipresence and infinitude."],["2015","10","Write a critical note on the attributes of God."],["2014","20","Elucidate the status of man in the realm of between immanence and transcendence."],["2013","10","Is god indispensable for religion?"]]},{"id":"o2_12","name":"Proofs for the Existence of God","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","10","Discuss Aquinas’ argument from the contingency of the world to prove the existence of God."],["2026","15","Explain and examine Madhvacharya’s arguments for the existence of God."],["2025","20","Present an account of Design argument to prove the existence of God along with its criticism by David Hume."],["2025","15","What proofs do Nyāya philosophers offer for the existence of God? Discuss."],["2024","15","Present an exposition of ontological proof for the existence of God along with its criticism."],["2023","20","Critically examine of arguments of Nyaya of the existence of God."],["2022","20","Discuss the main points of distinction between a priori and a- posteriori arguments for the existence of God. Which one according to you should be preferred over the other? Give reasons and justifications for your answer."],["2022","20","Present a critical exposition of different arguments offered by St. Thomas Aquinas to prove the existence of God also known as ‘Five Ways’. Which one of them do you find philosophically most interesting? Give reasons in support of your answer."],["2021","15","Give a critical account of moral argument to prove the existence of God."],["2020","20","It is ontological proof for the existence of God by St. Anselm logical? Discuss."],["2019","10","State and evaluate the profs for the existence of God as propounded in Jainism."],["2018","15","Does the concept of God entail the existence of God? Examine from the perspective of ontological argument."],["2018","20","Compare St. Thomas Aquinas’ five ways of knowing God with the arguments of the Nyāya School of Indian Philosophy for the existence of God."],["2017","15","Compare and contrast the different forms of cosmological arguments for the existence of God."],["2016","15","“It would be self-contradictory to say that the most perfect conceivable being lacks the attribute of existence.” Analyse."],["2016","15","“The natural world is as complexly and manifestly designed as a watch.” Evaluate."],["2015","10","Is existence of God a necessary condition for the survival of religion? Explain."],["2015","20","Examine the Nyaya arguments in favour of the existence of God."],["2015","15","Examine the ontological and cosmological arguments in favour of existence of God."],["2014","15","Discuss the ontological argument for the existence of God, and show its merits and demerits."],["2014","15","Can it self-contradictory to accept the idea of God but deny the existence of God?"],["2013","15","State and elucidate cosmological argument for the existence of god in Western and Indian philosophy ."],["2013","15","Discuss two main objections against this argument . Are theist able to answer these satisfactorily."],["2013","20","Critically evaluate three main objections against the argument from design for the existence of god."]]},{"id":"o2_13","name":"Problem of Evil","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","20","In what sense does St. Augustine’s identification of all evil as either sin or as the punishment of sin succeed or fail in providing a coherent account of both moral and natural evil? Evaluate."],["2025","15","Explain the main tenets of the Process Theodicy as an explanation of the problem of evil."],["2024","15","“The problem of evil is a direct offshoot of how God is conceptualised in a system.” Critically discuss."],["2023","20","All evil is either sin or punishment for sin.” – St. Augustine. Critically discuss."],["2022","15","If God is the Absolute Creator, then the responsibility of the evil cannot belong to the human agent. Critically examine."],["2021","10","Discuss the paradox of omnipotence of God in the context of the existence of evil."],["2020","15","What is the logical problem of evil? Discuss."],["2019","15","What role do the concepts of evil and profane play to provide a firm foundation to religion?"],["2017","10","How do you define a non-theological concept of evil? Explain"],["2016","20","“If God is all-powerful, God must wish to abolish all evils; but moral and natural evils are rampant in the world.” How would a theist react to this?"],["2015","10","Is God the cause of natural evil? Explain."],["2015","15","Do you think that evil is a bitter pill which no theist can swallow? Discuss."],["2014","20","Is evil reconcilable with the benevolent God?"],["2013","10","Do theist succeed in explaining the natural evil in the world as a necessary counterpart to good?"]]},{"id":"o2_14","name":"Soul Immortality, Rebirth and Liberation","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2025","10","Discuss the nature of embodied liberation (jīvanmukti) with reference to Advaita Vedānta."],["2025","15","Is the concept of immortality of soul a necessary condition for Rebirth? Discuss with reference to the Bhagavad Gītā."],["2024","10","Discuss the concept of liberation (Apavarga) according to Nyāya-Vaiśeṣika."],["2024","20","Is it necessary to adhere to the notions of immortality of soul and rebirth in order to have a robust conception of liberation? Give reasons and justifications for your answer."],["2023","20","Critically examine Plato’s a-priori proofs for the immortality of the soul."],["2023","15","Examine the significance of the concept of of rebirth in theory of Karma."],["2022","10","«Immortality of Soul is a necessary postulate for rebirth.” Critically examine with reference to Buddhism."],["2022","15","Is it possible to have an idea of Liberation without the conception of a real agent? In this context, discuss the difference between Advaita and Visistädvaita systems of thought."],["2022","15","Discuss the nature of Soul and Bondage according to Jainism."],["2021","20","Discuss the concept of immortality of soul with special reference to Hindu tradition."],["2021","15","Elucidate the concept of liberation according to Advaita Vedanta Explain the role of knowledge in the attainment of liberation."],["2021","15","Discuss and evaluate the doctrine of Karma as an essential postulate of Hinduism."],["2020","10","The concept of ‘Immortality’ is a basic presupposition of religion. Elaborate your answer."],["2020","15","Do you accept that knowledge, Action and Devotion are the means to attain liberation in Indian tradition? Discuss"],["2019","20","State and explain the doctrines of Karma, Rebirth and Rebirth and Reincarnation in Hinduism."],["2018","15","Evaluate the concept of Bhakti (Devotion) as a pathway to attain liberation."],["2018","10","How far is it plausible to argue that the anti-theistic religions’ stand on the concept of rebirth is philosophically significant?"],["2017","10","Discuss whether the doctrine of immortality of soul is indispensable for a religion."],["2017","20","Is there an essential difference between the concept of liberation in theological and non-theological approaches of life? Discuss"],["2016","10","Buddhism disbelieves in the immortality of soul, but accepts the phenomenon of rebirth. Examine."],["2015","15","“Immortality means absence of karma and rebirth.” Discuss."],["2015","20","What is liberation? Briefly discuss the ways to attain it as outlined in the system of Vedanta."],["2014","10","How do you justify rebirth with or without the soul?"],["2014","10","What are the arguments given in favour of immortality of soul?"],["2014","15","Compare and contrast the concept of liberation according to ‘Advait’ and ‘Visishtadvait’."],["2013","10","Is there anything else other than human efforts which may be conducive to attainment of liberation?"]]},{"id":"o2_15","name":"Reason, Revelation and Faith","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","10","How does Paul Tillich’s idea of faith as ultimate concern address the relation between faith, doubt and reason? Evaluate."],["2026","10","“If religion were a subject of reason alone, it would have lacked an experiential account.” Do you agree with this statement? Give reasons in support of your answer."],["2025","10","How does Aquinas’ account of Faith as “an intellectual assent” reconcile the juxtaposition between Reason and Faith? Discuss."],["2025","15","Distinguish between Natural Theology and Revealed Theology in the context of the Propositional view of Revelation."],["2024","10","Discuss the role of reason in religion."],["2024","15","What kind of epistemic justifications are possible with regard to claims to revelation? Discuss with your own comments."],["2023","15","Explain the rational and irrational aspects of faith in the discourse of religion."],["2023","10","Can religious beliefs be justified? Discuss."],["2022","10","Is the notion of faith indispensable for the idea of revelation? Critically comment."],["2021","20","Discuss the role of reason and faith in religion. Can reason be regulative force in the formulation of religious beliefs? Explain."],["2020","15","What are the basic tenets of faith? Distinguish between faith and belief."],["2019","10","What is instrumental to self-revelation : Faith or Reason? Justify your position."],["2017","15","Discuss whether the voluntarist’s theories of faith are adequate."],["2016","10","Faith means human awareness of God; but it cannot be irrational. Analyse."],["2016","15","The content of revelation is a body of truths expressed in statements or propositions. But it cannot be against reason. Discuss."],["2015","10","Do reason and faith go together? Discuss."],["2015","15","Can revelation be justified by reason? Discuss"],["2014","15","Can reason be used to justify faith?"],["2013","10","Is religious faith opposed to reason?"]]},{"id":"o2_16","name":"Religious Experience","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","10","On what grounds does William James characterize mystical states as a genuine expression of religious experience? Elaborate."],["2025","20","Evaluate the nature and object of Religious Experience as explained by Radhakrishnan in ‘The Hindu View of Life’."],["2024","15","Discuss the main features of religious experience according to Advaita Vedanta."],["2023","15","Examine the relation between mystical experience and revelation and pound their significance in the religious life."],["2022","15","Discuss the nature and variety of religious experiences as presented by William James."],["2021","15","Explain the concept of religious experience in the light of Vedantic tradition."],["2019","20","Discuss whether and how does religious symbolism lead to mysticism."],["2019","15","How far can religious experience be made a topic of public discourse Analyse."],["2017","15","In order to make expressions of religious experiences communicable, what kind of language needs to be considered and used? Explain."],["2016","20","State and evaluate the nature and validity of mystic experience."],["2015","15","Explain the nature of mysticism Hinduism and Islam."],["2014","15","Discuss the conflicting nature of religious experience with special reference to Buddhism and Jainism."],["2013","15","What is the nature of mystical experience?"],["2013","15","Is mystical experience open to different interpretations?"],["2013","20","Can mystical experience be regarded as valid source of knowledge?"]]},{"id":"o2_17","name":"Religion Without God","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2024","20","State and evaluate Buddhism as a religion without God."],["2021","10","Is religious life possible without the belief in God? Discuss."],["2020","15","Critically examine the concept of God as prerequisite for a religion."],["2019","15","How would a religious person deny the possibility of a religion without God? Discuss."],["2018","10","Can you justify religion without God? Support your answer."],["2018","15","Critically evaluate the Buddhistic arguments against the existence of God as the creator of the world."],["2017","10","Is God necessary for religion? Justify your answer."]]},{"id":"o2_18","name":"Religion and Morality","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","15","How does the issue of moral autonomy conflict with conception of religion as a source of morality? Critically discuss."],["2026","20","Critically evaluate the shift in Gandhi’s view from ‘God is Truth’ to ‘Truth is God’, in the context of interrelation between religion and morality."],["2025","10","Present an account of Nietzsche’s criticism of religion and morality."],["2025","15","Is it necessary for the normative principles to bear reference to God in order to produce a feeling of obligation in a moral agent? Critically discuss."],["2024","10","Can there be a religion without morality? Discuss."],["2023","10","Does religion influence the moral behaviour? Explain the interactive relation between religion and morality."],["2022","10","«One can have morality without religion but not religion without morality.” Discuss."],["2021","15","Do you consider that religion and morality are inseparable? Give reasons for your answer."],["2020","15","Are religious beliefs and practices incompatible with moral behaviour? Discuss."],["2019","10","Does a devoted commitment to a religious way of life make man go astray from social morality? Examine."],["2019","15","Secular ethics cannot fully resolve as to why one should be moral all the time. Examine."],["2018","10","Can one claim that there is an inter-relatedness between ‘religiosity and ‘immorality’? Discuss."],["2017","10","Does a committed religious person go against social morality? Discuss from moral perspective."],["2017","15","What will be the authority and acceptance of the absolute ethical values in the non-theological system of social practices? Discuss"],["2017","15","Can a religious person take an elastic view about religious ideals, principles and practices, etc. which are supposed to be eternal? Will it make religion progressive or will it demolish its authority?Discuss critically."],["2016","15","“Moral principles function better when they remain independent and unconnected with religion.” Discuss."],["2015","10","Is morality necessarily based on religion? Discuss."],["2015","15","“An atheist may be better man than a religious person bereft of moral values.” Discuss."],["2014","20","How far can religious morality incorporate individual freedom?"],["2013","10","Is religious consistent with individual freedom?"]]},{"id":"o2_19","name":"Religious Pluralism and Absolute Truth","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","15","Does the idea of Religious Pluralism necessarily entail moral relativism? Critically discuss."],["2026","15","Can conflicting truth claims among religions be reconciled within the framework of religious pluralism? Critically discuss."],["2025","20","How does the Vedantic view of Religious Pluralism address the conflicting truth claims of different faiths? Answer with reference to Swami Vivekananda’s view of Universal Religion."],["2024","10","Write a note on the notion of absolute truth in the context of religion."],["2023","10","What is Agnosticism? How do agnostics conceptualize the relation between religion and God? Discuss."],["2023","15","Does religious pluralism invite inter-religious conflicts and destroy the ruth of religion? Discuss."],["2022","20","“An unquestionable acceptance of only one Absolute Truth will inevitably result in religious exclusivism.” Discuss."],["2022","15","Critically examine the idea of Brahman in Advaita philosophy of Samkara. Does Samkara’s conception of Brahman leave room for theism? Discuss."],["2021","10","Discuss the possibility of Absolute Truth in the context of religious pluralism."],["2021","10","Is religious freedom possible in a multireligious society? Explain."],["2020","10","Is it acceptable that the History of Religions is the History of Conflicts? Discuss."],["2020","10","What is the importance of religious tolerance in a multicultural pluralistic society? Justify your answer."],["2019","20","Expound and explain the central problem in the discussion between religious pluralists and religious exclusivists."],["2018","15","“Truth is one, yet people perceive differently.” Critically evaluate by considering the present Indian context."],["2018","20","Distinguish between Exclusivism, Inclusivism and Pluralism with regard to the conflicting truth-claims of different religions."],["2017","15","Does religion guarantee the absolute truth? Discuss in the context of religious pluralism."],["2016","10","“World-religion is a spiritualistic and humanistic composite.” Evaluate."],["2016","10","Is Religious absolutism a threat to Religious pluralism? Discuss."],["2014","10","Can pluralist perspective vindicate Absolute Truth?"],["2014","10","If God is regarded as ‘one’, will it give rise to religious conflicts?"],["2014","10","On what grounds , dichotomy between ‘is’ and ‘ought’ can either be justified or rejected?"]]},{"id":"o2_20","name":"Nature of Religious Language","lastRevised":"","status":"Not Started","note":"","revisionCount":0,"pyqs":[["2026","10","Critically discuss the views of R. B. Braithwaite on the nature of religious language."],["2026","20","Analyse R. M. Hare’s concept of ‘blik’ and assess whether it successfully defends the meaningfulness of religious language."],["2025","10","Is religious language symbolic? Give reasons and justification in support of your answer."],["2025","15","Discuss the Advaitic notion of indescribability (anirvachanīyatā) in the context of nature of religious language."],["2024","10","Explain the analogical nature of religious language."],["2024","20","Distinguish between cognitivist and non-cognitivist account of religious language. Does the cognitivist account lead to any contradiction? Answer with reference to the philosophical views of R. B. Braithwaite."],["2023","10","Discuss Wittgenstein’s view about the non-cognitive nature of religious language."],["2023","15","Explain the symbolic nature of religious language according to Tillich."],["2022","10","Explain the difference between the cognitivist and non-cognitivist approaches to the religious language with reference to the statement- “God exists”."],["2021","20","What is non-cognitive theory of religious language? Explain critically in the light of R.B. Braithwaite’s views."],["2021","15","Explain the symbolic nature of religious language with special reference to Paul Tillich."],["2020","20","Does religious language carry cognitive content? Elucidate in detail."],["2018","15","Critically examine Braithwaite’s non-cognitive theory of religious language."],["2018","10","In what sense is the secular use of language different from the religious use of language? Discuss."],["2018","15","Explain the significance of religious symbols as transcendent referent that mediates into the cultural, spatial and temporal world."],["2017","20","Is not the language of analogies more confusing and the language of symbols more unintelligible? Evaluate in the case of religious language."],["2016","15","Among the different views of religious language, which one is more satisfactory and why?"],["2015","20","How can religious language be verified? Is it correct to say that religious language is verified because it can not be falsified? Discuss."],["2014","15","How do you formulate religious language as non-cognitive?"],["2013","15","What is meant by saying that religious is non-cognitive?"],["2013","15","Can religious language can said to be verifiable?"],["2013","20","Do cognitivist provide cogent answer to the objection based on falsifiablity?"]]}]}]}];
const MainsTool = (function(){
  let _onSave=null; const COL={overdue:'#D64545',soon:'#E3A01B',fresh:'#4CA34A',never:'#9aa0b4'};
  let papers=[], view='dash', curP=0, curS=-1, filter='all', expanded={}, addP=0, addS=0;
  const MARKS=[{k:'studied',l:'Studied',c:'#4A43A8'},{k:'notes',l:'Notes',c:'#1f9bb5'},{k:'r1',l:'R1',c:'#3f9d45'},{k:'r2',l:'R2',c:'#E08A1B'},{k:'r3',l:'R3',c:'#D6479A'}];
  const PAL={'GS I':'#4A43A8','GS II':'#0f9fb8','GS III':'#2e9d4a','GS IV · Ethics':'#E8850C','Essay':'#D6479A','Optional I':'#7c5cf0','Optional II':'#e5484d'};
  const EXTRA=['#0c8f6f','#b5651d','#2f6fed','#c2410c','#8b5cf6'];
  const pcol=(name,i)=>PAL[name]||EXTRA[i%EXTRA.length];
  function migrate(ps){ ps.forEach(p=>{ if(p.name==='GS IV') p.name='GS IV · Ethics'; if(p.name==='Optional') p.name='Optional I'; });
    if(!ps.some(p=>p.name==='Optional II')) ps.push({name:'Optional II',subjects:[]});
    return ps; }
  const $=id=>document.getElementById(id);
  /* Optional I/II chapters + PYQs live in MAINS_PRESET; add any that a user's saved data is missing (keeps their progress/notes) */
  function mergeOptional(ps){ MAINS_PRESET.filter(pp=>/^Optional/.test(pp.name)).forEach(pre=>{
      let P=ps.find(x=>x.name===pre.name); if(!P){ P={name:pre.name,subjects:[]}; ps.push(P); }
      pre.subjects.forEach(ps0=>{ let S=P.subjects.find(x=>x.name===ps0.name); if(!S){ S={name:ps0.name,chapters:[]}; P.subjects.push(S); }
        ps0.chapters.forEach(c=>{ if(!S.chapters.some(x=>x.id===c.id)) S.chapters.push(clone(c)); }); }); });
    return ps; }
  const clone=o=>JSON.parse(JSON.stringify(o));
  const esc=s=>(s||'').toString().replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const PYQ_BY_ID={}; MAINS_PRESET.forEach(p=>p.subjects.forEach(s=>s.chapters.forEach(c=>{PYQ_BY_ID[c.id]=c.pyqs||[];})));
  /* PYQs are static preset data (and Firestore rejects nested arrays), so they are not stored; they are re-attached by chapter id on load */
  function hydrate(ps){ ps.forEach(p=>{ p.subjects=p.subjects||[]; p.subjects.forEach(s=>{ s.chapters=s.chapters||[]; s.chapters.forEach(c=>{ c.pyqs=PYQ_BY_ID[c.id]?clone(PYQ_BY_ID[c.id]):[]; }); }); }); return ps; }
  function serialize(){ return {version:2,papers:papers.map(p=>({name:p.name,subjects:p.subjects.map(s=>({name:s.name,chapters:s.chapters.map(c=>{const o=Object.assign({},c); delete o.pyqs; return o;})}))}))}; }
  function save(){ if(_onSave) _onSave(serialize()); }
  function daysSince(d){ if(!d) return null; return Math.floor((new Date().setHours(0,0,0,0)-new Date(d).setHours(0,0,0,0))/86400000); }
  function status(ch){ const d=daysSince(ch.lastRevised); return d===null?'never':d>=15?'overdue':d>=8?'soon':'fresh'; }
  function badge(ch){ const d=daysSince(ch.lastRevised);
    if(d===null) return {cls:'never',text:'Not started'};
    if(d>=15) return {cls:'overdue',text:d+'d ago — revise now'};
    if(d>=8) return {cls:'soon',text:d+'d ago — due soon'};
    return {cls:'fresh',text:d===0?'Revised today':d+'d ago'}; }
  const prio=ch=>({never:0,overdue:1,soon:2,fresh:3})[status(ch)];
  function flat(ps){ const o=[]; (ps||papers).forEach((p,pi)=>p.subjects.forEach((s,si)=>s.chapters.forEach(ch=>o.push({ch,paper:p.name,subject:s.name,pi,si})))); return o; }
  function cnt(list){ const c={overdue:0,soon:0,fresh:0,never:0,t:list.length}; list.forEach(x=>c[status(x.ch||x)]++); c.started=c.t-c.never; c.pct=c.t?Math.round(c.started/c.t*100):0; return c; }
  function find(id){ for(const p of papers) for(const s of p.subjects){ const i=s.chapters.findIndex(c=>c.id===id); if(i>-1) return {s,i,ch:s.chapters[i]}; } }

  /* ---------- DASHBOARD ---------- */
  function ringSvg(c){ const R=56, C=2*Math.PI*R; let off=0; const seg=(n,col)=>{ const len=c.t?n/c.t*C:0; const el=`<circle cx="70" cy="70" r="${R}" stroke="${col}" stroke-dasharray="${len} ${C-len}" stroke-dashoffset="${-off}"/>`; off+=len; return el; };
    return `<svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="${R}" stroke="var(--track)"/>${seg(c.fresh,COL.fresh)}${seg(c.soon,COL.soon)}${seg(c.overdue,COL.overdue)}</svg>`; }
  function renderDash(){
    const all=flat(), c=cnt(all), week=all.filter(x=>{const d=daysSince(x.ch.lastRevised);return d!==null&&d<=6;}).length;
    const h=new Date().getHours(), greet=h<12?'Good morning':h<17?'Good afternoon':'Good evening';
    const today=new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'});
    const left=`<div class="dcol"><div class="hello"><h2>${greet} 👋</h2><p>${today} · here is where your Mains preparation stands</p></div>
      <div class="ringwrap"><div class="ring">${ringSvg(c)}<div class="rc"><b>${c.pct}%</b><span>started</span></div></div>
      <div class="big">You have started <b>${c.started}</b> of <b>${c.t}</b> topics.<br><b>${c.never}</b> still to begin.</div></div>
      <div class="chips">
        <button class="chip" onclick="MainsTool.go(-1,-1,'overdue')"><i style="background:${COL.overdue}"></i><b>${c.overdue}</b><span>Overdue<br>15+ days</span></button>
        <button class="chip" onclick="MainsTool.go(-1,-1,'soon')"><i style="background:${COL.soon}"></i><b>${c.soon}</b><span>Due soon<br>8–14 days</span></button>
        <button class="chip" onclick="MainsTool.go(-1,-1,'fresh')"><i style="background:${COL.fresh}"></i><b>${c.fresh}</b><span>Recently revised<br>0–7 days</span></button>
        <button class="chip" onclick="MainsTool.go(-1,-1,'never')"><i style="background:${COL.never}"></i><b>${c.never}</b><span>Not started<br>yet</span></button>
      </div><div style="font-size:12px;color:var(--muted);margin-top:12px">📅 ${week} topic${week===1?'':'s'} revised in the last 7 days</div></div>`;
    const mk=MARKS.map(m=>({...m,n:all.filter(x=>x.ch.marks&&x.ch.marks[m.k]).length}));
    const stat=`<div class="dcol"><h3>✅ Study status</h3><div class="sub">Your own Studied · Notes · R1 · R2 · R3 marks across all ${c.t} topics.</div>`+
      mk.map(m=>{ const pc=c.t?Math.round(m.n/c.t*100):0; return `<div class="srow"><span class="sc" style="--c:${m.c}">✓</span><div class="sbody"><div class="stop"><b>${m.l}</b><span>${m.n} / ${c.t} · ${pc}%</span></div><div class="sbar2"><i style="width:${pc}%;background:${m.c}"></i></div></div></div>`; }).join('')+`</div>`;
    const right=`<div class="dcol"><h3>📘 Your papers</h3><div class="sub">Tap a paper to open its topics.</div><div class="papers">`+
      (papers.map((p,i)=>{ const pc=cnt(flat([p])); const w=n=>(pc.t?n/pc.t*100:0).toFixed(1)+'%'; const need=pc.overdue+pc.soon;
        return `<div class="prow" style="--pc:${pcol(p.name,i)}" onclick="MainsTool.go(${i},-1,'all')"><div class="prtop"><span class="pn">${esc(p.name)}</span><span class="pr">${pc.started}/${pc.t}${need?` · <span style="color:${COL.overdue}">${need} due</span>`:''}</span><span class="pp">${pc.pct}%</span></div>
          <div class="sbar"><i style="width:${w(pc.fresh)};background:${COL.fresh}"></i><i style="width:${w(pc.soon)};background:${COL.soon}"></i><i style="width:${w(pc.overdue)};background:${COL.overdue}"></i></div>
          </div>`; }).join('')||'<div class="empty-d">No papers yet.</div>')+`</div></div>`;
    let html=`<div class="dgrid3">${left}${stat}${right}</div>`;
    let need=all.filter(x=>{const s=status(x.ch);return s==='overdue'||s==='soon';}).sort((a,b)=>daysSince(b.ch.lastRevised)-daysSince(a.ch.lastRevised)).slice(0,6);
    let fill=[]; if(need.length<6) fill=all.filter(x=>status(x.ch)==='never').slice(0,6-need.length);
    const row=(x,kind)=>{ const b=badge(x.ch); return `<div class="rn"><span class="dot" style="background:${COL[b.cls]}"></span><div class="rtxt" onclick="MainsTool.open('${x.ch.id}')"><div class="rname">${esc(x.ch.name)}</div><div class="rmeta">${esc(x.paper)} › ${esc(x.subject)} · ${b.text}</div></div><button class="donebtn" onclick="MainsTool.markToday('${x.ch.id}')">${kind==='start'?'▶ Start today':'✓ Revised today'}</button></div>`; };
    html+=`<div class="dsec"><h3>🎯 What to do next</h3><div class="sub">${need.length?'Topics that are due for revision, oldest first.':'Nothing is overdue — nice! Here are topics to start.'}</div>`+
      (need.length+fill.length?`<div class="rngrid">${need.map(x=>row(x,'rev')).join('')+fill.map(x=>row(x,'start')).join('')}</div>`:'<div class="empty-d">No topics yet. Click a paper above to add some.</div>')+`</div>`;
    $('v-dash').innerHTML=html;
  }

  /* ---------- TOPICS ---------- */
  function renderTopics(){
    if(curP>=papers.length) curP=papers.length?0:-1;
    const P=papers[curP]; if(P&&curS>=P.subjects.length) curS=-1;
    const total=p=>p.subjects.reduce((a,s)=>a+s.chapters.length,0);
    $('paper-tabs').innerHTML=`<button class="tab${curP===-1?' active':''}" onclick="MainsTool.pick(-1)">⭐ All <span style="opacity:.6;font-size:11px">${flat().length}</span></button>`+
      papers.map((p,i)=>`<button class="tab ptab${i===curP?' active':''}" style="--pc:${pcol(p.name,i)}" onclick="MainsTool.pick(${i})">${esc(p.name)} <span style="opacity:.6;font-size:11px">${total(p)}</span><span class="tab-del" onclick="event.stopPropagation();MainsTool.delPaper(${i})" title="Remove paper">✕</span></button>`).join('');
    $('sub-row').style.display=(curP===-1||!P)?'none':'flex';
    if(P) $('subject-tabs').innerHTML=`<button class="tab sub${curS===-1?' active':''}" onclick="MainsTool.pickS(-1)">All subjects</button>`+
      P.subjects.map((s,i)=>`<button class="tab sub${i===curS?' active':''}" onclick="MainsTool.pickS(${i})">${esc(s.name)} <span style="opacity:.6;font-size:11px">${s.chapters.length}</span><span class="tab-del" onclick="event.stopPropagation();MainsTool.delSubject(${i})" title="Remove subject">✕</span></button>`).join('');
    let items=flat().filter(x=>curP===-1||(x.pi===curP&&(curS===-1||x.si===curS)));
    const c=cnt(items);
    $('topline').innerHTML=`<b>${c.started}</b> of <b>${c.t}</b> topics started (${c.pct}%)`;
    $('filter-sel').value=filter;
    const canAdd=true; renderAdd();
    if(filter!=='all') items=items.filter(x=>status(x.ch)===filter);
    const sort=$('sort-sel').value;
    if(sort==='priority') items=[...items].sort((a,b)=>prio(a.ch)-prio(b.ch)||(daysSince(b.ch.lastRevised)||0)-(daysSince(a.ch.lastRevised)||0));
    else if(sort==='name') items=[...items].sort((a,b)=>a.ch.name.localeCompare(b.ch.name));
    const list=$('chapter-list');
    if(!papers.length){ list.innerHTML='<div class="empty">No papers yet. Click “+ Paper”.</div>'; return; }
    if(!items.length){ list.innerHTML=`<div class="empty"><div class="empty-icon">📖</div>${filter!=='all'?'Nothing in this category.':(canAdd?'No microthemes yet. Type a name above and press Enter.':'Nothing here yet.')}</div>`; return; }
    list.innerHTML=items.map(({ch,paper,subject,pi})=>{
      const b=badge(ch), open=expanded[ch.id], rc=ch.revisionCount>0?`${ch.revisionCount}× revised`:'', py=ch.pyqs||[];
      const tag=curP===-1?`${esc(paper)} · ${esc(subject)}`:(curS===-1?esc(subject):'');
      return `<div class="ch-card ${b.cls}" id="card-${ch.id}"><div class="ch-head" onclick="MainsTool.toggle('${ch.id}')">
        <span class="ch-name">${esc(ch.name)}</span>${tag?`<span class="subject-tag pt" style="--pc:${pcol(papers[pi].name,pi)}">${tag}</span>`:''}
        ${py.length?`<span class="rev-count">${py.length} PYQ${py.length>1?'s':''}</span>`:''}${rc?`<span class="rev-count">${rc}</span>`:''}
        <span class="mdots">${MARKS.map(m=>`<i class="md md-${m.k}${ch.marks&&ch.marks[m.k]?' on':''}" style="--c:${m.c}" title="${m.l}"></i>`).join('')}</span>
        <span class="badge ${b.cls}">${b.text}</span>
        <div class="ch-actions" onclick="event.stopPropagation()"><button class="icon-btn" onclick="MainsTool.delChapter('${ch.id}')" title="Delete">✕</button><span class="chevron ${open?'open':''}">▼</span></div></div>
        ${open?`<div class="ch-body">
          <div class="field-row"><label>Study status</label><div class="marks">${MARKS.map(m=>`<button class="mk${ch.marks&&ch.marks[m.k]?' on':''}" style="--c:${m.c}" title="Click to mark ${m.l}" onclick="MainsTool.mark('${ch.id}','${m.k}',this)"><span class="mc">✓</span><span class="ml">${m.l}</span></button>`).join('')}</div></div>
          <div class="field-row"><label>Last revised</label><input type="date" value="${ch.lastRevised||''}" onchange="MainsTool.setField('${ch.id}','lastRevised',this.value)"><button class="hbtn primary" style="font-size:11px;padding:4px 10px" onclick="MainsTool.markToday('${ch.id}')">Mark today</button></div>
          <div class="field-row note-row"><label>Notes</label><textarea placeholder="Key points, keywords, examples…" onchange="MainsTool.setField('${ch.id}','note',this.value)">${esc(ch.note||'')}</textarea></div>
          ${py.length?`<div class="pyq-box"><div class="pyq-title">Previous year questions (2013–2025)</div>${py.map(q=>`<div class="pyq"><span class="pyq-meta">${esc(q[0])} · ${esc(q[1])}m</span>${esc(q[2])}</div>`).join('')}</div>`:''}
        </div>`:''}</div>`; }).join('');
  }
  function renderAdd(){
    if(!papers.length){ $('toolbar').style.display='none'; return; }
    $('toolbar').style.display='flex';
    if(addP<0||addP>=papers.length) addP=0;
    const P=papers[addP]; if(addS>=P.subjects.length||addS<0) addS=0;
    $('add-paper').innerHTML=papers.map((p,i)=>`<option value="${i}"${i===addP?' selected':''}>${esc(p.name)}</option>`).join('');
    $('add-subj').innerHTML=P.subjects.length?P.subjects.map((x,i)=>`<option value="${i}"${i===addS?' selected':''}>${esc(x.name)}</option>`).join(''):'<option value="-1">General (new subject)</option>';
  }
  function render(){
    $('v-dash').style.display=view==='dash'?'block':'none'; $('v-topics').style.display=view==='topics'?'block':'none';
    if(view==='dash') renderDash(); else renderTopics(); }
  function modal(title,ph,fn){
    $('mrev-modal-layer').innerHTML=`<div class="modal-bg" onclick="MainsTool.closeModal(event)"><div class="modal" onclick="event.stopPropagation()"><h3>${title}</h3><input id="m-in" placeholder="${ph}" onkeydown="if(event.key==='Enter')MainsTool.confirm()"><div class="modal-btns"><button class="hbtn" onclick="MainsTool.closeModal()">Cancel</button><button class="hbtn primary" onclick="MainsTool.confirm()">Add</button></div></div></div>`;
    MainsTool._fn=fn; setTimeout(()=>$('m-in')?.focus(),50); }
  return {
    init(data,onSave){ _onSave=onSave||null; const ok=!!(data&&Array.isArray(data.papers)); papers=mergeOptional(migrate(hydrate(ok?clone(data.papers):clone(MAINS_PRESET)))); curP=0;curS=-1;addP=0;addS=0;filter='all';expanded={};view='dash'; if(!ok) save(); render(); }, render,
    items(){ return flat().map(x=>({id:x.ch.id,name:x.ch.name,subject:x.subject,paper:x.paper,days:daysSince(x.ch.lastRevised)})).filter(x=>x.days!==null&&x.days>=8); },
    summary(){ const c=cnt(flat()); return {started:c.started,total:c.t,pct:c.pct,overdue:c.overdue,soon:c.soon,fresh:c.fresh,papers:papers.map((p,i)=>{const k=cnt(flat([p])); return {name:p.name,started:k.started,total:k.t,pct:k.pct,color:pcol(p.name,i)};})}; },
    setView(v){view=v;render();window.scrollTo(0,0)},
    go(p,s,f){ curP=p;curS=s;filter=f||'all'; if(p>=0){addP=p;addS=Math.max(0,s);}view='topics';render();window.scrollTo(0,0); },
    open(id){ const r=flat().find(x=>x.ch.id===id); if(!r) return; curP=r.pi;curS=r.si;addP=r.pi;addS=r.si;filter='all';expanded[id]=true;view='topics';render(); setTimeout(()=>$('card-'+id)?.scrollIntoView({behavior:'smooth',block:'center'}),50); },
    pick(i){curP=i;curS=-1; if(i>=0){addP=i;addS=0;} render()}, pickS(i){curS=i; if(i>=0) addS=i; render()},
    setAddPaper(v){addP=+v;addS=0;renderAdd()}, setAddSubj(v){addS=+v},
    mark(id,k,btn){ const r=find(id); if(!r) return; r.ch.marks=r.ch.marks||{}; r.ch.marks[k]=!r.ch.marks[k]; btn.classList.toggle('on',!!r.ch.marks[k]); const cd=btn.closest('.ch-card'); if(cd){const d=cd.querySelector('.md-'+k); if(d) d.classList.toggle('on',!!r.ch.marks[k]);} save(); },
    toggle(id){expanded[id]=!expanded[id];render()},
    setFilter(f){filter=f;render()},
    closeModal(e){ if(e&&e.target!==e.currentTarget) return; $('mrev-modal-layer').innerHTML=''; },
    confirm(){ const v=$('m-in')?.value.trim(); if(!v) return; if(MainsTool._fn(v)!==false){ MainsTool.closeModal(); save(); render(); } },
    addPaperModal(){ modal('Add paper','e.g. Optional Paper I',v=>{ if(papers.some(p=>p.name===v)){alert('Paper already exists.');return false;} papers.push({name:v,subjects:[]}); curP=papers.length-1; curS=-1; }); },
    addSubjectModal(){ if(curP===-1||!papers[curP]){alert('Select a paper first.');return;}
      modal('Add subject to '+esc(papers[curP].name),'e.g. Anthropology',v=>{ const P=papers[curP]; if(P.subjects.some(s=>s.name===v)){alert('Subject already exists.');return false;} P.subjects.push({name:v,chapters:[]}); curS=P.subjects.length-1; }); },
    delPaper(i){ const p=papers[i]; const n=flat([p]).length; if(!confirm(`Delete paper "${p.name}"${n?` with ${n} microtheme(s)`:''}?`)) return; papers.splice(i,1); curP=Math.min(curP,papers.length-1); curS=-1; save(); render(); },
    delSubject(i){ const s=papers[curP].subjects[i]; if(!confirm(`Delete subject "${s.name}"${s.chapters.length?` with ${s.chapters.length} microtheme(s)`:''}?`)) return; papers[curP].subjects.splice(i,1); curS=-1; save(); render(); },
    addChapter(){ const inp=$('ch-input'); const v=inp.value.trim(); if(!v||!papers.length) return;
      const P=papers[addP]; if(!P) return; if(!P.subjects.length){ P.subjects.push({name:'General',chapters:[]}); addS=0; }
      const S=P.subjects[addS]||P.subjects[0];
      S.chapters.push({id:'c'+Date.now(),name:v,lastRevised:'',status:'Not Started',note:'',revisionCount:0,marks:{},pyqs:[]});
      inp.value=''; curP=addP; curS=P.subjects.indexOf(S); save(); render(); $('ch-input').focus(); },
    setField(id,f,v){ const r=find(id); if(!r) return; if(f==='lastRevised'&&v&&v!==r.ch.lastRevised) r.ch.revisionCount=(r.ch.revisionCount||0)+1; r.ch[f]=v; save(); render(); },
    markToday(id){ MainsTool.setField(id,'lastRevised',new Date().toISOString().slice(0,10)); },
    delChapter(id){ const r=find(id); if(!r||!confirm(`Delete "${r.ch.name}"?`)) return; r.s.chapters.splice(r.i,1); delete expanded[id]; save(); render(); },
    resetPreset(){ if(!confirm('Replace ALL current data with the fresh Civilsdaily microthemes list? Your progress and notes will be lost.')) return; papers=mergeOptional(migrate(hydrate(clone(MAINS_PRESET)))); curP=0;curS=-1;addP=0;addS=0; save(); render(); },
    exportData(){ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([JSON.stringify({version:2,papers},null,2)],{type:'application/json'})); a.download='upsc-mains-revision-backup-'+new Date().toISOString().slice(0,10)+'.json'; a.click(); },
    importData(){ $('mrev-import-input').click(); },
    handleImport(e){ const f=e.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=ev=>{ try{ const d=JSON.parse(ev.target.result); let np;
        if(d.papers) np=d.papers; else if(d.subjects&&d.data) np=[{name:'Imported',subjects:d.subjects.map(s=>({name:s,chapters:(d.data[s]||[]).map(c=>({pyqs:[],...c}))}))}]; else throw 0;
        if(confirm('Replace current data with this backup?')){ papers=mergeOptional(migrate(hydrate(clone(np)))); curP=0;curS=-1; save(); render(); } }catch(x){alert('Invalid backup file.');} e.target.value=''; }; r.readAsText(f); }
  };
})();

window.MainsTool=MainsTool;
